INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do Python generators improve memory efficiency in data processing workflows?', '{"key_points": [{"id": "KP1", "description": "Explain lazy evaluation via the `yield` keyword and frame suspension vs eager list materialization.", "required": true, "acceptable_evidence": ["Technical keywords: yield, generator object, lazy evaluation, stack frame suspension (gi_frame), StopIteration.", "Explains that a generator function (`def` with `yield`) or generator expression `(x for x in data)` returns a lazy iterator that produces one item at a time on `next()`, suspending its local execution frame in memory rather than materializing the entire collection eagerly like a `list`."]}, {"id": "KP2", "description": "Contrast $O(1)$ auxiliary memory complexity of generator pipelines against $O(N)$ memory exhaustion (`MemoryError`) of list comprehensions.", "required": true, "acceptable_evidence": ["Technical keywords: O(1) auxiliary space vs O(N) RAM footprint, sys.getsizeof, MemoryError / OOMKilled prevention, multi-GB JSONL/CSV streaming.", "Explains that processing a 50 GB JSONL/Parquet stream or 100M database rows via `[transform(row) for row in file]` allocates $O(N)$ memory and triggers `MemoryError`/container `OOMKilled`, whereas a generator holds only the single active record or micro-batch in RAM ($O(1)$ space)."]}, {"id": "KP3", "description": "Chain composable generator stages (`read` -> `filter` -> `transform` -> `batch`) for pull-based streaming ETL and ML data loading.", "required": true, "acceptable_evidence": ["Technical keywords: generator pipeline chaining, itertools.islice, chunked batching, PyTorch IterableDataset, backpressure.", "Provides valid examples such as chaining generator stages to stream S3/local logs, filter malformed rows, yield fixed-size mini-batches via `itertools.islice` into vector database upserts or PyTorch `IterableDataset` loaders."]}, {"id": "KP4", "description": "Identify generator limitations (single-pass exhaustion, no random indexing `gen[i]`, no `len()`) and resource cleanup (`try...finally` / `contextlib.closing`).", "required": false, "acceptable_evidence": ["Technical keywords: single-pass exhaustion, TypeError on len()/indexing, generator.close(), GeneratorExit, context manager file closure.", "Explains that generators are single-use iterators that cannot be indexed or iterated twice without re-instantiation, and file-backed generators must wrap handles in `with open(...)` so `generator.close()` cleanly releases OS descriptors."]}], "critical_failures": ["Calls `list(generator)` at the start of the pipeline, immediately materializing all elements in RAM and negating all memory efficiency.", "Claims generators speed up CPU arithmetic rather than reducing peak memory allocation and time-to-first-element latency."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do React components communicate with each other using props, and what is the role of default props?', '{"key_points": [{"id": "KP1", "description": "Explain unidirectional parent-to-child data flow via immutable `props`.", "required": true, "acceptable_evidence": ["Technical keywords: unidirectional data flow, parent-to-child props, read-only immutability, pure rendering.", "Explains that React enforces one-way data binding where a parent component passes data, configuration, or JSX `children` down to child components as read-only `props` object attributes that the child must never mutate directly."]}, {"id": "KP2", "description": "Explain child-to-parent and sibling communication via callback function props and lifting state up.", "required": true, "acceptable_evidence": ["Technical keywords: callback function props (onSelect, onSubmit), lifting state up, sibling communication via shared parent, Context API (avoiding prop drilling).", "Explains that children communicate events or state changes upward by invoking callback functions passed down as props from the parent, while sibling components communicate by lifting shared state to their closest common ancestor (or React Context for deep trees)."]}, {"id": "KP3", "description": "Explain the role of default props (ES6 destructuring defaults vs legacy `defaultProps`) in preventing `undefined` runtime errors.", "required": true, "acceptable_evidence": ["Technical keywords: ES6 default parameter destructuring ({ variant = ''primary'', items = [] }), undefined fallback, React 18/19 defaultProps deprecation on function components.", "Explains that default prop values guarantee safe fallback behavior when optional props are omitted or explicitly passed as `undefined` (preventing `TypeError: Cannot read properties of undefined`), noting that modern React function components use ES6 destructuring defaults (`function Button({ size = ''md'' })`) rather than legacy `Component.defaultProps`."]}], "critical_failures": ["Mutates `props` directly inside a child component (`props.count++`) instead of invoking a state-updating callback from the parent.", "Claims ES6 default parameters trigger when `null` is passed (in JavaScript, default values only trigger when the prop is `undefined`, not `null`)."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you adapt your communication style when interviewers ask you to explain versus focus only on coding?', '{"key_points": [{"id": "KP1", "description": "Structure the ''Explain-First / Collaborative'' mode: clarify constraints, compare algorithmic trade-offs ($O(T)$ vs $O(S)$), and narrate design invariants.", "required": true, "acceptable_evidence": ["Technical keywords: constraint clarification, brute-force vs optimal trade-off, time/space complexity Big-O, invariant narration, dry-run trace.", "Explains that when an interviewer requests explanation, communication focuses on high-signal architectural reasoning—stating input assumptions, contrasting candidate data structures (e.g., hash map $O(N)$ vs sorting $O(N \\\\log N)$), getting buy-in on the approach before typing, and explaining *why* a branch handles an edge case rather than reading syntax line-by-line."]}, {"id": "KP2", "description": "Adapt to ''Focus-on-Coding / Heads-Down'' mode: confirm a 30-second high-level contract, write self-documenting typed Python, and give brief milestone checkpoints.", "required": true, "acceptable_evidence": ["Technical keywords: concise alignment check, self-documenting code, Python type hints, descriptive variable names, milestone checkpoints.", "Explains that when an interviewer asks to focus strictly on coding (common under tight time limits), you confirm the function signature in 30 seconds, shift to rapid implementation using clear variable names, modular helper functions, and Python type annotations so the code speaks for itself, and offer 10-second checkpoints only at major transitions."]}, {"id": "KP3", "description": "Read interviewer cues dynamically and close both modes with deterministic test verification.", "required": true, "acceptable_evidence": ["Technical keywords: interviewer cue calibration, time-budget awareness, assert test cases, edge-case validation.", "Explains monitoring verbal/non-verbal cues (e.g., if the interviewer interrupts to ask ''what is the complexity?'' vs ''let''s see the code running'') and always concluding with concise `assert` test cases covering happy paths and edge cases."]}], "critical_failures": ["Continues talking at length about theoretical tangents after the interviewer explicitly asks to focus on writing the code, running out the clock.", "Goes completely silent for 30 minutes without first confirming requirements or writing readable, modular code."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you approach understanding a new codebase and integrating it into an existing system using AI-assisted development tools?', '{"key_points": [{"id": "KP1", "description": "Map the system boundaries, entrypoints, dependency manifests, and test suites before modifying code.", "required": true, "acceptable_evidence": ["Technical keywords: dependency manifest (pyproject.toml, package.json, Dockerfile), API entrypoints, database migrations, pytest test suite, architecture mapping.", "Explains starting with deterministic artifacts (`pyproject.toml`, `Dockerfile`, `docker-compose.yml`, API routers, DB schemas, and existing `pytest` suites) and using workspace-indexed AI tools (Cursor / Claude Code / GitHub Copilot Workspace) to trace call graphs from HTTP/CLI entrypoints down to data persistence."]}, {"id": "KP2", "description": "Verify AI-generated architectural summaries empirically via execution traces, debuggers, and existing unit/integration tests.", "required": true, "acceptable_evidence": ["Technical keywords: empirical verification, debugger breakpoints, OpenTelemetry / log tracing, hallucination check on legacy symbols.", "Explains never trusting AI codebase explanations blindly: running the test suite locally, stepping through a single end-to-end request with a debugger or log trace, and confirming side effects, global state, and implicit configuration."]}, {"id": "KP3", "description": "Design an Anti-Corruption / Adapter Layer (`Protocol` / Pydantic interface) to integrate the new module cleanly without tight coupling.", "required": true, "acceptable_evidence": ["Technical keywords: Adapter / Facade pattern, Anti-Corruption Layer (ACL), Python typing.Protocol / ABC, Pydantic boundary validation, dependency conflicts.", "Explains isolating the integrated codebase behind an explicit interface or Anti-Corruption Layer (`Protocol` + Pydantic DTOs) so internal data models, exception types, or dependency version differences do not leak across system boundaries."]}, {"id": "KP4", "description": "Write characterization and integration contract tests (`pytest`) and roll out behind feature flags.", "required": true, "acceptable_evidence": ["Technical keywords: characterization tests, contract tests, pytest fixtures, feature flag / canary toggle, CI/CD regression gate.", "Explains using AI assistants to scaffold characterization tests that lock in existing behavior before refactoring, writing integration tests across the adapter boundary, and deploying the integration behind a feature flag."]}], "critical_failures": ["Prompts an AI assistant to bulk-refactor or merge an unfamiliar codebase into production without running tests or understanding side effects.", "Tightly couples internal classes of the new codebase directly into core domain logic without an adapter boundary or schema validation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you build responsive user interfaces in React using CSS frameworks like Tailwind CSS?', '{"key_points": [{"id": "KP1", "description": "Apply Tailwind''s Mobile-First breakpoint system (`sm:`, `md:`, `lg:`, `xl:`, `2xl:`) where unprefixed utilities target mobile viewports.", "required": true, "acceptable_evidence": ["Technical keywords: mobile-first min-width media queries, unprefixed base mobile classes, sm: (640px), md: (768px), lg: (1024px), xl: (1280px).", "Explains that Tailwind uses `min-width` mobile-first breakpoints: unprefixed classes (e.g., `grid-cols-1 p-4`) style the smallest mobile screen by default, while prefixed utilities (`md:grid-cols-2 lg:grid-cols-4 lg:p-8`) progressively override layout at larger viewports."]}, {"id": "KP2", "description": "Combine CSS Grid, Flexbox, Container Queries (`@container`), and fluid typography/spacing (`clamp`, `rem`, `max-w-*`, `min-h-dvh`).", "required": true, "acceptable_evidence": ["Technical keywords: Flexbox (flex-col md:flex-row), CSS Grid (grid-cols-*), container queries (@container / @md:), dvh/svh viewport units, aspect-ratio.", "Explains structuring macro page layouts with responsive CSS Grid and micro component alignment with Flexbox, using `@container` queries so reusable React cards adapt to their parent container width (e.g., collapsible AI chat sidebar vs main dashboard) rather than just global screen width."]}, {"id": "KP3", "description": "Encapsulate reusable React component variants cleanly using `clsx` / `tailwind-merge` (`cn`) and `tailwind.config` design tokens.", "required": true, "acceptable_evidence": ["Technical keywords: tailwind-merge, clsx, class-variance-authority (cva), tailwind.config.js theme tokens, PurgeCSS/JIT tree-shaking, no dynamic string concatenation.", "Explains composing conditional classes in React via `twMerge(clsx(...))` and `cva`, avoiding dynamically concatenated class names (`col-span-${n}`) that Tailwind''s static JIT compiler cannot detect at build time."]}], "critical_failures": ["Misinterprets `sm:` as ''only on small mobile screens'' rather than `min-width: 640px` and above.", "Constructs dynamic Tailwind class strings via template interpolation (`bg-${color}-500`), causing styles to be stripped in production builds."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do you manage dependency conflicts between different Python projects on the same machine?', '{"key_points": [{"id": "KP1", "description": "Isolate per-project site-packages and Python interpreter versions using Virtual Environments (`uv`, `venv`, `Poetry`, `Conda`) and `pyenv`.", "required": true, "acceptable_evidence": ["Technical keywords: python -m venv, uv venv, Poetry, Conda, pyenv, isolated site-packages, sys.path, PATH activation.", "Explains never installing packages into the global system Python: each project gets an isolated `.venv` directory with its own `site-packages` and `bin/python` symlink (and `pyenv` or `uv python pin` when Project A requires Python 3.10 and Project B requires Python 3.12)."]}, {"id": "KP2", "description": "Enforce deterministic transitive dependency resolution using `pyproject.toml` and hash-pinned lockfiles (`uv.lock`, `poetry.lock`, `pip-compile`).", "required": true, "acceptable_evidence": ["Technical keywords: pyproject.toml, uv.lock, poetry.lock, pip-tools (pip-compile), transitive dependency SAT solver, pipdeptree.", "Explains separating direct semantic constraints in `pyproject.toml` from exact resolved transitive versions and cryptographic SHA-256 hashes in a committed lockfile (`uv.lock` / `poetry.lock`), using `pipdeptree` or `uv tree` to inspect and resolve diamond dependency conflicts (e.g., conflicting `pydantic` or `numpy` bounds)."]}, {"id": "KP3", "description": "Isolate conflicting OS-level C/C++ shared libraries and CUDA toolkits using Docker / DevContainers.", "required": true, "acceptable_evidence": ["Technical keywords: Docker containers, DevContainers, CUDA/cuDNN version conflicts, OS shared libraries (libGL, glibc), pipx (CLI tools).", "Explains that Python `venv` only isolates Python packages, not system-level C binaries or GPU drivers; when two ML projects require incompatible CUDA/TensorRT or OS libraries, Docker containers (or VS Code DevContainers) provide full filesystem and library isolation."]}], "critical_failures": ["Installs project packages globally using `sudo pip install` or shares a single virtual environment across multiple unrelated repositories.", "Uses unpinned `requirements.txt` files without locking transitive dependencies, leading to broken builds when upstream sub-dependencies release breaking versions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you manage version control, testing, and code quality in ML projects using tools like Git, GitHub, and PyTest?', '{"key_points": [{"id": "KP1", "description": "Manage code and data/model version control via Git/GitHub trunk-based PR workflows, `nbstripout`, and DVC/MLflow lineage.", "required": true, "acceptable_evidence": ["Technical keywords: Git/GitHub branch protection, Pull Request reviews, nbstripout / Jupytext, DVC (.dvc pointers), MLflow commit SHA tagging.", "Explains enforcing protected `main` branches with mandatory PR reviews, stripping noisy Jupyter notebook output cells via `nbstripout` (or refactoring notebooks into `src/` Python modules), and keeping large datasets/weights out of Git via `.gitignore` + DVC S3 pointers."]}, {"id": "KP2", "description": "Structure a multi-layered `pytest` suite covering feature transformations, data schema contracts, and model behavioral invariants.", "required": true, "acceptable_evidence": ["Technical keywords: pytest, @pytest.fixture, @pytest.mark.parametrize, Pandera/Great Expectations data contracts, model shape/NaN/latency tests, FastAPI TestClient.", "Explains writing parameterized `pytest` unit tests for feature engineering edge cases (nulls, divide-by-zero, unseen categories, temporal boundaries), schema validation tests (`Pandera`), model behavioral smoke tests (output probability $\\\\in [0, 1]$, no NaNs, deterministic seed parity, single-batch overfitting test), and API contract tests."]}, {"id": "KP3", "description": "Enforce static code quality and security checks locally via `pre-commit` and in GitHub Actions CI (`ruff`, `black`, `mypy`, `bandit`).", "required": true, "acceptable_evidence": ["Technical keywords: pre-commit hooks, GitHub Actions CI, ruff / flake8, black / isort, mypy static type checking, pytest-cov coverage gate, bandit/gitleaks.", "Explains running fast linters, formatters, secret scanners (`gitleaks`), and `mypy` type checks on every commit via `pre-commit` and blocking GitHub PR merges in GitHub Actions if `pytest` or coverage thresholds fail."]}, {"id": "KP4", "description": "Separate fast CPU unit tests (run on every PR commit) from heavy GPU/golden-dataset evaluation tests.", "required": false, "acceptable_evidence": ["Technical keywords: pytest custom markers (@pytest.mark.slow / @pytest.mark.integration), synthetic fixture data, Champion-vs-Challenger CI gate.", "Explains using small deterministic synthetic fixtures in PR unit tests so CI completes in <2 minutes, while gating model releases with full Out-Of-Time / Golden Dataset evaluation suites."]}], "critical_failures": ["Commits raw multi-gigabyte CSV/Parquet files, `.pkl` binaries, or unstripped Jupyter notebooks with embedded credentials directly into GitHub.", "Tests only standard HTTP status codes while leaving feature engineering transformations and training-serving parity untested."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do you mitigate risks associated with dynamic typing in Python using tools like type hints or runtime validation libraries?', '{"key_points": [{"id": "KP1", "description": "Recognize that standard Python type hints (`PEP 484`) are not enforced at runtime by CPython and require static analysis (`mypy` / `pyright`) in CI.", "required": true, "acceptable_evidence": ["Technical keywords: PEP 484 type annotations, typing (Protocol, TypedDict, Literal, Generic), mypy --strict, pyright, compile-time / CI static analysis.", "Explains that Python''s interpreter ignores function type annotations at runtime (`def add(a: int) -> int:` will still accept strings unless checked); enforcing `mypy --strict` or `pyright` in pre-commit and CI catches `None` dereferences (`Optional` mismatches), wrong argument types, and missing return paths before execution."]}, {"id": "KP2", "description": "Enforce strict runtime validation at external I/O boundaries (APIs, LLM JSON outputs, env vars) using `Pydantic` (`BaseModel`, `Field`, `@field_validator`).", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic v2 BaseModel, ConfigDict(strict=True, extra=''forbid''), Field constraints, @field_validator, @model_validator, BaseSettings.", "Explains that static type checkers cannot know what untrusted JSON payloads arrive over HTTP, Kafka, or LLM tool calls at runtime; `Pydantic` parses and validates external inputs at the boundary, failing fast with structured `ValidationError` details."]}, {"id": "KP3", "description": "Validate tabular DataFrame schemas (`Pandera`) in data/ML pipelines to prevent silent type coercion and NaN propagation.", "required": true, "acceptable_evidence": ["Technical keywords: Pandera DataFrameModel, column dtype enforcement, nullable=False, range checks, training-serving feature contract.", "Explains using `Pandera` (`pa.DataFrameModel`) at Pandas/PySpark/Polars pipeline boundaries to validate column dtypes, nullability, and value bounds before feeding arrays into ML models."]}], "critical_failures": ["Believes that adding `: int` type hints to a Python function automatically raises a `TypeError` at runtime without `mypy` or a runtime validator like `Pydantic`.", "Passes raw unvalidated `dict` payloads from external APIs or LLM outputs deep into core business logic."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you prepare for interview processes that focus more on deep discussion of experience rather than coding?', '{"key_points": [{"id": "KP1", "description": "Map end-to-end architecture blueprints of core production systems (data flow, control flow, latency budgets, and failure modes).", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end system architecture, ingestion-to-serving data flow, P95 latency breakdown, bottleneck analysis, failure modes.", "Explains preparing detailed mental and visual architectural diagrams of 3–4 flagship projects (e.g., Hybrid RAG / Agentic AI platform, Fraud Detection MLOps pipeline), ready to trace a single request from API gateway through feature/vector stores, model inference, and observability."]}, {"id": "KP2", "description": "Prepare explicit ''Why X over Y'' trade-off analyses and root-cause debugging stories.", "required": true, "acceptable_evidence": ["Technical keywords: architectural trade-offs (Why X over Y), rejected alternatives, production incident RCA, scaling/cost bottlenecks.", "Explains reviewing every major technical decision to articulate why a specific tool or algorithm was chosen over alternatives (e.g., LoRA vs Full SFT, Hybrid BM25+Vector vs Dense-only, EKS vs SageMaker, XGBoost vs Deep Learning) and preparing real production failures and how they were diagnosed and fixed."]}, {"id": "KP3", "description": "Anchor every experience narrative with concrete quantitative metrics (baseline vs post-deployment KPIs) and clear individual ownership (''I'' vs ''We'').", "required": true, "acceptable_evidence": ["Technical keywords: quantitative metrics (PR-AUC, Faithfulness, P95 latency, cost reduction), STAR + Technical Depth, individual ownership (''I architected'' vs team scope).", "Explains quantifying before-and-after metrics (e.g., improving retrieval Recall@5 from 0.68 to 0.89, cutting P95 latency from 2.4s to 650ms) and clearly distinguishing personal engineering contributions from broader team scope."]}, {"id": "KP4", "description": "Use custom hierarchy customizers or `@property` validators to enforce runtime invariants on subclasses.", "required": false, "acceptable_evidence": ["Technical keywords: `__init_subclass__`, `@property` setter validation, Liskov Substitution Principle (LSP).", "Explains using `__init_subclass__` or property setters to validate class attributes and ensure subclasses preserve parent contract invariants."]}, {"id": "KP5", "description": "Optimize memory layout on high-volume object hierarchies using `__slots__` across parent and child classes.", "required": false, "acceptable_evidence": ["Technical keywords: `__slots__`, per-instance `__dict__` elimination, subclass slot inheritance rules.", "Explains declaring `__slots__` in both base and derived classes (with `slots=True` in dataclasses) to eliminate per-instance `__dict__` overhead."]}], "critical_failures": ["Recites high-level resume bullet points using ''we'' for everything without being able to explain internal mechanics, failure modes, or personal ownership.", "Cannot explain why specific architectural choices were made or what trade-offs were accepted."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you set up a new React project, including tooling and initial project structure?', '{"key_points": [{"id": "KP1", "description": "Select a modern build/framework toolchain (`Vite` for SPAs or `Next.js` for SSR/App Router) with strict `TypeScript` (`tsconfig.json` `strict: true`).", "required": true, "acceptable_evidence": ["Technical keywords: Vite (ESBuild/Rollup) vs Next.js (SSR/RSC), TypeScript strict mode, pnpm/npm lockfile, deprecation of Create React App (CRA).", "Explains scaffolding with `Vite` (`npm create vite@latest -- --template react-ts`) for fast HMR Single-Page Applications or `Next.js` when SSR/SEO/server actions are needed, avoiding deprecated `create-react-app`, and enabling `strict: true` and path aliases (`@/*`) in `tsconfig.json`."]}, {"id": "KP2", "description": "Organize a scalable Feature-Based directory structure separating domain features from shared UI primitives, API clients, and hooks.", "required": true, "acceptable_evidence": ["Technical keywords: feature-based architecture (src/features/<domain>/), src/components/ui, src/lib/api, TanStack Query (React Query) vs Zustand/Context, React Router.", "Explains structuring `src/` by domain (`src/features/chat/`, `src/features/analytics/` colocating feature components, hooks, types, and tests) alongside shared `src/components/ui/` primitives, typed `axios`/`fetch` clients with `TanStack Query` for server-state caching, and environment variable validation (`import.meta.env`)."]}, {"id": "KP3", "description": "Configure code quality, styling, and testing automation (`ESLint`, `Prettier`, `Tailwind CSS`, `Vitest` + `React Testing Library`, `Husky` pre-commit).", "required": true, "acceptable_evidence": ["Technical keywords: ESLint (eslint-plugin-react-hooks, jsx-a11y), Prettier, Husky + lint-staged, Vitest, React Testing Library, Playwright.", "Explains wiring `ESLint` (enforcing Rules of Hooks and accessibility), `Prettier`, `Husky` + `lint-staged` pre-commit hooks, and `Vitest` + `React Testing Library` into the CI pipeline from day one."]}], "critical_failures": ["Recommends the deprecated `create-react-app` (CRA) toolchain or puts hundreds of unrelated components into a single flat `components/` folder without domain separation.", "Stores server API response caches manually inside global Redux/Context state without request deduplication, error boundaries, or TypeScript validation."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How have you mentored junior engineers through planning, code reviews, documentation, or internal knowledge sharing?', '{"key_points": [{"id": "KP1", "description": "Guide junior engineers during sprint planning and design decomposition (breaking ambiguous epics into vertical, testable milestones with RFCs/ADRs).", "required": true, "acceptable_evidence": ["Technical keywords: task decomposition, lightweight RFC / design doc, acceptance criteria, edge-case identification before coding, pair design.", "Explains mentoring juniors to write a brief 1-page design note (inputs/outputs, Pydantic schemas, failure modes, test plan) before writing code, helping them decompose large features into small, independently testable PRs."]}, {"id": "KP2", "description": "Use Code Reviews as a teaching multiplier (explaining the *why* behind architectural, complexity, and safety feedback while automating style nits in CI).", "required": true, "acceptable_evidence": ["Technical keywords: educational PR reviews, blocking vs non-blocking comments (nit/suggestion), algorithmic complexity, concurrency/leakage pitfalls, automated linting.", "Explains offloading formatting/style rules to `ruff`/`black`/`ESLint` in CI so human code reviews focus on high-leverage learning: data leakage risks, $O(N^2)$ bottlenecks, exception safety, and test coverage—always explaining the underlying principle and linking reference patterns."]}, {"id": "KP3", "description": "Institutionalize living documentation (onboarding guides, Architecture Decision Records, incident runbooks) and brown-bag tech talks.", "required": true, "acceptable_evidence": ["Technical keywords: Architecture Decision Records (ADRs), operational runbooks, onboarding playbook, blameless post-mortems, pair programming / mob debugging.", "Explains having mentees update onboarding docs with fresh eyes, co-authoring production runbooks, and running internal deep-dive sessions (e.g., walking through RAG evaluation metrics, PySpark partition skew, or LangGraph state debugging)."]}], "critical_failures": ["Micromanages or rewrites the junior engineer''s code directly instead of guiding them to understand the root cause and fix it themselves.", "Uses code reviews only to nitpick whitespace/formatting without mentoring on system design, testing, or edge cases."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How have you used AI tools to improve code quality, and what limitations required manual intervention?', '{"key_points": [{"id": "KP1", "description": "Leverage AI tools for high-leverage quality improvements: parameterized unit test generation (`pytest`), static type annotation (`mypy`), Pydantic schemas, and refactoring boilerplate.", "required": true, "acceptable_evidence": ["Technical keywords: pytest edge-case generation, property-based tests (Hypothesis), Pydantic schema scaffolding, Python type hint migration, docstring/OpenAPI generation.", "Explains using AI coding tools (Cursor, Claude Code, GitHub Copilot) to rapidly generate comprehensive `pytest.mark.parametrize` suites covering boundary conditions, add strict type annotations to legacy functions, and flag cyclomatic complexity during pre-PR self-review."]}, {"id": "KP2", "description": "Identify critical AI limitations requiring manual intervention: cross-service architectural invariants, subtle concurrency/async bugs, and ML data leakage.", "required": true, "acceptable_evidence": ["Technical keywords: blocking event loop in async def, race conditions, temporal/target leakage in ML, N+1 database queries, multi-service state invariants.", "Explains where AI assistants consistently fail and require human engineering intervention: (1) calling synchronous blocking I/O inside FastAPI `async def` routes, (2) introducing subtle temporal leakage in ML feature joins or fitting scalers before splitting, and (3) generating $O(N^2)$ or N+1 query loops that pass toy tests but fail at production scale."]}, {"id": "KP3", "description": "Identify package/API hallucination (`slopsquatting`), outdated library idioms (e.g., Pydantic v1 vs v2), and security antipatterns.", "required": true, "acceptable_evidence": ["Technical keywords: hallucinated APIs/packages, Pydantic v1 vs v2 deprecation, SQL injection / BOLA vulnerabilities, hardcoded defaults.", "Explains that LLMs frequently mix deprecated library syntax (e.g., Pydantic v1 `@validator` instead of v2 `@field_validator`, or LangChain legacy chains) or omit tenant RBAC checks (`tenant_id` scoping), requiring manual correction."]}, {"id": "KP4", "description": "Enforce deterministic verification gates (linters, type checkers, SAST security scanners, and line-by-line human diff review).", "required": true, "acceptable_evidence": ["Technical keywords: ruff, mypy, pytest, bandit/Semgrep SAST, human PR review ownership.", "Explains that AI-generated code is treated as untrusted draft code that must pass `ruff`, `mypy --strict`, `pytest`, security scans, and human architectural review before merging."]}], "critical_failures": ["Merges AI-generated code directly into production without reading every line of the diff or running automated test suites.", "Claims AI coding assistants have no technical limitations or can autonomously guarantee security and distributed system invariants."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'BROAD', 210, 'If I have a million chatbots and I want my users to do a thousand things using a ReAct pattern with a thousand tools, do you see any problems with that approach?', '{"key_points": [{"id": "KP1", "description": "Diagnose Context Window Exhaustion and Attention Degradation from injecting 1,000 tool JSON schemas into every prompt.", "required": true, "acceptable_evidence": ["Technical keywords: tool schema bloat (100k-250k tokens per turn), lost-in-the-middle attention degradation, tool selection accuracy collapse (>15-20 tools).", "Explains that 1,000 JSON Schema tool definitions consume 100,000–250,000+ input tokens on every single ReAct reasoning step—blowing past context budgets and causing severe tool-selection accuracy collapse (LLM tool routing degrades sharply beyond ~15–20 simultaneous tools due to overlapping descriptions)."]}, {"id": "KP2", "description": "Diagnose Compounding Multi-Step ReAct Latency, Token Cost Explosion, and Looping Failures at 1M-Chatbot Scale.", "required": true, "acceptable_evidence": ["Technical keywords: sequential Thought-Action-Observation latency compounding, $O(k \\\\times N)$ token cost explosion, TPM/RPM quota exhaustion, infinite ReAct loops.", "Explains that each ReAct iteration re-sends the entire prompt + 1,000 tool schemas + growing scratchpad: a 5-step ReAct loop across millions of users multiplies token spend by orders of magnitude, exhausts provider TPM quotas (`HTTP 429`), and creates 15–30s latencies and cascading hallucinated tool calls."]}, {"id": "KP3", "description": "Diagnose the Security & Blast-Radius Nightmare of granting a single autonomous ReAct agent access to 1,000 tools.", "required": true, "acceptable_evidence": ["Technical keywords: Confused Deputy / Excess Agency, violation of Least Privilege, prompt injection blast radius, destructive tool execution.", "Explains that giving one agent all 1,000 tools violates the Principle of Least Privilege: a single prompt injection in a read-only summarization task could trick the ReAct loop into invoking destructive billing, account-deletion, or admin tools."]}, {"id": "KP4", "description": "Architect the Solution (Part 1): Semantic Tool Retrieval (Dynamic Top-$K$ Tool RAG) and Hierarchical Domain Sub-Agents (LangGraph).", "required": true, "acceptable_evidence": ["Technical keywords: Semantic Tool Retriever (Vector/BM25 over MCP tool registry), top-k (5-10) dynamic tool injection, Hierarchical Supervisor / Domain Sub-Agents (LangGraph).", "Explains replacing the monolithic 1,000-tool prompt with: (1) an Intent Router / Supervisor that routes the request to a specialized Domain Sub-Agent (each scoped to 5–10 domain tools), or (2) a Semantic Tool Retriever that embeds the user query against the MCP tool catalog and dynamically binds only the top $K=5\\\\text{--}8$ relevant tool schemas for that turn."]}, {"id": "KP5", "description": "Architect the Solution (Part 2): Deterministic Workflow Fast-Paths, Bounded Graph Execution, and Per-Tenant RBAC/HITL.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic DAG fast-paths (bypassing free-form ReAct), recursion_limit, Redis semantic caching, out-of-band RBAC filtering, HITL approval.", "Explains converting common multi-step workflows into deterministic state-graph pipelines (`LangGraph`) rather than open-ended ReAct loops, filtering available tools by the user''s JWT RBAC claims before LLM binding, and enforcing `recursion_limit` and HITL gates on mutating tools."]}], "critical_failures": ["Claims that passing 1,000 tools to a single ReAct agent works fine as long as you use a model with a 1M–2M token context window.", "Ignores token cost multiplication, tool-selection confusion, latency compounding, and least-privilege security risks."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'In a Python script, what is the purpose of if __name__ == "__main__" and how does it work?', '{"key_points": [{"id": "KP1", "description": "Explain how the Python interpreter assigns the special `__name__` dunder variable on direct execution (`''__main__''`) versus module import (the module''s package/file name).", "required": true, "acceptable_evidence": ["Technical keywords: __name__ built-in attribute, ''__main__'', python script.py vs python -m pkg.mod vs import mod.", "Explains that before executing a `.py` file, CPython sets its global `__name__` variable to `''__main__''` if the file is run directly as the entrypoint (`python train.py` or `python -m src.train`), whereas if the file is imported by another module (`import src.train`), `__name__` is set to `''src.train''`."]}, {"id": "KP2", "description": "Explain how `if __name__ == ''__main__'':` prevents unintended side effects when importing functions/classes for `pytest` testing or library reuse.", "required": true, "acceptable_evidence": ["Technical keywords: import side-effect isolation, reusable module + CLI script, pytest test discovery.", "Explains that gating CLI argument parsing (`argparse`), server startup, or training execution inside `if __name__ == ''__main__'':` allows `pytest` and other modules to import classes and helper functions without accidentally triggering heavy execution at import time."]}, {"id": "KP3", "description": "Identify its critical role in preventing infinite process-spawning bombs in Python `multiprocessing` (on `spawn` platforms like Windows and macOS).", "required": false, "acceptable_evidence": ["Technical keywords: multiprocessing, spawn start method, RuntimeError, PyTorch DataLoader(num_workers > 0).", "Explains that when using `multiprocessing.Process` or `DataLoader(num_workers > 0)` with the `spawn` start method, child worker processes re-import the main module from scratch; without the `if __name__ == ''__main__'':` guard, each child recursively spawns new children infinitely."]}], "critical_failures": ["Claims `if __name__ == ''__main__'':` is a mandatory compiler entrypoint required for Python to parse a file (like `main()` in C/Java).", "Cannot explain what value `__name__` takes when the file is imported by another module."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'EASY', 'SPECIFIC', 60, 'What are Promises in JavaScript, and how does async/await improve asynchronous programming?', '{"key_points": [{"id": "KP1", "description": "Define a `Promise` as an object representing the eventual completion or failure of an asynchronous operation with three mutually exclusive states (`pending`, `fulfilled`, `rejected`).", "required": true, "acceptable_evidence": ["Technical keywords: Promise states (pending, fulfilled/resolved, rejected), immutable settlement, .then(), .catch(), .finally(), microtask queue.", "Explains that a Promise starts in `pending` state and settles once into either `fulfilled` (with a value) or `rejected` (with an error/reason), scheduling `.then()`/`.catch()` callbacks on the Event Loop''s high-priority Microtask Queue."]}, {"id": "KP2", "description": "Explain how `async`/`await` acts as syntactic sugar over Promises, enabling synchronous-looking control flow and unified `try / catch / finally` error handling.", "required": true, "acceptable_evidence": ["Technical keywords: async function (always returns a Promise), await suspension, callback hell / .then() pyramid elimination, unified try/catch/finally.", "Explains that marking a function `async` wraps its return value in a Promise, while `await` pauses execution of that function (without blocking the single-threaded JS call stack) until the awaited Promise settles—allowing both synchronous and asynchronous errors to be caught in standard `try/catch` blocks."]}, {"id": "KP3", "description": "Warn against the sequential `await` waterfall pitfall and use `Promise.all` / `Promise.allSettled` for concurrent independent I/O.", "required": true, "acceptable_evidence": ["Technical keywords: sequential await waterfall trap, Promise.all, Promise.allSettled, concurrent execution.", "Explains that awaiting independent API calls sequentially (`const a = await fetchA(); const b = await fetchB();`) sums their latencies, whereas `await Promise.all([fetchA(), fetchB()])` (or `Promise.allSettled` for partial-failure resilience) runs them concurrently."]}], "critical_failures": ["Claims `await` blocks the browser''s main UI thread or creates a new OS thread.", "Writes sequential `await` calls inside a `for` loop for independent requests instead of using `Promise.all`."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What are decorators and generators in Python, and how are they used to enhance or modify function behavior?', '{"key_points": [{"id": "KP1", "description": "Define Python Decorators (`@decorator`) as higher-order callables that wrap a function/class to add cross-cutting behavior without modifying its core body.", "required": true, "acceptable_evidence": ["Technical keywords: higher-order function, closure, @decorator syntactic sugar (fn = decorator(fn)), *args, **kwargs, functools.wraps.", "Explains that a decorator takes a callable, wraps it in an inner closure accepting `(*args, **kwargs)` to execute pre/post logic (e.g., `@retry`, `@lru_cache`, `@app.post` routing, RBAC auth checks, execution timing), and uses `@functools.wraps(func)` to preserve `__name__`, `__doc__`, and type signatures."]}, {"id": "KP2", "description": "Define Python Generators (`yield`) as functions that transform execution from eager single-return to lazy, stateful on-demand iteration.", "required": true, "acceptable_evidence": ["Technical keywords: yield keyword, generator iterator (__iter__, __next__), lazy evaluation, execution frame suspension, StopIteration.", "Explains that replacing `return` with `yield` turns a function into a generator factory that suspends local state between `next()` calls, streaming sequences lazily in $O(1)$ memory."]}, {"id": "KP3", "description": "Show how decorators and generators combine in practice (e.g., `@contextlib.contextmanager` and FastAPI `Depends` lifecycle dependencies).", "required": false, "acceptable_evidence": ["Technical keywords: @contextlib.contextmanager, yield resource management (setup before yield, teardown in finally), FastAPI Depends.", "Provides valid examples such as `@contextlib.contextmanager` (or FastAPI database session `Depends`), where a decorator transforms a single-`yield` generator into a `with` context manager handling setup before `yield` and guaranteed cleanup in a `finally` block after `yield`."]}], "critical_failures": ["Confuses decorators (wrapping a callable to augment behavior) with generators (yielding a lazy sequence of values).", "Omits `*args, **kwargs` or `@functools.wraps` when writing a general-purpose function decorator, breaking function arguments or metadata."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What are iterators and generators in Python, and how does the yield keyword work?', '{"key_points": [{"id": "KP1", "description": "Define an Iterator via Python''s Iterator Protocol (`__iter__` returning `self` and `__next__` returning the next element or raising `StopIteration`).", "required": true, "acceptable_evidence": ["Technical keywords: Iterator protocol, __iter__(), __next__(), StopIteration, stateful single-pass traversal.", "Explains that an iterator is any object implementing `__iter__()` (returning `self`) and `__next__()` (advancing internal cursor state to return the next value and raising `StopIteration` once exhausted)."]}, {"id": "KP2", "description": "Define a Generator as a concise implementation of the Iterator protocol where Python automatically generates `__iter__` and `__next__`. ", "required": true, "acceptable_evidence": ["Technical keywords: generator function, generator expression, every generator is an iterator, automatic __iter__/__next__ synthesis.", "Explains that every generator is an iterator (though not every iterator is a generator): instead of writing a verbose class with `__init__`, `__iter__`, and `__next__`, writing a function with `yield` (or `(x for x in seq)`) automatically produces a compliant iterator object."]}, {"id": "KP3", "description": "Trace how the `yield` keyword suspends and resumes stack frame state (`gi_frame`, instruction pointer, local variables) across `next()` calls.", "required": true, "acceptable_evidence": ["Technical keywords: yield suspension, stack frame preservation (local variables, instruction pointer), next(gen), yield from, StopIteration on return.", "Explains that calling a generator function does not run its body immediately; it returns a generator object. Each `next(gen)` call runs the code until it hits `yield val`, emits `val` to the caller while freezing all local variables and the instruction pointer in memory, and resumes from the exact line after `yield` on the subsequent `next()` until the function exits and raises `StopIteration`."]}], "critical_failures": ["Claims `yield` terminates the function permanently and destroys local variables like `return` does.", "Claims calling a generator function immediately executes the function body before `next()` or a `for` loop is invoked."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'What are the differences between synchronous and asynchronous functions in Python, and when would you use each?', '{"key_points": [{"id": "KP1", "description": "Contrast synchronous blocking execution (`def`) with asynchronous cooperative multitasking (`async def` coroutines, `await`, and the `asyncio` Event Loop).", "required": true, "acceptable_evidence": ["Technical keywords: blocking def vs non-blocking async def coroutine, asyncio event loop, await yield point, single-threaded cooperative multitasking, asyncio.gather.", "Explains that a synchronous `def` function blocks the calling OS thread until every operation finishes sequentially, whereas an `async def` function returns a coroutine object scheduled on a single-threaded `asyncio` event loop—suspending execution at `await` points during network/disk wait time so thousands of concurrent requests interleave without thread-switching overhead."]}, {"id": "KP2", "description": "Specify when to use `async def` (high-concurrency I/O-bound workloads: LLM APIs, vector DBs, Redis, SSE streaming) vs synchronous/multiprocess execution (CPU-bound ML/data compute).", "required": true, "acceptable_evidence": ["Technical keywords: I/O-bound concurrency (httpx, asyncpg, Redis, LLM streaming) vs CPU-bound workloads (NumPy, Pandas, XGBoost/PyTorch inference), ProcessPoolExecutor / asyncio.to_thread.", "Explains using `async def` with native async libraries (`httpx.AsyncClient`, `asyncpg`, `redis.asyncio`) for I/O-bound orchestration (RAG retrieval + LLM calls), while running CPU-bound tasks or legacy blocking SDKs (`boto3`, `requests`) via `asyncio.to_thread()` / `run_in_executor` or `ProcessPoolExecutor`."]}, {"id": "KP3", "description": "Explain the FastAPI event-loop blocking pitfall (putting blocking I/O or heavy CPU work inside `async def`).", "required": true, "acceptable_evidence": ["Technical keywords: event loop starvation, time.sleep vs asyncio.sleep, requests.get vs httpx.AsyncClient, FastAPI def threadpool behavior.", "Explains that calling blocking code (`time.sleep()`, `requests.get()`, or synchronous CPU model inference) directly inside an `async def` route freezes the entire `asyncio` event loop for all concurrent users, whereas FastAPI automatically runs standard `def` routes in an external threadpool (`anyio`)."]}], "critical_failures": ["Calls blocking `requests.get()`, `time.sleep()`, or heavy CPU-bound model inference directly inside an `async def` function without `asyncio.to_thread` / `run_in_executor`.", "Claims `async/await` automatically parallelizes CPU-bound matrix math across multiple CPU cores."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What are the limitations of current AI coding assistants in real-world codebases, and how do you mitigate those limitations?', '{"key_points": [{"id": "KP1", "description": "Identify context-window and cross-repository architectural blindness (missing implicit domain invariants, cross-service contracts, and runtime infrastructure constraints).", "required": true, "acceptable_evidence": ["Technical keywords: cross-repo architectural blindness, local-optimum patching, code duplication, implicit business invariants, distributed system state.", "Explains that AI assistants optimize locally for the open file/snippet and often miss cross-service side effects, existing internal utility libraries (duplicating helpers instead of reusing them), idempotency requirements, or production latency/memory budgets."]}, {"id": "KP2", "description": "Identify training-cutoff drift, hallucinated APIs/packages, and security/concurrency blind spots.", "required": true, "acceptable_evidence": ["Technical keywords: knowledge cutoff drift, deprecated SDK methods (Pydantic v1 vs v2, LangChain v0.1 vs v0.3), hallucinated packages, BOLA/SQLi/race conditions.", "Explains that assistants frequently emit deprecated library syntax from pre-cutoff training data, invent non-existent method signatures, or generate happy-path code that lacks tenant authorization (`tenant_id` checks), timeouts, or thread safety."]}, {"id": "KP3", "description": "Mitigate via project rules (`CLAUDE.md`/`.cursorrules`), explicit interface specs, TDD (`pytest`), and strict CI static/security gates.", "required": true, "acceptable_evidence": ["Technical keywords: .cursorrules / CLAUDE.md architectural context, TDD (write failing pytest first), mypy --strict, ruff, SAST (Semgrep/Bandit), human PR review.", "Explains grounding the assistant with repository rules files (`CLAUDE.md` / `.cursorrules`), pinning target file/doc context, writing `pytest` contracts and Pydantic schemas first, and enforcing `mypy`, `ruff`, and human diff review in CI."]}], "critical_failures": ["Treats AI-generated code that compiles as automatically production-ready without testing edge cases, concurrency, or security boundaries.", "Allows AI assistants to install arbitrary unverified third-party packages without dependency and license auditing."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What code quality practices and processes do you follow to ensure maintainable and reliable code within a team?', '{"key_points": [{"id": "KP1", "description": "Automate deterministic formatting, linting, static typing, and secret scanning via `pre-commit` and CI gates (`ruff`, `black`, `mypy`, `gitleaks`).", "required": true, "acceptable_evidence": ["Technical keywords: pre-commit hooks, ruff / flake8, black, mypy --strict, ESLint/Prettier, gitleaks/Bandit, branch protection rules.", "Explains removing subjective style debates by enforcing automated formatters (`black`/`ruff`), static type checkers (`mypy --strict`), and secret/SAST scanners in `pre-commit` and blocking GitHub/GitLab branch merges on any violation."]}, {"id": "KP2", "description": "Enforce modular architecture, explicit boundary contracts (`Pydantic` / `Protocol`), and SOLID/DRY design principles.", "required": true, "acceptable_evidence": ["Technical keywords: separation of concerns, SOLID principles, dependency injection, Pydantic/OpenAPI schemas, externalized config (BaseSettings).", "Explains keeping business/ML logic decoupled from I/O frameworks via dependency injection and typed interfaces, enforcing strict Pydantic schemas at API/queue boundaries, and banning hardcoded magic numbers or paths."]}, {"id": "KP3", "description": "Maintain a balanced Testing Pyramid (`pytest` unit, contract/integration, and E2E smoke tests) with coverage and regression requirements.", "required": true, "acceptable_evidence": ["Technical keywords: Testing Pyramid, pytest unit tests, integration/contract tests, regression test per bug fix, coverage ratcheting.", "Explains requiring every new feature or bug fix to include deterministic `pytest` unit and edge-case tests alongside integration contract tests so regressions are caught in CI in under a few minutes."]}, {"id": "KP4", "description": "Standardize small Pull Requests, structured Code Review checklists, and Architecture Decision Records (ADRs).", "required": true, "acceptable_evidence": ["Technical keywords: small atomic PRs (<400 lines), CODEOWNERS, PR review checklist (concurrency, security, observability, rollback), ADRs.", "Explains keeping PRs small and focused (<300–400 LOC) with `CODEOWNERS` routing, reviewing for failure handling, structured logging/metrics, and backward compatibility, and documenting non-obvious design choices in ADRs."]}], "critical_failures": ["Relies solely on manual human code reviews to catch formatting, type errors, or regressions without automated CI pipelines.", "Chases 100% line coverage with brittle, over-mocked tests that do not assert actual business invariants or edge cases."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What edge cases and test scenarios would you consider when validating a function that finds duplicates in an array?', '{"key_points": [{"id": "KP1", "description": "Test structural and cardinality boundary conditions (empty array `[]`, single element `[x]`, all unique, all identical `[x, x, x]`, and elements appearing $>2$ times).", "required": true, "acceptable_evidence": ["Technical keywords: empty list [], single-element [1], all unique [1,2,3], all identical [5,5,5,5], multi-duplicate deduplication ([2,2,2] -> [2] once), order preservation.", "Explains verifying that an empty or 1-element array returns `[]`, an array where a value appears 3+ times (`[2, 2, 2]`) returns `2` only once in the output (not twice) while preserving first-seen or sorted order per specification, and checking that the input array is not mutated in-place unexpectedly."]}, {"id": "KP2", "description": "Test Python-specific type, hashability, and equality edge cases (`1 == True == 1.0`, `0 == False`, `float(''nan'')`, `None`, negative numbers, and unhashable nested dicts/lists).", "required": true, "acceptable_evidence": ["Technical keywords: Python bool/int hash collision (1 == True, 0 == False, hash(1) == hash(True) == hash(1.0)), float(''nan'') != float(''nan''), None, unhashable TypeError (list/dict elements).", "Explains testing Python''s notorious equality/hash traps: in a naive `set`, `1`, `1.0`, and `True` collide (`1 == True` and `hash(1) == hash(True)`); `float(''nan'') != float(''nan'')` fails equality checks; and unhashable elements (`[[1], [1]]`) raise `TypeError: unhashable type: ''list''` if inserted into a `set`."]}, {"id": "KP3", "description": "Test scale/performance benchmarks ($N = 10^6$ elements to catch $O(N^2)$ `x in list` regressions) and invalid top-level inputs (`None`, generators).", "required": true, "acceptable_evidence": ["Technical keywords: O(N) vs O(N^2) time complexity benchmark, large input (10^6 elements), None input TypeError, generator/iterator input.", "Explains running a performance test on $10^6$ elements with a strict timeout to ensure the implementation uses an $O(N)$ hash set/Counter rather than an accidental $O(N^2)$ nested loop."]}], "critical_failures": ["Tests only a basic happy path like `[1, 2, 2, 3]` without considering elements occurring 3+ times (`[2, 2, 2]`), empty arrays, or Python''s `1 == True` / `NaN` / unhashable type traps.", "Fails to check whether the function accidentally mutates the caller''s input list in-place (e.g., via `.sort()`)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is an iterable in Python, and how does it relate to iteration protocols?', '{"key_points": [{"id": "KP1", "description": "Define an `Iterable` as any object capable of returning a fresh `Iterator` via `iter(obj)` (implementing `__iter__()` or sequential 0-indexed `__getitem__()`).", "required": true, "acceptable_evidence": ["Technical keywords: collections.abc.Iterable, __iter__(), legacy __getitem__() sequence protocol, iter() built-in, list, tuple, dict, str, set, range.", "Explains that an `Iterable` (such as `list`, `tuple`, `dict`, `str`, `range`) represents a collection or stream that can be passed to `iter(obj)` to obtain a new `Iterator`."]}, {"id": "KP2", "description": "Distinguish an `Iterable` (reusable across multiple passes) from an `Iterator` (stateful single-pass cursor implementing both `__iter__` and `__next__`).", "required": true, "acceptable_evidence": ["Technical keywords: Iterable vs Iterator, __next__(), StopIteration, multi-pass reusability vs single-pass exhaustion.", "Explains that a container `Iterable` like a `list` does NOT implement `__next__()` directly; instead, each call to `iter(my_list)` returns a separate, independent `list_iterator` with its own cursor state, allowing multiple concurrent or sequential `for` loops over the same `list`, whereas an `Iterator` (like a generator or file object) returns `self` from `__iter__()` and is exhausted after one pass."]}, {"id": "KP3", "description": "Trace how Python''s `for` loop, unpacking, and comprehensions execute the iteration protocol under the hood.", "required": true, "acceptable_evidence": ["Technical keywords: for loop desugaring, iterator = iter(iterable), next(iterator), StopIteration catch.", "Explains that `for x in obj:` first calls `it = iter(obj)` (invoking `obj.__iter__()`) and then repeatedly calls `x = next(it)` (invoking `it.__next__()`) inside an internal loop until `StopIteration` is caught to terminate the loop cleanly."]}, {"id": "KP4", "description": "Mitigate cascading failures across service boundaries with circuit breakers, bulkhead connection pools, and jittered retries.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breaker (closed/open/half-open), bulkhead isolation, exponential backoff with full jitter, timeout budgets.", "Explains isolating downstream dependencies in separate connection pools and tripping a circuit breaker when failure rates exceed threshold."]}, {"id": "KP5", "description": "Verify scalability and fault tolerance empirically through chaos engineering and load testing (Locust/k6).", "required": false, "acceptable_evidence": ["Technical keywords: load testing (k6 / Locust), fault injection / chaos testing, p99 tail-latency SLO verification.", "Demonstrates validating horizontal scaling and graceful degradation under synthetic spike traffic and dependency blackouts."]}], "critical_failures": ["Conflates an `Iterable` with an `Iterator`, claiming that `list` or `dict` implements `__next__()` directly or can only be iterated once.", "Cannot explain the relationship between `iter()`, `next()`, and `StopIteration` in a `for` loop."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is duck typing in Python, and how does it differ from static typing?', '{"key_points": [{"id": "KP1", "description": "Define Duck Typing as runtime behavioral polymorphism where an object''s suitability is determined by the methods and attributes it supports rather than its explicit class inheritance hierarchy.", "required": true, "acceptable_evidence": ["Technical keywords: duck typing, behavioral polymorphism, dunder protocols (__len__, __iter__, .read()), file-like objects (io.StringIO, BytesIO).", "Explains that in Python (''If it walks like a duck and quacks like a duck, it''s a duck''), functions operate on any object supporting the required interface—e.g., `json.load(f)` accepts a real OS file, an in-memory `io.StringIO` buffer, or an HTTP response stream as long as it implements `.read()`, without requiring a shared base class."]}, {"id": "KP2", "description": "Contrast Python''s dynamic Duck Typing and EAFP (`try/except AttributeError`) with Nominal Static Typing (compile-time type/inheritance verification in Java/C++/Rust).", "required": true, "acceptable_evidence": ["Technical keywords: dynamic runtime dispatch vs compile-time nominal type checking, EAFP (Easier to Ask Forgiveness than Permission) vs LBYL (isinstance).", "Explains that nominal static typing verifies declared types and explicit class/interface inheritance at compile time (catching type mismatches before execution), whereas pure duck typing resolves attributes dynamically at runtime—risking late `AttributeError` failures if an untested code path receives an incompatible object."]}, {"id": "KP3", "description": "Bridge both worlds in modern Python using `typing.Protocol` (Static Duck Typing / Structural Subtyping) verified by `mypy`.", "required": true, "acceptable_evidence": ["Technical keywords: typing.Protocol (PEP 544), structural subtyping, static duck typing, collections.abc, mypy.", "Explains that `typing.Protocol` brings static type safety to duck typing: any class that implements the methods declared on a `Protocol` (e.g., `def embed(self, texts: list[str]) -> list[list[float]]:`) passes `mypy` static checks automatically without needing to inherit from that `Protocol`."]}], "critical_failures": ["Writes brittle `if type(x) is list:` checks everywhere instead of accepting duck-typed iterables or `Sequence` protocols.", "Claims Python cannot statically type-check duck-typed interfaces (unaware of `typing.Protocol` / PEP 544)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is hoisting in JavaScript, and how does it affect variables declared with var, let, and const?', '{"key_points": [{"id": "KP1", "description": "Explain Hoisting as JavaScript''s registration of variable and function declarations in lexical memory during the Execution Context Creation Phase before line-by-line execution.", "required": true, "acceptable_evidence": ["Technical keywords: Execution Context creation phase vs execution phase, lexical environment memory allocation, declarations hoisted (not assignments).", "Explains that JavaScript does not physically move code text to the top of the file; rather, the JS engine allocates bindings for declarations in the scope''s Lexical Environment during the creation phase, while value assignments remain in place until the execution phase reaches that line."]}, {"id": "KP2", "description": "Contrast `var` (function-scoped, hoisted and initialized to `undefined`) with `let` and `const` (block-scoped, hoisted uninitialized in the Temporal Dead Zone / TDZ).", "required": true, "acceptable_evidence": ["Technical keywords: var (function scope, initialized to undefined), let and const (block scope, Temporal Dead Zone / TDZ, ReferenceError), const mandatory initializer.", "Explains that accessing a `var` variable before its declaration line silently returns `undefined` (masking bugs and leaking out of `if`/`for` blocks), whereas `let` and `const` are block-scoped and remain in the **Temporal Dead Zone (TDZ)** from the start of the block until their declaration line is evaluated—throwing an explicit `ReferenceError: Cannot access ''...'' before initialization`."]}, {"id": "KP3", "description": "Contrast Function Declarations (fully hoisted with body) vs Function Expressions / Arrow Functions and `class` declarations.", "required": false, "acceptable_evidence": ["Technical keywords: function declaration (fully hoisted) vs const arrow function / function expression (TDZ / TypeError), class declaration TDZ.", "Explains that `function foo() {}` is hoisted with its full implementation (callable above its definition), whereas `const foo = () => {}` or `var foo = function() {}` follows `const`/`var` variable rules (throwing `ReferenceError` or `TypeError: foo is not a function`)."]}], "critical_failures": ["Claims `let` and `const` are not hoisted at all (ignoring why shadowing an outer variable inside a block throws a TDZ `ReferenceError` before the inner `let` line).", "Claims accessing `let` or `const` before declaration returns `undefined` like `var`."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is inheritance in object-oriented programming, and how does it support code reuse and polymorphism?', '{"key_points": [{"id": "KP1", "description": "Define Inheritance (`is-a` hierarchy) and how subclasses reuse and extend base-class attributes and methods via `super()`.", "required": true, "acceptable_evidence": ["Technical keywords: base/parent superclass, derived/child subclass, is-a relationship, super().__init__(), method extension vs overriding, Python C3 MRO.", "Explains that inheritance allows a child class to inherit shared state initialization and behavior from a parent class (invoking `super()` to reuse parent logic without duplicating code) while adding or overriding specialized behavior."]}, {"id": "KP2", "description": "Explain how Inheritance and Abstract Base Classes (`abc.ABC`, `@abstractmethod`) enable Runtime Polymorphism and the Liskov Substitution Principle (LSP).", "required": true, "acceptable_evidence": ["Technical keywords: runtime polymorphism, dynamic method dispatch, abc.ABC, @abstractmethod, Liskov Substitution Principle (LSP), uniform interface.", "Explains that polymorphism allows caller code to program against a uniform base interface (e.g., `BaseRetriever.retrieve(query)` or `BaseModel.predict(X)`) and seamlessly substitute `MilvusRetriever`, `BM25Retriever`, or `HybridRetriever` at runtime via dynamic method dispatch."]}, {"id": "KP3", "description": "Identify the Fragile Base Class pitfall of deep inheritance hierarchies and when to prefer Composition (`has-a`) or `Protocol`s.", "required": true, "acceptable_evidence": ["Technical keywords: composition over inheritance (has-a vs is-a), fragile base class problem, tight coupling, Diamond Problem / MRO.", "Explains that deep or multi-level inheritance tightly couples subclasses to parent implementation details (the Fragile Base Class problem), so production architectures keep inheritance shallow (1-level ABC/interface contracts) and favor Composition (`has-a` dependency injection) for assembling behavior."]}], "critical_failures": ["Violates the Liskov Substitution Principle by having a subclass override a base method with incompatible return types or `NotImplementedError` on expected interface methods.", "Cannot explain how polymorphism allows a single caller loop to invoke overridden methods across different subclass instances."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'What is the logic behind grouping anagrams using Python, and why is sorting used as a key in this approach?', '{"key_points": [{"id": "KP1", "description": "Explain why sorting characters maps all anagrams in an equivalence class to the exact same canonical representation (`collections.defaultdict(list)`).", "required": true, "acceptable_evidence": ["Technical keywords: canonical invariant representation, equivalence class, collections.defaultdict(list), tuple(sorted(word)) or ''''.join(sorted(word)), hashable dict key.", "Explains that two strings are anagrams if and only if they contain the exact same characters with identical multiplicities; sorting each string''s characters (`tuple(sorted(s))` or `''''.join(sorted(s))`) maps `''eat''`, `''tea''`, and `''ate''` to the identical immutable, hashable key `(''a'', ''e'', ''t'')` (since Python `list`s are mutable and unhashable), grouping them in $O(1)$ hash-map lookup via `defaultdict(list)`."]}, {"id": "KP2", "description": "Analyze the Time and Space Complexity of the sorting approach ($O(N \\\\cdot K \\\\log K)$ time, $O(N \\\\cdot K)$ space) vs the optimal Character-Count Tuple approach ($O(N \\\\cdot K)$ time).", "required": true, "acceptable_evidence": ["Technical keywords: O(N * K log K) time complexity (sorting), O(N * K) time complexity (26-element character count tuple), O(N * K) space complexity, ord(c) - ord(''a'').", "Explains that for $N$ strings of maximum length $K$, sorting each string takes $O(K \\\\log K)$ for a total of $O(N \\\\cdot K \\\\log K)$ time, whereas building a fixed 26-integer frequency count `count = [0] * 26` and using `tuple(count)` as the dictionary key eliminates the $\\\\log K$ sorting factor to achieve optimal $O(N \\\\cdot K)$ time."]}, {"id": "KP3", "description": "Handle practical edge cases (empty strings `\\"\\"`, single-character strings, case sensitivity, and Unicode/non-ASCII characters).", "required": false, "acceptable_evidence": ["Technical keywords: empty string '''', case normalization (.lower()), Unicode characters (where sorted() works directly while fixed [0]*26 requires dynamically sized Counter/sorted).", "Explains that while `tuple(count)` of size 26 is fastest for lowercase ASCII `''a''-''z''`, `tuple(sorted(s))` handles arbitrary Unicode characters cleanly without a huge sparse array."]}], "critical_failures": ["Attempts to use `sorted(word)` directly as a Python dictionary key without converting the returned `list` to a `tuple` or `str`, raising `TypeError: unhashable type: ''list''`.", "Uses $O(N^2 \\\\cdot K)$ pairwise string comparisons instead of a single-pass hash map."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is the role of libraries like argparse, requests, and json in Python applications?', '{"key_points": [{"id": "KP1", "description": "Explain `argparse` for building parameterized, self-documenting Command-Line Interfaces (CLIs) without hardcoded script values.", "required": true, "acceptable_evidence": ["Technical keywords: argparse.ArgumentParser, add_argument (type, default, required, choices, help), parse_args(), CLI parameterization in CI/CD & MLOps jobs.", "Explains that `argparse` parses `sys.argv` command-line flags (e.g., `--epochs`, `--learning-rate`, `--env`), enforces types and allowed `choices`, and auto-generates `--help` documentation so training/ETL scripts are reusable across Airflow, Databricks, and CI/CD."]}, {"id": "KP2", "description": "Explain `requests` for synchronous HTTP/REST communication using connection pooling (`Session`), explicit `timeout`s, and `raise_for_status()`.", "required": true, "acceptable_evidence": ["Technical keywords: requests.Session (TCP connection pooling), HTTPAdapter + Retry, timeout=(connect, read), response.raise_for_status(), headers/auth.", "Explains that `requests` handles HTTP `GET`/`POST` calls to external REST APIs, emphasizing production best practices: always setting an explicit `timeout=(3.05, 30)` (since `requests` defaults to `timeout=None`, hanging forever on dead sockets), calling `response.raise_for_status()`, and reusing `requests.Session()` for TCP/TLS connection pooling."]}, {"id": "KP3", "description": "Explain `json` for serializing (`dumps`/`dump`) and deserializing (`loads`/`load`) Python objects to/from RFC 8259 JSON strings/streams.", "required": true, "acceptable_evidence": ["Technical keywords: json.loads vs json.load, json.dumps vs json.dump, json.JSONDecodeError, custom default serializer (datetime/UUID/Decimal), orjson/Pydantic.", "Explains distinguishing string methods (`json.loads`/`json.dumps`) from file-stream methods (`json.load`/`json.dump`), catching `json.JSONDecodeError` on malformed payloads, and handling non-native types (`datetime`, `UUID`, `numpy` arrays) via custom `default=` encoders or `Pydantic`/`orjson`."]}], "critical_failures": ["Calls `requests.get(url)` or `requests.post(url)` in production without a `timeout` parameter, allowing a stalled upstream server to hang worker threads indefinitely.", "Confuses `json.load`/`json.dump` (file-like streams) with `json.loads`/`json.dumps` (in-memory strings)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is the role of the continue statement in handling failed records during iteration in Python loops?', '{"key_points": [{"id": "KP1", "description": "Explain how `continue` skips the remainder of the current loop body and immediately advances the iterator to the next record (contrasted with `break` and `pass`).", "required": true, "acceptable_evidence": ["Technical keywords: continue (skip current iteration), break (terminate entire loop), pass (no-op placeholder), guard clause pattern.", "Explains that when Python encounters `continue` inside a `for` or `while` loop, it bypasses all remaining statements in the current iteration and jumps directly to the next item from the iterator—whereas `break` aborts the entire loop and `pass` does nothing."]}, {"id": "KP2", "description": "Use `continue` with early Guard Clauses or `try...except` blocks to prevent a single malformed record from aborting a batch ETL/ingestion job.", "required": true, "acceptable_evidence": ["Technical keywords: poison-pill isolation, guard clauses (flat vs deeply nested if-else), try/except SpecificError -> log/DLQ -> continue.", "Explains that in data processing loops, early validation guard clauses (`if not is_valid(row): ... continue`) or `except (ValidationError, JSONDecodeError): ... continue` isolate bad records and keep code flat and readable instead of crashing a million-row job on one corrupted line."]}, {"id": "KP3", "description": "Always pair `continue` on failed records with structured logging, Dead-Letter Queue (DLQ) quarantine, and an error-rate circuit breaker.", "required": true, "acceptable_evidence": ["Technical keywords: no silent data loss, structured error logging, quarantine/DLQ append, failure-rate threshold circuit breaker.", "Emphasizes that production pipelines never execute a bare silent `continue`: before skipping a failed record, the loop increments a failure counter, writes the raw record + error reason to a quarantine/DLQ sink, and aborts (`raise`) if the cumulative failure rate exceeds a safety threshold (e.g., >1%)."]}], "critical_failures": ["Confuses `continue` with `break` (terminating the loop) or `pass` (which continues executing the lines immediately below it in the same iteration!).", "Uses `except Exception: continue` to silently drop failed records without logging, metrics, or DLQ routing."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'What is your approach to solving coding problems in interviews, including handling edge cases and communicating your thought process?', '{"key_points": [{"id": "KP1", "description": "Clarify problem constraints, input/output contracts, scale ($N$), and edge cases before designing an algorithm.", "required": true, "acceptable_evidence": ["Technical keywords: requirement clarification, input size constraints (N), data types, mutability, duplicate/negative/empty handling, return contract.", "Explains starting by restating the problem, working through a concrete small example, and asking targeted clarifying questions (input scale $N$, memory limits, sorted vs unsorted, duplicates, empty/null inputs, and expected return value on failure)."]}, {"id": "KP2", "description": "Compare brute-force vs optimal approaches (stating Time $O(T)$ and Space $O(S)$ complexity) and align with the interviewer before coding.", "required": true, "acceptable_evidence": ["Technical keywords: brute-force baseline, optimal data structure selection (hash map, two-pointer, heap, DP, BFS/DFS), Big-O Time and Space complexity alignment.", "Explains briefly stating the naive baseline ($O(N^2)$), proposing the optimal data structure/algorithm (e.g., $O(N)$ hash map or sliding window), stating exact time and space complexity trade-offs, and confirming the plan with the interviewer before writing code."]}, {"id": "KP3", "description": "Write clean, modular, typed Python code and dry-run against both normal and adversarial edge cases.", "required": true, "acceptable_evidence": ["Technical keywords: Python type annotations, guard clauses, modular helper functions, line-by-line dry-run trace, assert test suite.", "Explains writing idiomatic Python with type hints, descriptive variable names, and upfront guard clauses for edge cases (`if not nums:`), then tracing through the code step-by-step with a happy-path case and boundary cases (empty input, single element, duplicates, overflow/cycles)."]}], "critical_failures": ["Jumps straight into typing code within 5 seconds of reading the prompt without clarifying constraints or agreeing on an algorithmic approach.", "Declares ''I''m done'' the moment the last line is typed without dry-running the code or testing boundary edge cases."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What is your approach to solving coding problems in interviews, particularly when building small applications in Python?', '{"key_points": [{"id": "KP1", "description": "Model core domain entities and state using typed Python data structures (`@dataclass`, `Pydantic BaseModel`, `Enum`) with clear separation of concerns.", "required": true, "acceptable_evidence": ["Technical keywords: @dataclass, Pydantic BaseModel, Enum, typing.Protocol, separation of domain logic from I/O, O(1) lookup indexes (dict/set).", "Explains that unlike single-function LeetCode puzzles, small-application interviews (e.g., building an in-memory file system, task scheduler, rate limiter, or card game) are judged on extensibility across Part 1 -> Part 4: starting with clean `@dataclass`/`Enum` models and separating core state/business methods from CLI/HTTP I/O."]}, {"id": "KP2", "description": "Deliver working vertical slices incrementally (getting Part 1 passing with `assert`/`pytest` tests before over-engineering Part 3).", "required": true, "acceptable_evidence": ["Technical keywords: incremental vertical slices, YAGNI balance, extensible interface, custom domain exceptions.", "Explains prioritizing a clean, working implementation of each requirement milestone with immediate executable tests, while keeping data structures extensible (e.g., storing entities by ID in a `dict[str, Entity]` for $O(1)$ lookup and future snapshotting/filtering)."]}, {"id": "KP3", "description": "Enforce defensive validation, custom error handling, and clean state encapsulation.", "required": true, "acceptable_evidence": ["Technical keywords: input validation guard clauses, ValueError / custom exceptions, immutability / copy-on-write, deterministic test driver.", "Explains validating invalid state transitions (e.g., negative balances, duplicate IDs, drawing from an empty deck) with explicit exceptions and writing a concise test harness at the bottom (`if __name__ == ''__main__'':`) that verifies every requirement and edge case."]}], "critical_failures": ["Writes the entire application as one giant 200-line procedural function manipulating deeply nested untyped dicts and global variables.", "Spends 40 minutes building abstract factory patterns and never finishes a working, tested implementation of the core requirements."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your approach when transitioning from AI-assisted coding to manual code refinement?', '{"key_points": [{"id": "KP1", "description": "Use AI generation for initial scaffolding and boilerplate, then switch to manual refinement for core business invariants, algorithmic hot paths, and security boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: scaffolding vs core domain refinement, stop prompting loop on subtle bugs, architectural alignment.", "Explains using AI to scaffold repetitive boilerplate (DTOs, test fixtures, CRUD wiring), then intentionally taking manual control to refine complex state transitions, concurrency locks, SQL/PySpark query plans, and authorization boundaries—avoiding the trap of endlessly re-prompting when the AI misses a subtle constraint."]}, {"id": "KP2", "description": "Strip AI-generated bloat, redundant defensive wrappers, and inconsistent idioms to match repository patterns.", "required": true, "acceptable_evidence": ["Technical keywords: dead-code removal, DRY reuse of internal utilities, exception hierarchy alignment, algorithmic complexity audit (O(N) vs O(N^2)).", "Explains auditing every line of the generated diff: replacing duplicated helper functions with existing repository utilities, replacing broad `try...except Exception:` blocks with specific domain exceptions, and simplifying verbose code."]}, {"id": "KP3", "description": "Verify refined code with deterministic `pytest` edge-case tests, `mypy --strict`, `ruff`, and profiler/debugger traces.", "required": true, "acceptable_evidence": ["Technical keywords: pytest boundary tests, mypy --strict, ruff linting, mutation testing (verifying test failure when logic is broken).", "Explains running static analysis (`ruff`, `mypy`) and purposefully breaking a condition in the refined implementation to confirm the `pytest` suite actually catches regressions."]}], "critical_failures": ["Accepts multi-file AI diffs wholesale without stripping dead code, verifying internal utility reuse, or understanding every line.", "Spends hours in a ''prompt-and-pray'' loop when an AI assistant repeatedly breaks one test while fixing another instead of debugging and writing the logic manually."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your understanding of the flipped classroom model used in mentorship programs?', '{"key_points": [{"id": "KP1", "description": "Define the Flipped Classroom model: shifting passive knowledge consumption (recorded lectures, study guides, ADRs, codebase reading) to asynchronous pre-work before the session.", "required": true, "acceptable_evidence": ["Technical keywords: asynchronous pre-work (study guides, recorded deep-dives, codebase exploration) vs synchronous active practice.", "Explains that in a flipped classroom, mentees review foundational materials (architecture study guides, recorded walkthroughs, documentation, and starter code) asynchronously on their own schedule prior to meeting."]}, {"id": "KP2", "description": "Dedicate synchronous live mentorship time to high-signal interactive problem solving (live debugging, pair programming, architecture grill/Q&A, and code reviews).", "required": true, "acceptable_evidence": ["Technical keywords: active learning, live debugging, architectural trade-off Q&A, mock design reviews, pair programming.", "Explains that because passive lecturing is removed from live calls, 100% of synchronous mentor-mentee time is spent on hands-on troubleshooting, reviewing actual PRs/designs, and stress-testing edge cases."]}, {"id": "KP3", "description": "Identify key benefits and practical guardrails (faster skill retention, self-sufficiency, and pre-session readiness checkpoints).", "required": true, "acceptable_evidence": ["Technical keywords: engineering self-sufficiency, higher retention, pre-session quiz/PR checkpoint, asynchronous unblockers.", "Explains that this model builds real-world engineering autonomy and exposes specific conceptual gaps quickly, provided mentors set clear pre-work checkpoints (e.g., submitting a draft PR or 3 specific questions beforehand) so mentees do not arrive unprepared."]}], "critical_failures": ["Confuses the flipped classroom with abandoning mentees to self-study without structured synchronous coaching or code review.", "Spends the entire live mentorship session reading slides aloud instead of engaging in interactive problem-solving."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What issues can arise when using the array index as a key in React lists?', '{"key_points": [{"id": "KP1", "description": "Explain how React''s Fiber reconciler uses `key` to match component instances across renders and how index shifts (`0, 1, 2...`) corrupt component identity on prepend, insert, delete, or sort.", "required": true, "acceptable_evidence": ["Technical keywords: React Fiber reconciliation, Virtual DOM diffing, component identity mismatch, index shift on prepend/delete/reorder/filter.", "Explains that React identifies which list item changed by matching `key` between the previous and next render trees; when an item is prepended, deleted from the middle, or sorted, every subsequent item''s array index shifts, tricking React into thinking index `0` is still the same entity with updated props."]}, {"id": "KP2", "description": "Describe concrete UI state corruption bugs (uncontrolled `<input>` values, local `useState`, focus/selection, and CSS animations sticking to the wrong row).", "required": true, "acceptable_evidence": ["Technical keywords: stale local state (useState/useRef), uncontrolled DOM input values, checkbox/focus mismatch, broken exit/enter animations.", "Explains the classic production bug: if a user types text into row 0''s `<input>` (or expands row 0''s local `useState` accordion) and deletes row 0, React reuses the component instance at `key={0}` for the old row 1—leaving the deleted item''s typed text or expanded state attached to the wrong data item!"]}, {"id": "KP3", "description": "Explain unnecessary re-renders of all shifted rows and specify the correct solution (stable, globally unique entity IDs like database `id`/`uuid`, or when index keys are safe).", "required": true, "acceptable_evidence": ["Technical keywords: stable unique entity ID (item.id, crypto.randomUUID() at creation time), anti-pattern of key={Math.random()}, static non-reordered list exception.", "Explains using a permanent domain ID (`key={item.id}`) or a `crypto.randomUUID()` assigned once when the data record is created (never `key={Math.random()}` inside `render`, which unmounts and remounts every DOM node on every render), noting that index keys are only acceptable for purely static, stateless lists that are never reordered or filtered."]}], "critical_failures": ["Recommends `key={Math.random()}` or `key={uuidv4()}` called directly inside the `.map()` render body, which destroys and recreates all DOM nodes and state on every render.", "Claims using array index as `key` only causes a harmless console warning and cannot cause real UI state bugs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What strategies would you use to manage state effectively in React applications to minimize unnecessary re-renders?', '{"key_points": [{"id": "KP1", "description": "Colocate state as close as possible to the leaf components that read it and use Component Composition (`children` slot pattern) instead of lifting state to the root.", "required": true, "acceptable_evidence": ["Technical keywords: state colocation, moving state down, children composition pattern, avoiding root-level state updates.", "Explains that updating state in a top-level parent re-renders its entire subtree by default; isolating frequently changing state (e.g., a chat input box or hover timer) inside a small leaf component or passing expensive siblings as `children` prevents re-rendering the rest of the page."]}, {"id": "KP2", "description": "Partition React Contexts (separating state vs dispatch, or high-frequency vs low-frequency values) or use atomic selector stores (`Zustand`, `Redux Toolkit`, `Jotai`).", "required": true, "acceptable_evidence": ["Technical keywords: Context splitting (StateContext vs DispatchContext), Zustand selector subscriptions (useStore(s => s.field)), TanStack Query for server state.", "Explains that a single monolithic React `Context` re-renders every consumer whenever any property on the context object changes; splitting Contexts by domain/frequency or using selector-based stores (`Zustand`) ensures components re-render only when their specific selected slice changes."]}, {"id": "KP3", "description": "Apply `React.memo`, `useMemo`, and `useCallback` strategically to preserve referential equality (`===`) across renders.", "required": true, "acceptable_evidence": ["Technical keywords: React.memo, useMemo, useCallback, referential equality (===), React 19 Compiler auto-memoization, React DevTools Profiler.", "Explains wrapping expensive child subtrees in `React.memo` and stabilizing object/array props and callback functions with `useMemo` and `useCallback` (profiled via React DevTools Profiler flamegraphs rather than premature micro-memoization)."]}, {"id": "KP4", "description": "Avoid redundant derived state in `useState`+`useEffect`, use `useRef` for non-visual mutable values, and use `useTransition` / debouncing for rapid input streams.", "required": true, "acceptable_evidence": ["Technical keywords: derived state calculated during render, useRef (zero re-render mutation), useTransition / useDeferredValue, debouncing/throttling.", "Explains computing derived values directly during render instead of syncing them via `useEffect(() => setDerived(...))` (which forces an extra cascading render pass), storing timers/WebSocket handles in `useRef`, and marking non-urgent filter updates with `useTransition`."]}], "critical_failures": ["Uses `useEffect` to synchronize derived state into a second `useState` variable, causing double renders and state desynchronization bugs.", "Wraps every single component in `React.memo` while still passing inline arrow functions (`onClick={() => ...}`) or inline object literals (`style={{...}}`), breaking shallow prop comparison on every render."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why do you prefer TypeScript over JavaScript in React applications, and how does it improve code quality?', '{"key_points": [{"id": "KP1", "description": "Catch `undefined`/`null` dereferences and invalid component prop contracts at compile time (`strictNullChecks`, typed Props/Hooks).", "required": true, "acceptable_evidence": ["Technical keywords: tsc compile-time type checking, strict: True, strictNullChecks, React.FC / typed props interface, useState<T>.", "Explains that TypeScript shifts the most common React runtime crash (`TypeError: Cannot read properties of undefined`) to compile time by enforcing explicit `interface`/`type` definitions for component props, callbacks, `useRef<HTMLInputElement>(null)`, and event handlers."]}, {"id": "KP2", "description": "Model asynchronous UI and AI streaming states safely using Discriminated Unions (`status: ''idle'' | ''streaming'' | ''success'' | ''error''`).", "required": true, "acceptable_evidence": ["Technical keywords: Discriminated Unions (tagged unions), exhaustive switch checking (never type), impossible UI state elimination.", "Explains that discriminated unions make impossible UI states unrepresentable (e.g., narrowing `data` as non-null only when `state.status === ''success''`), while exhaustive `never` checks ensure adding a new backend enum/tool status forces compile errors wherever UI handling is missing."]}, {"id": "KP3", "description": "Enable fearless cross-repo refactoring and end-to-end schema parity with FastAPI (`openapi-typescript` / `Zod`).", "required": true, "acceptable_evidence": ["Technical keywords: OpenAPI-to-TypeScript codegen, Zod runtime boundary validation, IDE AST refactoring, self-documenting contracts.", "Explains generating TypeScript types directly from FastAPI''s Pydantic `openapi.json` schema (and validating external responses with `Zod`) so renaming a backend field immediately highlights every affected React component in CI."]}, {"id": "KP4", "description": "Enforce database-level tenant isolation (Row-Level Security or tenant_id composite indexes) and encrypted secret storage.", "required": false, "acceptable_evidence": ["Technical keywords: PostgreSQL Row-Level Security (RLS), composite `(tenant_id, id)` index, AWS KMS / HashiCorp Vault envelope encryption.", "Explains ensuring every database query is scoped to the authenticated tenant and sensitive credentials/tokens are encrypted at rest."]}, {"id": "KP5", "description": "Implement real-time security audit logging and anomaly alerting for authentication failures and privilege escalation attempts.", "required": false, "acceptable_evidence": ["Technical keywords: structured security audit log (`actor_id`, `ip`, `action`, `status`), brute-force velocity alerting, SIEM ingestion.", "Explains emitting immutable audit events for all login, token refresh, and 403 authorization failures."]}], "critical_failures": ["Sprinkles `: any` or `@ts-ignore` across React components, completely disabling TypeScript''s type safety.", "Claims TypeScript automatically validates untrusted runtime JSON payloads returned from `fetch()` without a runtime validator like `Zod`."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 90, 'You mentioned React on the front end, what are you using on the back end?', '{"key_points": [{"id": "KP1", "description": "Specify `FastAPI` (Python ASGI on `Uvicorn`/`Gunicorn`) with `Pydantic v2` schema validation as the primary API and AI orchestration gateway.", "required": true, "acceptable_evidence": ["Technical keywords: Python FastAPI, Uvicorn/Gunicorn ASGI workers, Pydantic v2 request/response validation, auto-generated OpenAPI 3.1 schema, SSE StreamingResponse.", "Explains using Python + FastAPI on the backend because it combines high-concurrency asynchronous I/O (`async/await` + `StreamingResponse` for real-time LLM token streaming to React) with native integration into the Python AI/ML ecosystem (`LangGraph`, `PyTorch`, `MLflow`, `scikit-learn`)."]}, {"id": "KP2", "description": "Detail the persistence, caching, and vector retrieval tier (`PostgreSQL`/`pgvector`, `Milvus`, `Redis`, `DynamoDB`, `S3`).", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL (SQLAlchemy async / asyncpg), Milvus / pgvector / FAISS, Redis (semantic cache, rate limiting, session state), Amazon S3.", "Explains pairing FastAPI with PostgreSQL for relational transactional state, Milvus/pgvector for hybrid RAG vector retrieval, Redis for semantic caching and Celery/background task queues, and S3 for raw document/model artifact storage."]}, {"id": "KP3", "description": "Explain production security, containerization, and observability (`JWT`/`OAuth2`, `Docker` on `AWS EKS`, `Prometheus`/`Grafana`).", "required": true, "acceptable_evidence": ["Technical keywords: OAuth2/JWT RBAC middleware, CORS configuration, Docker multi-stage build, AWS EKS / ALB Ingress, Prometheus/Grafana/OpenTelemetry.", "Explains securing the React-to-FastAPI boundary with strict CORS rules, JWT RBAC dependency injection (`Depends`), containerized deployment on AWS EKS, and end-to-end OpenTelemetry/Prometheus observability."]}], "critical_failures": ["Names a backend framework without explaining how it connects to the React frontend (REST/SSE/OpenAPI), database/vector stores, or ML inference pipelines.", "Uses synchronous WSGI servers (e.g., single-threaded Flask dev server) to serve long-lived streaming LLM connections in production."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'Can you describe a simple approach in Python to check whether the difference between two values (i and j) equals a specific number, such as 3?', '{"key_points": [{"id": "KP1", "description": "Distinguish signed difference (`i - j == 3`) vs absolute magnitude difference (`abs(i - j) == 3`) in $O(1)$ time for two scalar values.", "required": true, "acceptable_evidence": ["Technical keywords: abs(i - j) == k, signed vs unsigned difference, math.isclose(abs(i - j), 3.0, rel_tol=1e-9) for floats.", "Explains that for two given numbers `i` and `j`, `abs(i - j) == 3` checks order-independent distance in $O(1)$ time and $O(1)$ space (while `i - j == 3` checks directional difference), and uses `math.isclose(abs(i - j), 3.0)` when `i` and `j` are IEEE 754 floating-point numbers (`0.1 + 0.2 != 0.3`)."]}, {"id": "KP2", "description": "Scale to finding a pair `(i, j)` with difference $k=3$ across an array of $N$ numbers in $O(N)$ time using a Python `set` (avoiding $O(N^2)$ nested loops).", "required": true, "acceptable_evidence": ["Technical keywords: O(N) hash set lookup, seen = set(), (x - k) in seen or (x + k) in seen, two-pointer O(N log N) on sorted array.", "Explains that when searching an array `nums` for any two elements differing by $k=3$, iterating once with a hash set `seen = set()` and checking `if (x - 3) in seen or (x + 3) in seen: return True` reduces time complexity from $O(N^2)$ nested loops to $O(N)$ time and $O(N)$ space (or $O(N \\\\log N)$ time and $O(1)$ space via sorting + two pointers)."]}, {"id": "KP3", "description": "Handle edge cases ($k = 0$ requiring duplicate frequency count $\\\\ge 2$, negative numbers, empty/single-element arrays, and type validation).", "required": true, "acceptable_evidence": ["Technical keywords: k == 0 self-difference trap (checking seen before adding x), negative integers, len(nums) < 2 guard, collections.Counter.", "Explains checking `if (x - k) in seen` BEFORE `seen.add(x)` so that when $k = 0$, an element is not falsely matched against itself (`x - x == 0`)."]}], "critical_failures": ["Converts the entire array to a `set` upfront and checks `if (x + k) in num_set` without guarding against $k = 0$ (matching every element with itself).", "Uses `abs(i - j) == 3.0` with exact `==` on floating-point numbers without `math.isclose`."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your debugging approach when your initial solution produces errors?', '{"key_points": [{"id": "KP1", "description": "Read the bottom-up Python Traceback (exception type, exact line number, local variable state) and isolate a minimal deterministic failing input.", "required": true, "acceptable_evidence": ["Technical keywords: Python stack traceback (bottom-up frame inspection), exception class & message, deterministic minimal reproducible example (MRE), random seed fixing.", "Explains resisting random trial-and-error edits: first inspecting the exact exception type and innermost stack frame in the traceback (or comparing expected vs actual output for logic bugs) and shrinking the failing input to the smallest deterministic case that triggers the bug."]}, {"id": "KP2", "description": "Formulate a falsifiable hypothesis and bisect execution state using `breakpoint()` / `pdb`, IDE watches, or targeted invariant assertions.", "required": true, "acceptable_evidence": ["Technical keywords: scientific debugging (hypothesis -> test), binary search bisection of data flow, breakpoint() / pdb / pytest --pdb, invariant assertions.", "Explains bisecting the code path (checking intermediate variable types, shapes, or loop boundaries at the midpoint) using `breakpoint()` / `pytest --pdb` or targeted state logging to pinpoint the exact line where actual state diverges from the expected invariant."]}, {"id": "KP3", "description": "Fix the underlying root cause (not just the symptom) and lock in a permanent `pytest` regression test.", "required": true, "acceptable_evidence": ["Technical keywords: root-cause fix vs symptom masking, sibling bug audit, pytest regression test.", "Explains verifying why the root cause occurred (e.g., off-by-one boundary, shared mutable default argument, unawaited coroutine), checking if similar code paths have the same flaw, and adding the minimal failing input to the `pytest` suite so it can never regress."]}], "critical_failures": ["Randomly mutates operators (`<` to `<=`, `+1` to `-1`) without understanding the root cause or tracing the failing input.", "Wraps the failing code in `try...except: pass` to silence the exception instead of fixing the underlying bug."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'BROAD', 150, 'Can you tell me about your experience as a Python developer, specifically regarding design, testing, and code review?', '{"key_points": [{"id": "KP1", "description": "Demonstrate idiomatic Python Software Design (modular packages, `typing.Protocol`/ABCs, `Pydantic v2`, `@dataclass`, generators, and `asyncio`).", "required": true, "acceptable_evidence": ["Technical keywords: clean architecture, typing.Protocol, Pydantic v2 BaseModel/BaseSettings, @dataclass, context managers, generators, FastAPI async/await.", "Explains designing production Python services and ML/RAG pipelines using strict separation of concerns, dependency injection, `Pydantic` boundary contracts, memory-efficient generators, and non-blocking `asyncio` microservices."]}, {"id": "KP2", "description": "Detail comprehensive `pytest` engineering (fixtures, parameterization, monkeypatching/mocking external I/O, and data/model contract tests).", "required": true, "acceptable_evidence": ["Technical keywords: pytest, conftest.py fixtures, @pytest.mark.parametrize, unittest.mock / pytest-mock, httpx AsyncClient, Pandera, DeepEval.", "Explains authoring fast, deterministic `pytest` suites using reusable `conftest.py` fixtures, `@pytest.mark.parametrize` for edge-case matrices, mocking external LLM/S3 network calls in unit tests while running containerized integration tests against test databases."]}, {"id": "KP3", "description": "Describe high-signal Code Review standards (catching Python-specific pitfalls, complexity/memory bottlenecks, and security/leakage flaws).", "required": true, "acceptable_evidence": ["Technical keywords: mutable default arguments, blocking event loop in async def, N+1 queries, O(N^2) list lookups, ML data leakage, pre-commit (ruff, mypy, black).", "Explains automating style/formatting via `ruff`/`black`/`mypy` in CI so human PR reviews focus on Python anti-patterns (mutable default arguments, bare `except`, blocking `async` loops, unclosed handles), algorithmic complexity, and test completeness."]}], "critical_failures": ["Describes Python experience solely as running ad-hoc Jupyter notebook cells without package structure, type annotations, automated `pytest` suites, or PR review practices.", "Cannot name concrete Python bugs or design trade-offs caught during code reviews."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'Can you walk through the design and functionality of the AI-driven hiring automation system you worked on?', '{"key_points": [{"id": "KP1", "description": "Document Parsing & Multi-Source Ingestion Pipeline (Resumes, Job Descriptions, and Study-Guide Ground-Truth Rubrics).", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware PDF/DOCX parsing (Docling / PyMuPDF), Pydantic structured extraction, skill ontology normalization, PII anonymization.", "Explains ingesting candidate resumes, job descriptions, and technical question banks: parsing multi-column PDFs into structured JSON (skills, role tenure, project complexity) via Pydantic schemas while stripping demographic/PII identifiers (`name`, `gender`, `zip_code`) to prevent biased screening."]}, {"id": "KP2", "description": "Hybrid Retrieval & Dynamic Interview Question Selection (`BM25` + Dense Vector Search + Cross-Encoder Reranking).", "required": true, "acceptable_evidence": ["Technical keywords: Hybrid RAG (BM25 + dense embeddings), Milvus / pgvector, metadata filtering (subject, concept, difficulty_level, scope), Cross-Encoder reranking.", "Explains matching job requirements and candidate skill gaps against the calibrated question bank using metadata pre-filtering (`subject`, `concept`, `difficulty_level`, `time_limit_seconds`) and hybrid semantic + keyword search."]}, {"id": "KP3", "description": "Multi-Agent Assessment & Rubric-Grounded LLM-as-a-Judge Scoring (`KP1..KPn` Key Points & `critical_failures`).", "required": true, "acceptable_evidence": ["Technical keywords: Whisper ASR transcription, LLM-as-a-Judge (temperature=0), atomic key_points (KP1..KPn, required, acceptable_evidence), critical_failures, DeepEval / G-Eval.", "Explains transcribing candidate spoken/written answers and evaluating them via a deterministic `temperature=0` LLM Judge grounded strictly against each question''s `ground_truth` JSON (`key_points` `KP1..KPn`, `acceptable_evidence`, and `critical_failures`), requiring per-KP evidence citations before computing a weighted score."]}, {"id": "KP4", "description": "Fairness Guardrails, Bias Auditing, and Recruiter Human-in-the-Loop (HITL) Decision Support.", "required": true, "acceptable_evidence": ["Technical keywords: EEOC / NYC Local Law 144 bias auditing, adverse impact ratio, Cohen''s Kappa human calibration, Human-in-the-Loop (HITL) recruiter sign-off.", "Explains that the AI never makes autonomous final rejection/hiring decisions: it outputs transparent evidence-backed scorecards (`KP` pass/fail breakdown + transcript quotes) for human hiring managers and undergoes continuous calibration against SME graders."]}], "critical_failures": ["Feeds raw unredacted resumes (including names, photos, addresses, or protected attributes) into an uncalibrated LLM prompt asking ''Should we hire this person? Yes/No''.", "Scores candidate answers without structured ground-truth rubrics (`KP1..KPn`) or human-in-the-loop oversight."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Given a Python dictionary with various key and value types, how does Python handle and represent such mappings during execution?', '{"key_points": [{"id": "KP1", "description": "Explain how CPython stores `PyObject*` pointers in a Two-Array Compact Hash Table (sparse `dk_indices` + dense insertion-ordered `dk_entries`).", "required": true, "acceptable_evidence": ["Technical keywords: PyObject* pointers, compact dict (Python 3.6+), sparse index array (dk_indices), dense entry table (me_hash, me_key, me_value), insertion order preservation.", "Explains that because every variable in Python is a `PyObject*` heap pointer, a single `dict` can seamlessly mix heterogeneous key/value types; since Python 3.6+, CPython splits the table into a compact sparse array of integer indices and a dense array of `(hash, key_ptr, value_ptr)` entries—reducing memory by ~25% and guaranteeing insertion order."]}, {"id": "KP2", "description": "Explain Key Hashability requirements (`__hash__` and `__eq__`) and numeric/boolean equivalence collisions (`1 == 1.0 == True`).", "required": true, "acceptable_evidence": ["Technical keywords: __hash__(), __eq__(), immutable keys (int, str, tuple of immutables, frozenset), TypeError on mutable list/dict/set keys, 1 == 1.0 == True collision.", "Explains that keys must be hashable (`__hash__` remains invariant over lifetime and `a == b` implies `hash(a) == hash(b)`): Lookup computes `hash(k)`, masks the lower bits to probe `dk_indices`, verifies stored `me_hash == hash(k)`, and confirms identity `k is me_key` or equality `k == me_key` (which is why `{1: ''a'', True: ''b'', 1.0: ''c''}` collapses to `{1: ''c''}`)."]}, {"id": "KP3", "description": "Explain Open Addressing collision resolution with pseudo-random perturbation probing and dynamic resizing at $\\\\frac{2}{3}$ load factor ($O(1)$ amortized lookup/insert).", "required": true, "acceptable_evidence": ["Technical keywords: open addressing, perturbation probing (PERTURB_SHIFT = 5), dummy/tombstone deletion markers, 2/3 load factor resize, O(1) average vs O(N) worst-case.", "Explains that hash collisions are resolved via open addressing shifting higher hash bits (`perturb >>= 5`) rather than linked-list chaining, deleted slots leave dummy tombstones to preserve probe chains, and the table resizes when $\\\\ge \\\\frac{2}{3}$ full to maintain $O(1)$ amortized lookup."]}], "critical_failures": ["Claims Python dictionaries allow mutable `list` or `dict` objects (or tuples containing a `list`) as keys.", "Claims `{1: ''int'', True: ''bool''}` stores two separate keys in a Python dictionary."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Given a string encoding problem with repetition represented using a star notation, how would you determine the minimum encoded length without constructing the encoded string?', '{"key_points": [{"id": "KP1", "description": "Formulate the Star-Encoding recurrence (`''*''` repeats the entire preceding prefix $S[0..i-1]$ onto $S[i..2i-1]$, reducing length by $i - 1$ characters per star).", "required": true, "acceptable_evidence": ["Technical keywords: prefix-doubling compression (ABABCABABCD -> AB*C*D), S[0:i] == S[i:2*i], recurrence DP/greedy length counter, no string concatenation.", "Explains that in the classic prefix-repetition star encoding problem (e.g., `''ABABCABABCD''` $\\\\rightarrow$ `''AB*C*D''`, length $6$), a `''*''` at encoded position represents duplicating the entire prefix $S[0:i]$ immediately at $S[i:2i]$, replacing $i$ characters with a single `''*''` character (saving $i - 1$ characters)."]}, {"id": "KP2", "description": "Compute the exact encoded length using an integer state counter + Reverse Halving / DP recurrence without building any intermediate encoded strings.", "required": true, "acceptable_evidence": ["Technical keywords: integer length state variable, reverse index halving (even index i where S[:i//2] == S[i//2:i]), DP[i] = min(DP[i-1] + 1, DP[i//2] + 1), O(1) integer tracking.", "Explains tracking only an integer `ans` (or `dp[i]` array of integers) working backward from $N$ or forward via DP: if current length $L$ is even and the first half $S[0 : L//2]$ equals the second half $S[L//2 : L]$, replace the second half with `1` (for `''*''`) and halve $L \\\\leftarrow L // 2$; otherwise add `1` for the trailing literal character and decrement $L \\\\leftarrow L - 1$."]}, {"id": "KP3", "description": "Optimize prefix-equality checks from $O(N^2)$ slicing to $O(N)$ time using KMP $\\\\pi$-array, Z-algorithm, or Rolling Hash (Rabin-Karp).", "required": true, "acceptable_evidence": ["Technical keywords: Z-algorithm (Z[i] >= i), KMP LPS array, Polynomial Rolling Hash O(1) substring equality, O(N) time complexity.", "Explains that precomputing the Z-array (`z[i]` = longest common prefix of $S$ and $S[i:]`) or a 64-bit Rolling Hash in $O(N)$ time allows checking whether $S[0:k] == S[k:2k]$ in $O(1)$ time (`z[k] >= k`), achieving $O(N)$ total time and $O(1)$ extra string allocation."]}], "critical_failures": ["Constructs and concatenates new candidate strings (`encoded = encoded + ''*''`) inside nested loops, wasting $O(N^2)$ memory and violating the constraint.", "Confuses prefix-doubling star notation (`AB*` = `ABAB`) with standard Run-Length Encoding (`A3B2`) without clarifying the encoding rule."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Have you used Pydantic data classes? Can you explain them and then give me some example how you would use it? How would you set up a Pydantic data model?', '{"key_points": [{"id": "KP1", "description": "Explain Pydantic (`pydantic-core` Rust engine) and contrast `BaseModel` with `@pydantic.dataclasses.dataclass` and standard `@dataclasses.dataclass`.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic v2 BaseModel, pydantic.dataclasses.dataclass, Rust pydantic-core validation, runtime type validation/coercion vs stdlib @dataclass (zero runtime check).", "Explains that standard Python `@dataclass` does zero runtime type validation (`User(age=''not_an_int'')` silently succeeds), whereas `pydantic.BaseModel` and `@pydantic.dataclasses.dataclass` enforce strict runtime parsing, type coercion/validation, and detailed `ValidationError` reporting powered by `pydantic-core`."]}, {"id": "KP2", "description": "Demonstrate setting up a production Pydantic v2 model with `Field` constraints, `@field_validator`, `@model_validator`, and `ConfigDict`.", "required": true, "acceptable_evidence": ["Technical keywords: Field(ge=0, min_length=1, description=...), @field_validator(mode=''after''), @model_validator, ConfigDict(strict=True, extra=''forbid'', frozen=True), model_validate, model_dump_json.", "Provides a concrete setup example defining typed fields with `Field(...)` bounds, custom cross-field checks via `@model_validator(mode=''after'')`, `ConfigDict(extra=''forbid'')` to reject unexpected payload fields, and `.model_validate()` / `.model_json_schema()`."]}, {"id": "KP3", "description": "Provide concrete AI/ML & API production use cases (FastAPI request/response DTOs, LLM Structured Output / tool-calling schemas, and `BaseSettings` env config).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI request/response validation, LLM Structured Outputs (response_format / Instructor), MCP tool parameter schemas, pydantic-settings BaseSettings.", "Explains using Pydantic models to enforce FastAPI contracts, generate JSON Schemas for LLM structured outputs (`client.beta.chat.completions.parse(response_format=MyModel)`), and validate startup environment variables via `BaseSettings`."]}], "critical_failures": ["Confuses standard library `@dataclasses.dataclass` with `Pydantic`, claiming standard `@dataclass` automatically validates field types at runtime.", "Uses deprecated Pydantic v1 methods (`.dict()`, `.parse_obj()`, `@validator`) when writing Pydantic v2 models without knowing `.model_dump()`, `.model_validate()`, and `@field_validator`."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How can memoization be used to optimize repeated factorial computations across multiple calls, and what complexity improvements does it provide?', '{"key_points": [{"id": "KP1", "description": "Exploit the overlapping subproblem structure $n! = n \\\\times (n-1)!$ across multiple queries using `@functools.cache` / `@lru_cache` or a persistent dynamic array.", "required": true, "acceptable_evidence": ["Technical keywords: overlapping subproblems, n! = n * (n-1)!, functools.cache / lru_cache(maxsize=None), persistent cache list/dict across calls.", "Explains that while a single isolated call to `factorial(n)` has no internal overlapping subproblems (unlike Fibonacci), across $Q$ repeated calls (`factorial(5)`, `factorial(7)`, `factorial(6)`), caching intermediate values $k!$ means `factorial(7)` reuses cached `5!` in just 2 multiplications ($7 \\\\times 6 \\\\times 5!$) and `factorial(6)` returns in $O(1)$."]}, {"id": "KP2", "description": "Quantify the Time and Space Complexity improvement across $Q$ queries up to $N_{\\\\max}$: from $O(Q \\\\cdot N)$ down to $O(N_{\\\\max} + Q)$ ($O(1)$ amortized per lookup).", "required": true, "acceptable_evidence": ["Technical keywords: uncached O(Q * N) vs memoized O(N_max + Q) total time, O(1) cache-hit lookup, O(N_max) space complexity, arbitrary-precision integer multiplication cost.", "Explains that without memoization, $Q$ queries take $O(Q \\\\cdot N)$ multiplications, whereas with memoization each $k!$ up to $N_{\\\\max} = \\\\max(n_i)$ is computed at most once across the entire process lifetime—yielding $O(N_{\\\\max} + Q)$ total multiplications ($O(1)$ per subsequent query) at the cost of $O(N_{\\\\max})$ cache memory."]}, {"id": "KP3", "description": "Handle Python-specific edge cases (`n < 0` raising `ValueError`, `0! = 1`, `RecursionError` at `sys.getrecursionlimit()` avoided via iterative cache extension).", "required": true, "acceptable_evidence": ["Technical keywords: ValueError on n < 0, base case 0! == 1, RecursionError (>1000 depth) in recursive @cache vs iterative bottom-up cache list extension.", "Explains that a naive recursive `@cache def fact(n): return 1 if n <= 1 else n * fact(n-1)` crashes with `RecursionError` if the first call is `fact(2000)`, whereas an iterative cache list `while len(cache) <= n: cache.append(cache[-1] * len(cache))` achieves the same $O(1)$ lookup without stack overflow."]}], "critical_failures": ["Claims memoization reduces a *single* isolated call of `factorial(n)` from $O(2^n)$ to $O(n)$ (confusing linear factorial recursion with binary Fibonacci recursion).", "Ignores Python''s `RecursionError` stack limit when calling a recursive memoized factorial on cold inputs $n > 1000$."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you implement fallback mechanisms like human-in-the-loop logic to handle failures gracefully in the AI system?', '{"key_points": [{"id": "KP1", "description": "Implement Automated Tiered Technical Fallbacks first (Schema Repair Retry, Cross-Provider/Model Failover, and Deterministic Degraded Mode).", "required": true, "acceptable_evidence": ["Technical keywords: bounded retry with validation feedback, cross-model failover (primary LLM -> backup LLM), circuit breaker, deterministic search/rule fallback.", "Explains handling transient infrastructure and formatting failures automatically before paging a human: (1) up to 2 self-correction retries if Pydantic JSON validation fails, (2) circuit-breaker failover to a secondary model/region on `HTTP 429`/`5xx` timeouts, and (3) returning top reranked source snippets directly if generation is unavailable."]}, {"id": "KP2", "description": "Define explicit quantitative triggers for Human-in-the-Loop (HITL) escalation (Low Confidence, Low Groundedness/Faithfulness, Repeated Tool Failure, or High-Risk Action).", "required": true, "acceptable_evidence": ["Technical keywords: escalation triggers, confidence score < threshold, NLI faithfulness < 0.75, max retry exhaustion, high-stakes mutation/financial threshold.", "Explains escalating to a human operator when: retrieval similarity or NLI faithfulness falls below threshold, an agent exceeds its retry budget (`max_retries=2`), guardrails flag policy/PII ambiguity, or the action involves irreversible external side effects."]}, {"id": "KP3", "description": "Persist workflow state (`LangGraph` checkpointer) and hand off a rich Context Bundle to the human operator without losing user progress.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph PostgresSaver checkpointer, thread_id state snapshot, context handoff bundle (conversation history, retrieved chunks, draft response, failure reason).", "Explains checkpointing the exact graph state in PostgreSQL/Redis and routing a structured ticket to the human review UI containing the user query, conversation history, retrieved documents, failed model draft, and diagnostic reason so the human resolves it in seconds without asking the user to repeat themselves."]}, {"id": "KP4", "description": "Log the human resolution into an immutable Audit Trail and feed adjudicated corrections back into the Golden Dataset.", "required": false, "acceptable_evidence": ["Technical keywords: immutable audit log (reviewer_id, timestamp, diff), Golden Dataset expansion, DPO/few-shot feedback loop.", "Explains recording the human edit/approval for compliance auditing and promoting the resolved failure case into the DeepEval Golden Dataset."]}], "critical_failures": ["Exposes raw Python stack traces, broken JSON fragments, or unverified hallucinated guesses directly to the end user when the AI fails.", "Escalates to a human operator as a blank slate without passing the conversation state, retrieved context, or failure diagnostics."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do tools like linting, unit testing, and SonarQube contribute to maintaining code quality and security standards?', '{"key_points": [{"id": "KP1", "description": "Explain Linting & Static Type Checking (`ruff`, `flake8`, `ESLint`, `mypy`) as fast millisecond feedback catching syntax bugs, anti-patterns, and style drift.", "required": true, "acceptable_evidence": ["Technical keywords: ruff / flake8 / ESLint, mypy, AST static inspection, unused variables/imports, mutable default args, bare excepts.", "Explains that linters parse the Abstract Syntax Tree (AST) in milliseconds inside the IDE and `pre-commit` hooks to catch unused imports, undefined symbols, mutable default arguments, and formatting inconsistencies before a commit is even created."]}, {"id": "KP2", "description": "Explain Unit Testing (`pytest`, `Vitest`) as runtime behavioral verification of functional logic, boundary edge cases, and regressions.", "required": true, "acceptable_evidence": ["Technical keywords: pytest / Vitest, runtime behavioral correctness, boundary edge cases, mocking external dependencies, coverage report (coverage.xml).", "Explains that while linters check static syntax/structure, unit tests execute the code against controlled inputs and edge cases to verify that business logic, mathematical calculations, and error handlers behave accurately at runtime and generate `coverage.xml` artifacts."]}, {"id": "KP3", "description": "Explain `SonarQube` Quality Gates (SAST security hotspots, OWASP Top 10 taint analysis, cyclomatic/cognitive complexity, code duplication, and Clean-as-You-Code coverage gates).", "required": true, "acceptable_evidence": ["Technical keywords: SonarQube Quality Gate, SAST (SQL injection, XSS, hardcoded secrets, SSRF), cognitive/cyclomatic complexity, code duplication %, coverage on new code (>=80%).", "Explains that SonarQube aggregates `coverage.xml` with deep SAST taint analysis and maintainability metrics, enforcing a blocking PR **Quality Gate** on *New Code* (e.g., 0 new vulnerabilities/bugs, $\\\\ge 80\\\\%$ test coverage on modified lines, $<3\\\\%$ duplication, and bounded cognitive complexity)."]}], "critical_failures": ["Cannot distinguish static analysis (Linting/SonarQube inspecting AST/dataflow without executing code) from dynamic verification (Unit Testing executing functions at runtime).", "Treats SonarQube only as a passive dashboard without enforcing blocking Quality Gates on Pull Requests."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How do you design an AI system that supports human-in-the-loop workflows, including pausing execution and requiring user approval before tool actions?', '{"key_points": [{"id": "KP1", "description": "Classify tools by risk tier (`Read-Only` auto-approved vs `Mutating / Financial / External` requiring mandatory HITL interrupt).", "required": true, "acceptable_evidence": ["Technical keywords: tool risk taxonomy, read-only vs state-mutating tools, policy threshold gating, MCP tool metadata.", "Explains tagging every registered tool with a risk policy: safe read-only queries (`search_docs`, `get_order_status`) execute autonomously, whereas state-mutating or external actions (`execute_sql_write`, `issue_refund`, `send_customer_email`, `delete_resource`) require explicit approval."]}, {"id": "KP2", "description": "Implement durable State Checkpointing (`LangGraph` `PostgresSaver` + `interrupt_before=[''tool_executor'']` / `interrupt()`) without holding threads open.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, PostgresSaver / AsyncPostgresSaver checkpointer, thread_id, interrupt_before / dynamic interrupt(), zero-compute suspension.", "Explains compiling the agent state graph with a persistent database checkpointer (`PostgresSaver`) keyed by `thread_id` and configuring `interrupt_before=[''sensitive_tool_node'']`: when the LLM proposes a sensitive tool call, the graph serializes the full state to Postgres, emits a `PENDING_APPROVAL` payload to the UI, and releases the worker process completely."]}, {"id": "KP3", "description": "Support three structured human resume outcomes (`Approve`, `Edit Arguments`, or `Reject with Feedback`) via `Command(resume=...)` / state update.", "required": true, "acceptable_evidence": ["Technical keywords: Approve / Edit / Reject workflows, update_state / Command(resume=...), modified tool arguments, rejection ToolMessage.", "Explains how the backend resumes the paused `thread_id` once the user responds: (1) **Approve** executes the exact proposed tool call, (2) **Edit** patches the tool arguments in the checkpoint state (e.g., adjusting refund amount) before executing, and (3) **Reject** injects a `ToolMessage` stating the action was denied with the user''s reason so the agent replans safely."]}, {"id": "KP4", "description": "Enforce RBAC authorization, approval TTL expiration, idempotency keys, and an immutable compliance audit log.", "required": true, "acceptable_evidence": ["Technical keywords: approver JWT RBAC verification, approval TTL expiration, idempotency key (preventing double execution on double-click), immutable audit trail.", "Explains verifying that the approving user''s JWT has permission for that action, expiring stale pending approvals after a TTL, guarding the resume endpoint with an idempotency key, and logging `(thread_id, proposed_args, approver_id, decision, timestamp)`."]}], "critical_failures": ["Pauses execution using `input()` or `asyncio.sleep()` in local process memory, holding HTTP connections open and losing all state if the pod restarts or scales.", "Asks the LLM via prompt instructions (''Please ask the user for permission before calling the tool'') without enforcing a hard programmatic checkpoint before the tool execution node."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'HARD', 'BROAD', 210, 'How do you design utility functions and scoring mechanisms for candidates under multiple hypotheses?', '{"key_points": [{"id": "KP1", "description": "Formulate Bayesian Expected Utility $EU(c) = \\\\sum_{h \\\\in \\\\mathcal{H}} P(h \\\\mid x) \\\\cdot U(c, h) - \\\\text{Cost}(c)$ over mutually exclusive or competing hypotheses $\\\\mathcal{H}$.", "required": true, "acceptable_evidence": ["Technical keywords: Expected Utility Theory, posterior probability P(h | x), hypothesis space H, multi-objective utility U(c, h), risk/cost penalty.", "Explains that when evaluating candidates $c$ under uncertain hypotheses $h \\\\in \\\\mathcal{H}$ (e.g., ambiguous user intent in search/RAG, competing fraud/legitimate regimes, or multi-criteria candidate ranking), the scoring mechanism weights the conditional utility $U(c, h)$ of candidate $c$ under hypothesis $h$ by the posterior probability $P(h \\\\mid x)$ rather than committing greedily to only $\\\\arg\\\\max_h P(h \\\\mid x)$."]}, {"id": "KP2", "description": "Normalize and calibrate heterogeneous sub-scores onto a commensurate probability or utility scale (`Platt` / `Isotonic` calibration, `z-score` / `min-max` / `RRF`).", "required": true, "acceptable_evidence": ["Technical keywords: probability calibration (Platt scaling, Isotonic regression, temperature scaling), Brier score / ECE, score normalization, Reciprocal Rank Fusion (RRF).", "Explains that raw scores from different hypothesis models or retrievers (e.g., unbounded BM25 logits vs cosine similarities vs tree probabilities) cannot be added directly; probabilities $P(h \\\\mid x)$ must be calibrated (verified via Brier score / ECE) and sub-utilities normalized to $[0, 1]$ before linear or log-linear combination."]}, {"id": "KP3", "description": "Incorporate asymmetric error costs, hard constraint masks, and risk-aversion / uncertainty penalties (Mean-Variance / Lower Confidence Bound).", "required": true, "acceptable_evidence": ["Technical keywords: asymmetric cost matrix, hard feasibility multiplier I(feasible), variance/uncertainty penalty (LCB = mu - lambda*sigma), Maximal Marginal Relevance (MMR) diversity.", "Explains multiplying the utility by a hard feasibility indicator $\\\\mathbb{I}(\\\\text{constraints}(c) = 1)$ (so policy/eligibility violations score $-\\\\infty$) and penalizing high-variance candidates in risk-sensitive domains ($U_{\\\\text{risk-adjusted}}(c) = \\\\mathbb{E}[U(c)] - \\\\lambda \\\\sqrt{\\\\text{Var}(U(c))}$) or diversifying across hypotheses via MMR."]}, {"id": "KP4", "description": "Tune utility weights $(\\\\mathbf{w})$ empirically via offline Pareto frontier analysis (`NDCG@K`, `PR-AUC`), Bayesian Optimization, and online A/B / Bandit feedback.", "required": true, "acceptable_evidence": ["Technical keywords: Pareto frontier optimization, Optuna / Bayesian hyperparameter tuning, Learning-to-Rank (LambdaMART), contextual bandit / online A/B validation.", "Explains tuning the multi-objective utility weights on a held-out golden validation set to map the Pareto trade-off frontier (e.g., relevance vs latency vs diversity/safety) and validating the chosen operating point via online A/B experiments."]}], "critical_failures": ["Sums raw uncalibrated logits or incompatible metric scales (e.g., adding raw BM25 score `[0..45]` to cosine similarity `[-1..1]`) without normalization or probability calibration.", "Commits 100% to a single top-1 hypothesis when posterior entropy is high ($P(h_1)=0.51, P(h_2)=0.49$), ignoring the catastrophic cost if $h_2$ is the true state."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure that your implementation integrates correctly with existing code that expects certain interfaces or behaviors?', '{"key_points": [{"id": "KP1", "description": "Audit both the Explicit Interface (`typing.Protocol` / `ABC`, method signatures, return types) and Implicit Behavioral Invariants (side effects, exceptions, ordering, thread/async semantics).", "required": true, "acceptable_evidence": ["Technical keywords: typing.Protocol, Abstract Base Class (ABC), Liskov Substitution Principle (LSP), pre-conditions and post-conditions, exception contract.", "Explains inspecting the existing interface and caller sites to preserve Liskov Substitution: matching not only parameter and return types (`mypy --strict`), but also behavioral contracts (e.g., whether callers expect an empty list `[]` vs `None` vs raising `KeyError` on missing data, and whether inputs must remain unmutated)."]}, {"id": "KP2", "description": "Use the Adapter Pattern when wrapping a new module or model whose native signature differs from the legacy interface.", "required": true, "acceptable_evidence": ["Technical keywords: Adapter design pattern, DTO schema translation (Pydantic), exception mapping, zero caller modification.", "Explains implementing an Adapter class that conforms 100% to the legacy interface expected by callers while translating inputs, return payloads, and exception types to/from the new implementation internally."]}, {"id": "KP3", "description": "Verify parity using parametrized Contract Tests (`pytest` running the exact same test suite against both old and new implementations) and Shadow / Dark-Launch verification.", "required": true, "acceptable_evidence": ["Technical keywords: parameterized interface contract tests (@pytest.fixture(params=[OldImpl, NewImpl])), characterization tests, shadow/dark-launch parity comparison.", "Explains running the existing consumer test suite plus a shared `@pytest.fixture(params=[LegacyImpl, NewImpl])` contract test suite against both implementations, and optionally dark-launching (shadowing) in production to verify output parity before switching traffic."]}], "critical_failures": ["Changes the return type (e.g., returning a `dict` or `None` where existing callers expect a `list`) or raises new unhandled exception types that crash upstream callers.", "Tests the new implementation only in isolation with custom mocks without running integration tests against the actual calling code."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you evaluate and validate AI-generated code to ensure correctness and alignment with requirements?', '{"key_points": [{"id": "KP1", "description": "Enforce Test-Driven / Contract-First Validation (defining `Pydantic` schemas and human-reviewed `pytest` acceptance tests *before* or independently of the AI implementation).", "required": true, "acceptable_evidence": ["Technical keywords: TDD / specification-first validation, independent pytest acceptance tests, avoiding tautological AI self-testing.", "Explains never allowing an AI assistant to write both the implementation and the only tests unreviewed (as the AI will write tests that assert its own buggy assumptions); acceptance criteria, boundary cases, and I/O contracts are specified and verified against the business requirements."]}, {"id": "KP2", "description": "Run Automated Static, Type, and Security Gates (`ruff`, `mypy --strict`, `bandit`/`Semgrep`, dependency verification).", "required": true, "acceptable_evidence": ["Technical keywords: mypy --strict, ruff, bandit / Semgrep SAST, dependency verification (preventing hallucinated packages), cyclomatic complexity.", "Explains running strict static type checking and SAST analysis to catch hallucinated SDK methods, deprecated APIs, SQL/command injection, missing `timeout` parameters, and unverified third-party imports."]}, {"id": "KP3", "description": "Audit Algorithmic Complexity ($O(N)$ vs $O(N^2)$), Concurrency/Async Safety, and Domain Invariants via Manual Line-by-Line Diff Review.", "required": true, "acceptable_evidence": ["Technical keywords: Big-O complexity review, N+1 query check, async event-loop non-blocking audit, tenant RBAC enforcement, ML data leakage audit.", "Explains manually inspecting the diff for non-functional requirements that pass basic unit tests but fail in production: $O(N^2)$ list lookups inside loops, blocking synchronous calls inside `async def`, missing `tenant_id` authorization filters, or temporal leakage in ML pipelines."]}, {"id": "KP4", "description": "Validate runtime behavior with boundary/property-based tests (`Hypothesis`), mutation checks, and staging integration tests.", "required": false, "acceptable_evidence": ["Technical keywords: @pytest.mark.parametrize edge cases, Hypothesis property-based testing, mutation check (breaking code to verify test fails).", "Explains stress-testing the code with nulls, empty collections, unicode, and concurrency races, and confirming tests actually fail when the implementation is perturbed."]}], "critical_failures": ["Assumes AI-generated code is correct because the AI also generated a unit test that passes (''green checkmark fallacy'').", "Skips security and algorithmic complexity reviews on AI-generated code."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate the quality of AI-generated code review comments beyond just the number of comments?', '{"key_points": [{"id": "KP1", "description": "Measure Developer Actionability & Precision (`Resolution / Commit-Fix Rate`, `Thumbs-Up/Down Ratio`, and `False-Positive Dismissal Rate`).", "required": true, "acceptable_evidence": ["Technical keywords: Actionability / Acceptance Rate (% of comments resulting in a subsequent commit fix or ''Apply Suggestion''), False-Positive Noise Rate, developer thumbs-up/down.", "Explains that comment volume is an anti-metric (high volume causes alert fatigue): the primary online quality metric is **Actionability Precision**—the percentage of AI review comments that actually lead the PR author to modify the flagged lines or click ''Commit Suggestion'' versus being dismissed as false positives."]}, {"id": "KP2", "description": "Benchmark Offline Defect Recall & Severity Stratification against a Curated Golden PR Dataset (Seeded Bugs, Security Flaws, Logic Errors vs Trivial Style Nits).", "required": true, "acceptable_evidence": ["Technical keywords: Golden PR Benchmark (historical bug-introducing PRs), Defect Recall@K, severity weighting (Critical Security/Concurrency/Leakage vs Trivial Style Nit), line-localization accuracy.", "Explains evaluating the review agent offline against a versioned Golden Dataset of historical PRs with known ground-truth defects (race conditions, SQLi/BOLA, null dereferences, $O(N^2)$ regressions), measuring both **Line-Level Localization Recall** and **Severity Mix** (penalizing trivial bikeshedding nits that linters should handle)."]}, {"id": "KP3", "description": "Verify Technical Correctness of Suggested Code Patches (AST/Compile validity, `pytest` pass rate when applied, and Faithfulness to repo context).", "required": true, "acceptable_evidence": ["Technical keywords: patch syntactic/type validity (ruff/mypy), test pass rate of applied suggestion, RAG context grounding (no hallucinated internal helpers).", "Explains automatically applying the AI reviewer''s proposed ```suggestion``` code block in a sandboxed CI runner to verify that it compiles, passes `mypy`/`ruff`, and passes `pytest` without inventing non-existent repository functions."]}, {"id": "KP4", "description": "Track Downstream Engineering Impact (PR Cycle Time / Turnaround Reduction and Post-Merge Escaped Defect Rate).", "required": false, "acceptable_evidence": ["Technical keywords: PR time-to-merge reduction, human review iteration rounds, escaped production defect rate.", "Explains correlating AI review adoption with reduced human review back-and-forth rounds and lower post-merge hotfix rates."]}], "critical_failures": ["Rewards the AI code review system for generating a high count of verbose, generic style comments (''Add a docstring here'', ''Consider renaming variable'') that developers ignore.", "Never tests whether the code patches suggested in the AI''s review comments actually compile or pass the test suite."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle failures and debug issues in production AI systems?', '{"key_points": [{"id": "KP1", "description": "Contain immediate user blast radius via Circuit Breakers, Model/Prompt/Helm Rollbacks, and Graceful Fallbacks.", "required": true, "acceptable_evidence": ["Technical keywords: blast radius containment, circuit breaker failover, helm rollback, MLflow @champion alias / prompt version revert, graceful fallback.", "Explains that production incident handling starts with stabilization: if 5xx error rates, latency, or guardrail violation alarms fire after a release, immediately revert the prompt version, MLflow `@champion` alias, or Helm deployment, or trip the circuit breaker to a backup model/deterministic fallback."]}, {"id": "KP2", "description": "Isolate the failing pipeline layer using End-to-End Distributed Tracing (`OpenTelemetry` / `Langfuse` / `Arize Phoenix` span waterfalls).", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry trace_id, Langfuse / Arize Phoenix span waterfall, isolating Ingestion/Feature Skew vs Retrieval (Recall/Reranker) vs Prompt/LLM vs Tool Failure.", "Explains that AI failures are rarely simple crashes—they are silent quality or latency regressions; inspecting the `trace_id` span tree isolates whether the failure originated in (1) missing/corrupted upstream features or embeddings, (2) poor retrieval/reranking (irrelevant chunks fetched), (3) prompt/context truncation or model hallucination, or (4) downstream MCP tool timeout/schema error."]}, {"id": "KP3", "description": "Reproduce the failure deterministically in an offline harness (`temperature=0`, pinned prompt/model/context snapshot from the trace).", "required": true, "acceptable_evidence": ["Technical keywords: deterministic trace replay, exact prompt + retrieval_context snapshot, DeepEval LLMTestCase reproduction, PSI/KS drift check.", "Explains exporting the exact sanitized trace snapshot (input query, retrieved chunk IDs/text, system prompt version, model parameters) into a local `pytest` / `DeepEval` test case to reproduce and fix the root cause deterministically."]}, {"id": "KP4", "description": "Promote the incident trace into the Permanent Golden Regression Dataset and add targeted guardrail/alert coverage.", "required": true, "acceptable_evidence": ["Technical keywords: Golden Dataset regression case promotion, CI/CD evaluation gate, blameless post-mortem.", "Explains converting every resolved production incident into a permanent test case in the Golden Evaluation Dataset so future prompt, retriever, or model updates in CI/CD can never reintroduce that failure mode."]}], "critical_failures": ["Tweaks production prompts blindly (''prompt whack-a-mole'') without first inspecting the trace to see whether retrieval or upstream data was the actual culprit.", "Logs only HTTP 200/500 status codes without tracing intermediate retrieval chunks, prompt versions, token counts, or tool arguments."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle unexpected technical issues, such as a platform outage, during a live coding interview?', '{"key_points": [{"id": "KP1", "description": "Pivot calmly within 30 seconds to an alternative shared surface (local IDE + screen share, Google Doc, or plain text editor) without losing momentum.", "required": true, "acceptable_evidence": ["Technical keywords: rapid fallback (local VS Code screen share, shared doc/pad), composure under ambiguity, zero time wasted debugging third-party platform.", "Explains staying composed, acknowledging the platform issue immediately with the interviewer, and proposing a 15-second pivot (sharing a local IDE/terminal or a shared text document) rather than burning 15 minutes of interview time troubleshooting CoderPad/HackerRank."]}, {"id": "KP2", "description": "Replace automated code execution with a rigorous, line-by-line Manual Dry-Run State Table when a compiler/runtime is unavailable.", "required": true, "acceptable_evidence": ["Technical keywords: manual dry-run execution table, comment-block variable state trace (step, i, j, seen_set, return_val), loop invariant verification.", "Explains that when code cannot be executed live, you demonstrate strong engineering mastery by acting as the Python interpreter: writing a structured comment table below the function and tracing exact variable states (`i`, `curr_sum`, `hash_map`, pointer bounds) step-by-step on a small happy-path input and boundary edge cases (`[]`, single item, duplicates)."]}, {"id": "KP3", "description": "Proactively audit syntax, off-by-one bounds, and type contracts (`mypy`-style mental pass) before concluding.", "required": true, "acceptable_evidence": ["Technical keywords: off-by-one index audit, base-case termination check, type consistency check, complexity summary.", "Explains performing a deliberate static pass over the written code—verifying loop termination, base cases, dictionary key existence (`dict.get` vs `KeyError`), and time/space complexity."]}], "critical_failures": ["Panics, freezes, or blames the platform without offering a practical fallback or dry-running the logic.", "Writes sloppy pseudocode and skips edge-case verification because the ''Run'' button is unavailable."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you make a class thread-safe in Python, and what concurrency issues does it address?', '{"key_points": [{"id": "KP1", "description": "Identify the concurrency hazards addressed: Race Conditions on Check-Then-Act / Read-Modify-Write (`self.count += 1`), Torn Reads/Writes, and Invariant Corruption (even with the CPython GIL).", "required": true, "acceptable_evidence": ["Technical keywords: race condition, non-atomic read-modify-write (LOAD_ATTR, BINARY_OP, STORE_ATTR bytecode interleaving), check-then-act TOCTOU, GIL context switch between bytecodes.", "Explains that the CPython GIL does NOT make user classes thread-safe: compound operations like `self.balance += amount` or `if key not in self.cache: self.cache[key] = compute()` compile to multiple bytecode instructions across which the OS/interpreter can switch threads, causing lost updates and corrupted multi-attribute invariants."]}, {"id": "KP2", "description": "Synchronize critical sections using an instance-level `threading.Lock()` or `threading.RLock()` via the `with self._lock:` context manager.", "required": true, "acceptable_evidence": ["Technical keywords: threading.Lock, threading.RLock (reentrant lock for internal method-to-method calls), with self._lock: context manager (exception-safe release).", "Explains initializing `self._lock = threading.Lock()` (or `threading.RLock()` if one locked public method calls another locked method on `self`) in `__init__` and wrapping all state mutations and multi-field reads inside `with self._lock:`, guaranteeing the lock is released even if an exception is raised."]}, {"id": "KP3", "description": "Use Immutability (`@dataclass(frozen=True)`), Thread-Safe Queues (`queue.Queue`), and keep external I/O outside the lock to prevent Deadlocks and contention.", "required": true, "acceptable_evidence": ["Technical keywords: frozen immutable state, queue.Queue, threading.local, minimizing critical section scope (no network I/O inside lock), consistent lock acquisition order.", "Explains keeping critical sections minimal (never holding `self._lock` across slow network/disk I/O), returning defensive copies of internal mutable collections, or eliminating shared mutable state altogether via `@dataclass(frozen=True)` or `queue.Queue`."]}], "critical_failures": ["Claims the Python GIL automatically makes all Python classes and `self.counter += 1` operations 100% thread-safe without locks.", "Calls `self._lock.acquire()` and `self._lock.release()` manually without a `with` block or `try...finally`, permanently deadlocking all threads if an exception occurs inside the method."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you optimize React applications using techniques like memoization, lazy loading, and bundling?', '{"key_points": [{"id": "KP1", "description": "Apply Component & Computation Memoization (`React.memo`, `useMemo`, `useCallback`) selectively on expensive subtrees and referential props.", "required": true, "acceptable_evidence": ["Technical keywords: React.memo (shallow prop comparison), useMemo (expensive filtering/sorting/chart transforms), useCallback (referential function stability), React DevTools Profiler.", "Explains using `useMemo` to cache expensive client-side calculations (e.g., sorting/filtering 10,000 rows or parsing markdown ASTs) and pairing `React.memo` with `useCallback` so heavy child components skip re-rendering when parent state changes—guided by React DevTools Profiler measurements."]}, {"id": "KP2", "description": "Implement Route-Level and Component-Level Code Splitting using dynamic `import()`, `React.lazy()`, and `<Suspense>` boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: React.lazy(() => import(''./HeavyChart'')), <Suspense fallback={<Skeleton />}>, route-based code splitting, intersection observer image/list lazy loading.", "Explains deferring download and parse of heavy routes, admin modals, or charting/PDF/Monaco-editor libraries using `React.lazy(() => import(...))` wrapped in `<Suspense>`, plus virtualizing long DOM lists (`@tanstack/react-virtual`) so only visible rows mount."]}, {"id": "KP3", "description": "Optimize Bundling in Vite/Webpack (Tree-Shaking ES Modules, `manualChunks` vendor splitting, Brotli/Gzip compression, and Bundle Analyzer audits).", "required": true, "acceptable_evidence": ["Technical keywords: ES module tree-shaking (named imports), rollup-plugin-visualizer / webpack-bundle-analyzer, vendor chunk splitting (manualChunks), content-hash cache headers, Brotli compression.", "Explains inspecting the bundle treemap (`rollup-plugin-visualizer`) to replace bloated dependencies (e.g., `moment` $\\\\rightarrow$ `date-fns`), using named ES imports for tree-shaking, splitting stable vendor chunks (`react`, `react-dom`) for long-term CDN caching (`Cache-Control: immutable`), and serving Brotli-compressed assets."]}, {"id": "KP4", "description": "Measure impact against Core Web Vitals (`LCP`, `INP`, `CLS`, and Time-To-Interactive).", "required": false, "acceptable_evidence": ["Technical keywords: Core Web Vitals, Largest Contentful Paint (LCP), Interaction to Next Paint (INP), Cumulative Layout Shift (CLS), Lighthouse CI.", "Explains verifying that bundling/lazy-loading improves initial `LCP` while memoization/virtualization keeps `INP` under 200ms."]}], "critical_failures": ["Imports entire monolithic libraries (`import _ from ''lodash''`) into a single multi-megabyte main bundle blocking initial page load.", "Uses `React.lazy` without wrapping the component tree in a `<Suspense>` boundary, causing a runtime React crash."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How do you use browser developer tools, such as inspecting the DOM, debugging JavaScript, and analyzing HTTP requests, to diagnose issues?', '{"key_points": [{"id": "KP1", "description": "Inspect the `Elements` (DOM & Computed CSS) tab and DOM Mutation Breakpoints to diagnose layout shifts, `z-index`/stacking contexts, and event listeners.", "required": true, "acceptable_evidence": ["Technical keywords: Elements panel, Computed styles cascade/specificity, box model, Break on -> subtree modifications, Event Listeners inspector, accessibility tree.", "Explains using the Computed pane to trace overridden CSS rules, flexbox/grid constraints, and `overflow`/`z-index` clipping, and setting ''Break on subtree modification'' when third-party or React code unexpectedly mutates a DOM node."]}, {"id": "KP2", "description": "Debug JavaScript/TypeScript execution in the `Sources` & `Console` tabs using Conditional Breakpoints, Logpoints, Call Stack/Scope inspection, and Source Maps.", "required": true, "acceptable_evidence": ["Technical keywords: Sources panel, Source Maps, conditional breakpoints, logpoints, Pause on Caught/Uncaught Exceptions, Call Stack & Closure Scope inspection.", "Explains enabling ''Pause on uncaught exceptions'', setting conditional breakpoints (e.g., `item.id === ''err_42''`) or non-intrusive Logpoints across TypeScript source maps, and inspecting closure scopes and async call stacks without littering code with `console.log`."]}, {"id": "KP3", "description": "Analyze the `Network` tab for API status/CORS failures, SSE/WebSocket token streams, Waterfall timing (`TTFB`), and `Copy as cURL` reproduction.", "required": true, "acceptable_evidence": ["Technical keywords: Network panel, HTTP status (401/403/422/429/5xx), CORS preflight OPTIONS headers, EventStream (SSE) / WS frames, Waterfall TTFB, Copy as cURL, network throttling.", "Explains inspecting request/response JSON payloads (e.g., FastAPI `422 Unprocessable Entity` Pydantic validation details), CORS `Access-Control-Allow-Origin` preflight failures, real-time `EventStream` (SSE) chunks for LLM streaming, waterfall `TTFB` latency, and exporting failing requests via ''Copy as cURL'' for backend reproduction."]}, {"id": "KP4", "description": "Profile runtime jank, memory leaks, and browser storage in the `Performance`, `Memory` (Heap Snapshots), `Application`, and `React DevTools` tabs.", "required": false, "acceptable_evidence": ["Technical keywords: Performance flamegraph (Long Tasks > 50ms), Memory Heap Snapshot (Detached DOM nodes), Application tab (localStorage/Cookies/JWT), React DevTools Profiler.", "Explains capturing Heap Snapshots to find detached DOM trees or uncleared `setInterval`/event-listener leaks and using React DevTools Profiler to pinpoint why a component re-rendered."]}], "critical_failures": ["Relies exclusively on `console.log` without knowing how to inspect the Network tab payload/headers or set breakpoints in the Sources tab.", "Cannot distinguish a frontend JavaScript rendering error from a backend `422`/`500` API error or CORS preflight rejection in the Network tab."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'How would you approach debugging a PyTorch-based model in a production-like environment?', '{"key_points": [{"id": "KP1", "description": "Verify Inference-Mode Invariants first (`model.eval()`, `with torch.inference_mode():`, deterministic seeds, and Training-Serving Preprocessing Parity).", "required": true, "acceptable_evidence": ["Technical keywords: model.eval() (disabling Dropout and locking BatchNorm running stats), torch.inference_mode() / torch.no_grad(), training-serving normalization/tokenizer parity.", "Explains checking the most common silent production PyTorch bugs first: forgetting `model.eval()` (leaving `Dropout` active and updating `BatchNorm` stats on single inference batches), forgetting `with torch.inference_mode():` (leaking autograd computation graphs and causing GPU OOMs), or mismatched input normalization/tokenization between training and serving."]}, {"id": "KP2", "description": "Diagnose Tensor Shape, Dtype (`fp16`/`bf16`/`fp32`), and Device (`cpu` vs `cuda:0`) mismatches plus `NaN`/`Inf` numerical instability.", "required": true, "acceptable_evidence": ["Technical keywords: tensor.shape / dtype / device assertions, torch.isnan() / torch.isinf(), register_forward_hook, torch.autograd.set_detect_anomaly(True), FP16 overflow vs BF16.", "Explains attaching lightweight `register_forward_hook` inspectors (or `torch.isnan(x).any()`) across layers to isolate the exact submodule where activations turn to `NaN`/`Inf` (often caused by unnormalized division, log-of-zero, or `FP16` overflow in attention logits)."]}, {"id": "KP3", "description": "Debug GPU Memory Leaks, CUDA OOMs, and Latency Bottlenecks using `torch.cuda.memory_summary()`, `CUDA_LAUNCH_BLOCKING=1`, and `torch.profiler`.", "required": true, "acceptable_evidence": ["Technical keywords: CUDA_LAUNCH_BLOCKING=1 (synchronous CUDA stack traces), torch.cuda.memory_summary() / memory_snapshot(), .item()/.detach().cpu() tensor retention leak, torch.profiler.", "Explains that CUDA kernels execute asynchronously so stack traces point to the wrong line unless `CUDA_LAUNCH_BLOCKING=1` is set in staging; memory leaks from appending `.loss` tensors (instead of `loss.detach().item()`) or unfreed KV-caches are isolated via `torch.cuda.memory_snapshot()`, and CPU-to-GPU sync bottlenecks are profiled with `torch.profiler`."]}, {"id": "KP4", "description": "Validate numerical parity against a Golden Input-Output Reference Tensor (`torch.testing.assert_close`) in CI before deployment.", "required": false, "acceptable_evidence": ["Technical keywords: torch.testing.assert_close(actual, expected, rtol, atol), golden reference tensor artifact, ONNX/TorchScript parity check.", "Explains saving a golden `(input_tensor, expected_logits_tensor)` pair inside the MLflow model artifact and asserting `torch.testing.assert_close` on container startup."]}], "critical_failures": ["Runs production PyTorch inference without `model.eval()` and `torch.inference_mode()` / `torch.no_grad()`, causing stochastic predictions and autograd memory exhaustion.", "Appends raw PyTorch tensors (`history.append(output_tensor)`) across requests without `.detach().cpu()`, leaking the entire autograd graph in GPU VRAM."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 210, 'How would you approach defining the necessary technical standards, development processes, and setting the direction for the firm''s first internal software engineering function?', '{"key_points": [{"id": "KP1", "description": "Audit current business workflows, data silos, and high-ROI pain points to define a pragmatic 30-60-90 Day Engineering Roadmap.", "required": true, "acceptable_evidence": ["Technical keywords: stakeholder discovery audit, build-vs-buy matrix, 30-60-90 day roadmap, high-ROI quick wins vs foundational platform.", "Explains starting by mapping existing manual/spreadsheet or ad-hoc script workflows across the firm, quantifying operational bottlenecks and compliance risks, and establishing a 30-60-90 day plan that pairs an early high-value production delivery (building executive trust) with foundational platform standards."]}, {"id": "KP2", "description": "Standardize the Paved-Road Golden Tech Stack and Repository Templates (`Python`/`FastAPI`, `React`/`TypeScript`, `PostgreSQL`, `Docker`/`Terraform`).", "required": true, "acceptable_evidence": ["Technical keywords: Paved Road / Golden Path cookiecutter template, standardized stack (Python, FastAPI, Pydantic, uv/Poetry, Docker, AWS/Terraform), avoiding tool sprawl.", "Explains preventing fragmentation by providing a turnkey repository template (''Golden Path'') pre-wired with `pyproject.toml`, `ruff`, `mypy --strict`, `pytest`, `Dockerfile`, structured JSON logging, and Terraform IaC modules."]}, {"id": "KP3", "description": "Institute non-negotiable SDLC & CI/CD Engineering Processes (Trunk-based Git, mandatory PR reviews, automated CI test gates, and `dev` $\\\\rightarrow$ `staging` $\\\\rightarrow$ `prod` promotion).", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions / GitLab CI, branch protection, mandatory code review, automated pytest/linter gates, environment isolation (dev/staging/prod), ADRs.", "Explains eliminating manual production edits and unversioned scripts by enforcing protected branches, automated CI test/security gates, Architecture Decision Records (ADRs), and zero-downtime automated deployments."]}, {"id": "KP4", "description": "Embed Security, Data Governance, and Observability from Day 1 (SSO/RBAC, Secrets Manager, Prometheus/CloudWatch, and Incident Runbooks).", "required": true, "acceptable_evidence": ["Technical keywords: least-privilege IAM/RBAC, AWS Secrets Manager, PII/compliance controls, centralized logging/metrics, DORA metrics (Deployment Frequency, Lead Time, Change Failure Rate, MTTR).", "Explains baking security and observability into the foundation and measuring the new engineering function''s maturity via DORA metrics and business ROI."]}], "critical_failures": ["Spends 6+ months building an over-engineered internal platform in a vacuum without shipping any business value to stakeholders.", "Allows every engineer to pick different languages, databases, and manual deployment scripts without standardized CI/CD, testing, or security governance."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you balance automated testing versus functional testing in a project?', '{"key_points": [{"id": "KP1", "description": "Apply the Testing Pyramid allocation (~70% fast Unit tests, ~20% Integration/Contract/API Functional tests, ~10% E2E UI & Exploratory Functional tests).", "required": true, "acceptable_evidence": ["Technical keywords: Testing Pyramid, unit tests (pytest/Vitest), integration/API functional tests (TestClient/PostgreSQL), E2E tests (Playwright), execution speed vs flakiness.", "Explains clarifying that automated and functional testing are complementary (functional tests verify *what* the system does against business requirements and can be automated at the API/E2E level or run manually for exploratory UX): structuring ~70% fast unit tests, ~20% automated API/service functional tests, and ~10% critical-path E2E + human exploratory checks."]}, {"id": "KP2", "description": "Automate deterministic, repeatable regression paths, data/API contracts, and AI Golden Dataset gates in CI/CD.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD regression automation, Pydantic/OpenAPI contract validation, RBAC security checks, DeepEval golden regression suite.", "Explains automating any check that must run on every PR commit: pure business logic, boundary edge cases, API status/schema contracts, RBAC permissions, and golden-dataset RAG/ML regression thresholds."]}, {"id": "KP3", "description": "Reserve human Exploratory Functional Testing & SME UAT for novel UX workflows, multi-turn AI edge discovery, and visual/accessibility nuances, then codify findings into automated tests.", "required": true, "acceptable_evidence": ["Technical keywords: exploratory functional testing, SME User Acceptance Testing (UAT), red-teaming/adversarial discovery, bug-to-automated-test ratchet.", "Explains using manual functional and SME exploratory testing where human judgment excels (evaluating new UI usability, adversarial red-teaming of conversational AI flows, and initial UAT), and immediately converting every discovered defect into an automated regression test."]}], "critical_failures": [" builds an ''Inverted Ice-Cream Cone'' testing strategy (relying almost entirely on slow, flaky manual or browser UI tests with zero fast unit/API tests).", "Automates brittle UI tests on rapidly prototyping screens while leaving core backend billing/security/scoring logic untested."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you design an algorithm to find the second highest number in a given list, and what edge cases would you consider?', '{"key_points": [{"id": "KP1", "description": "Implement a single-pass $O(N)$ time, $O(1)$ auxiliary space algorithm tracking `first` and `second` initialized to `-math.inf`.", "required": true, "acceptable_evidence": ["Technical keywords: single-pass O(N) time, O(1) space, first = second = float(''-inf''), elif first > x > second: second = x.", "Explains iterating through the list once with `first = second = float(''-inf'')`: for each number `x`, if `x > first`, update `second = first` and `first = x`; `elif first > x > second` (strictly less than `first` to handle duplicate maximums cleanly), update `second = x`."]}, {"id": "KP2", "description": "Contrast why the single-pass $O(N)$ / $O(1)$ approach outperforms `sorted(set(nums))[-2]` ($O(N \\\\log N)$ time and $O(N)$ space).", "required": true, "acceptable_evidence": ["Technical keywords: O(N) vs O(N log N) sorting overhead, O(1) vs O(N) set allocation, heapq.nlargest(2, ...).", "Explains that sorting unique elements (`sorted(set(nums))[-2]`) allocates $O(N)$ memory and takes $O(N \\\\log N)$ time (and mutates the caller''s list if `.sort()` is used), whereas tracking two scalar variables takes $O(N)$ time and $O(1)$ space."]}, {"id": "KP3", "description": "Handle all critical edge cases: fewer than 2 elements (`[]`, `[5]`), all identical elements (`[7, 7, 7]`), duplicate maximums (`[10, 10, 8]`), and all negative numbers (`[-5, -2, -9]`).", "required": true, "acceptable_evidence": ["Technical keywords: duplicate maximums ([10, 10, 8] -> 8 vs 10 clarification), all identical ([7, 7, 7] -> None/ValueError), all negative numbers (why initializing to 0 fails!), empty/1-element list, float(''nan'').", "Explains clarifying whether ''second highest'' means second highest *distinct* value (`[10, 10, 8] -> 8`) or second in sorted order (`10`), returning `None` or raising `ValueError` if `second == float(''-inf'')` (e.g., `[]`, `[5]`, or `[7, 7, 7]`), and never initializing `first = 0` (which fails on all-negative lists like `[-10, -5]`)."]}], "critical_failures": ["Initializes `first = 0, second = 0`, which returns `0` (wrong!) when all numbers in the input list are negative (e.g., `[-10, -20, -5]`).", "Uses `nums.sort(); return nums[-2]`, which mutates the caller''s list in-place, runs in $O(N \\\\log N)$, crashes with `IndexError` on `<2` elements, and returns `10` on `[10, 10, 8]` without handling duplicate maximums."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you design the print_all_tasks function to correctly display nested subtasks with proper indentation?', '{"key_points": [{"id": "KP1", "description": "Implement Pre-Order Depth-First Search (DFS) tracking tree `depth` (`level`) to print `indent * depth + task.name` before recursing on `task.subtasks`.", "required": true, "acceptable_evidence": ["Technical keywords: Pre-order Depth-First Search (DFS), depth/level parameter (default 0), ''  '' * depth indentation, base case (empty subtasks), O(V) time and O(H) space.", "Explains that displaying a parent task immediately followed by its nested children requires a **Pre-Order DFS** traversal: `def print_all_tasks(tasks, depth: int = 0, indent: str = ''  '')`: for each `task` in `tasks`, print `f''{indent * depth}{task.title}''` and recursively call `print_all_tasks(task.subtasks, depth + 1, indent)` in $O(N)$ time and $O(H)$ stack space (where $H$ is maximum nesting height)."]}, {"id": "KP2", "description": "Detect and guard against circular task dependencies (`visited: set[str]` of task IDs) and deep nesting (`RecursionError` mitigated via an explicit LIFO stack).", "required": true, "acceptable_evidence": ["Technical keywords: cycle detection (visited/active_path set of task_ids), RecursionError (>1000 depth), explicit iterative LIFO stack [(task, depth)] reversing children.", "Explains tracking `visited` task IDs so a corrupted cycle (`Task A -> Task B -> Task A`) raises an error or prints `[Cycle Detected]` instead of crashing with `RecursionError`, and shows how an explicit iterative stack `stack = [(t, 0) for t in reversed(tasks)]` avoids Python''s 1,000-frame recursion limit."]}, {"id": "KP3", "description": "Separate string formatting/generation (yielding lines via a generator) from `print()` side effects for easy unit testing.", "required": false, "acceptable_evidence": ["Technical keywords: generator yield lines vs direct stdout print(), capsys pytest fixture, None/empty list handling.", "Explains yielding formatted lines (or accepting a stream) so unit tests can assert exact multi-line string output cleanly."]}], "critical_failures": ["Uses Breadth-First Search (BFS queue), which prints all depth-0 tasks first and all depth-1 subtasks grouped together at the bottom detached from their parent tasks!", "Forgets to increment `depth + 1` in the recursive call or fails to handle empty/leaf `subtasks` (`None` vs `[]`)."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you prepare and deliver a structured demo session, including introduction, conceptual presentation, and code walkthrough?', '{"key_points": [{"id": "KP1", "description": "Open with a crisp Executive Context & Problem Statement (the business bottleneck, target SLA/KPIs, and what changed).", "required": true, "acceptable_evidence": ["Technical keywords: problem statement, business/engineering KPI baseline vs target, audience calibration (stakeholders vs engineers).", "Explains starting with a 60–90 second framing: what user/system problem existed, the quantitative success criteria (e.g., <100ms fraud scoring or >0.90 RAG faithfulness), and the end-user value delivered."]}, {"id": "KP2", "description": "Present a 1-Slide Conceptual Architecture & Data Flow Diagram before showing live system execution.", "required": true, "acceptable_evidence": ["Technical keywords: architecture data-flow diagram, ingestion -> retrieval/inference -> observability mental model, live Golden-Path + Edge-Case demo.", "Explains anchoring the audience''s mental model with a clear end-to-end architecture diagram first, then demonstrating the live working application on a realistic happy-path scenario and a failure/guardrail/edge-case scenario (backed by pre-seeded environment data and a recorded fallback)."]}, {"id": "KP3", "description": "Conduct a trace-driven Code Walkthrough following a single request through the core interfaces, critical logic, and automated tests.", "required": true, "acceptable_evidence": ["Technical keywords: request-lifecycle code walkthrough (API entrypoint -> core domain/model -> tests), avoiding line-by-line boilerplate scrolling, Q&A buffer.", "Explains structuring the code walkthrough by tracing one end-to-end request (API router $\\\\rightarrow$ Pydantic contract $\\\\rightarrow$ core retrieval/agent/ML logic $\\\\rightarrow$ `pytest`/DeepEval evaluation), highlighting key design trade-offs rather than scrolling randomly through boilerplate files."]}], "critical_failures": ["Jumps immediately into scrolling through thousands of lines of raw source code without explaining the problem statement or high-level system architecture first.", "Runs an unverified live demo with broken credentials or empty databases without pre-testing the environment."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you remove duplicate records from a Spark DataFrame, and what functions would you use?', '{"key_points": [{"id": "KP1", "description": "Distinguish full-row deduplication (`df.distinct()` / `df.dropDuplicates()`) from business-key subset deduplication (`df.dropDuplicates([''transaction_id''])`).", "required": true, "acceptable_evidence": ["Technical keywords: df.distinct(), df.dropDuplicates(subset=[...]), df.drop_duplicates(), wide shuffle transformation.", "Explains that `df.distinct()` (or `df.dropDuplicates()` with no arguments) removes rows that are 100% identical across all columns, whereas `df.dropDuplicates([''user_id'', ''event_id''])` deduplicates based on specific primary/business key columns."]}, {"id": "KP2", "description": "Use `Window.partitionBy(...).orderBy(F.col(''updated_at'').desc())` + `F.row_number() == 1` when deterministic latest-record retention is required.", "required": true, "acceptable_evidence": ["Technical keywords: non-deterministic arbitrary row retention in dropDuplicates, pyspark.sql.window.Window, partitionBy, orderBy(col(''timestamp'').desc()), F.row_number() == 1.", "Explains a critical production pitfall: `df.dropDuplicates([''id''])` keeps an *arbitrary* row across distributed partitions when timestamps differ; to deterministically keep the most recent update (e.g., Silver layer CDC deduplication), use `w = Window.partitionBy(''id'').orderBy(F.col(''updated_at'').desc())` and filter `df.withColumn(''rn'', F.row_number().over(w)).filter(F.col(''rn'') == 1).drop(''rn'')`."]}, {"id": "KP3", "description": "Manage shuffle performance, Delta Lake `MERGE INTO` upserts, and Structured Streaming `withWatermark` state bounds.", "required": false, "acceptable_evidence": ["Technical keywords: ShuffleExchange partitioning, Delta Lake MERGE INTO, Structured Streaming withWatermark + dropDuplicates (preventing unbounded RocksDB state OOM).", "Explains using `MERGE INTO` when upserting into existing Silver Delta tables and always pairing `dropDuplicates` with `.withWatermark(''event_time'', ''24 hours'')` in Spark Structured Streaming so state store memory stays bounded."]}], "critical_failures": ["Uses `df.dropDuplicates([''user_id''])` after `.orderBy(''timestamp'')` assuming `dropDuplicates` preserves sort order across distributed Spark partitions without a `Window` + `row_number()` function.", "Calls `.toPandas().drop_duplicates()` on a multi-gigabyte Spark DataFrame, crashing the Spark driver node with an Out-Of-Memory error."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you stop the conditional nodes from entering an infinite loop?', '{"key_points": [{"id": "KP1", "description": "Maintain explicit per-loop iteration/retry counters (`retry_count`, `reflection_steps`) inside the typed Graph State and check them first in the conditional router function.", "required": true, "acceptable_evidence": ["Technical keywords: TypedDict / Pydantic GraphState, retry_count / iteration_count, max_retries (e.g., <= 3), deterministic conditional edge guard.", "Explains tracking an explicit integer counter (e.g., `state[''sql_retry_count'']` or `state[''rewrite_attempts'']`) incremented by the loop node, and coding the conditional edge function (`should_continue(state)`) to check `if state[''retry_count''] >= MAX_RETRIES: return ''fallback_or_end''` BEFORE evaluating any LLM/quality condition."]}, {"id": "KP2", "description": "Enforce a hard global runtime ceiling using LangGraph''s `recursion_limit` (catching `GraphRecursionError`) and execution wall-clock/token budgets.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph config={''recursion_limit'': 15}, GraphRecursionError catch, asyncio.timeout wall-clock cap, max_token_budget.", "Explains setting a hard graph-level safety net (`config={''recursion_limit'': 15}`) and wrapping invocation in `asyncio.timeout()` so even if two cycles interact unexpectedly, `GraphRecursionError` is caught cleanly and routed to a graceful fallback/HITL response."]}, {"id": "KP3", "description": "Detect semantic oscillation / duplicate tool calls by hashing `(tool_name, canonical_args)` or query rewrites in state.", "required": true, "acceptable_evidence": ["Technical keywords: semantic cycle detection, tool-call signature hash (seen_tool_calls set), state progress invariant, error feedback injection.", "Explains recording hashes of previous tool calls or rewritten queries in `state[''seen_actions'']`; if the agent proposes the exact same failing tool call or query twice in a row, the router immediately breaks the loop instead of burning all remaining retries on identical inputs."]}], "critical_failures": ["Relies solely on an LLM prompt decision (''Return STOP when you think you have tried enough times'') in a conditional edge without a deterministic integer counter or `recursion_limit`.", "Lets `GraphRecursionError` crash the API with an unhandled HTTP 500 instead of returning a graceful partial/fallback answer or escalating to HITL."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'I have five numbers in an array and I want to find one number. What is your approach or right algorithm to find the number in the array?', '{"key_points": [{"id": "KP1", "description": "Select a direct Linear Scan (`target in arr` or `enumerate(arr)`) for a tiny 5-element unsorted array due to CPU cache locality and zero preprocessing overhead.", "required": true, "acceptable_evidence": ["Technical keywords: linear search O(N), target in arr, next((i for i, x in enumerate(arr) if x == target), -1), CPU L1 cache line, zero allocation overhead.", "Explains that for $N = 5$ elements, a simple linear scan (`target in arr` for boolean existence or `arr.index(target)` / `enumerate` for index) checks at most 5 contiguous memory slots in a single CPU cache line—making it faster in wall-clock nanoseconds than building a hash set or sorting."]}, {"id": "KP2", "description": "Contrast how the optimal algorithm shifts if constraints change: Sorted Array (`Binary Search` / `bisect_left` in $O(\\\\log N)$) vs Millions of Repeated Queries (`set`/`dict` in $O(1)$).", "required": true, "acceptable_evidence": ["Technical keywords: Binary Search (bisect.bisect_left) O(log N) Time / O(1) Space on sorted array, Hash Set (set/dict) O(1) lookup / O(N) preprocessing for Q >> 1 queries.", "Explains the engineering decision matrix as scale $N$ and query count $Q$ grow: (1) Unsorted, single query $\\\\rightarrow$ Linear Search $O(N)$; (2) Already sorted, large $N$ $\\\\rightarrow$ Binary Search (`bisect_left`) in $O(\\\\log N)$ time and $O(1)$ space; (3) Many repeated lookups ($Q \\\\gg N$) $\\\\rightarrow$ pay $O(N)$ once to build a `set` or `dict` (val $\\\\rightarrow$ index) for $O(1)$ amortized queries."]}, {"id": "KP3", "description": "Clarify return contract (boolean vs index of first/all occurrences, `-1` vs `ValueError` when absent, and float `math.isclose` handling).", "required": false, "acceptable_evidence": ["Technical keywords: return contract (bool vs index), duplicate target occurrences, target not found (-1 vs ValueError), float equality.", "Explains confirming whether the caller wants a boolean (`target in arr`), the first matching index, or all matching indices when duplicates exist."]}, {"id": "KP4", "description": "Execute safe database schema migrations using the expand-and-contract pattern ahead of application traffic cutover.", "required": true, "acceptable_evidence": ["Technical keywords: expand-and-contract migration, backward-compatible additive DDL, dual-write / backfill verification.", "Explains separating additive schema changes from destructive column drops so both Blue (v1) and Green (v2) application versions can run concurrently against the database during canary rollout."]}, {"id": "KP5", "description": "Enforce PodDisruptionBudgets (PDB), topology spread constraints, and graceful `SIGTERM` connection draining during EKS rollouts.", "required": false, "acceptable_evidence": ["Technical keywords: `PodDisruptionBudget`, `preStop` lifecycle hook, `terminationGracePeriodSeconds`, in-flight request draining.", "Explains configuring a `preStop` sleep hook and `terminationGracePeriodSeconds` so ALB deregisters terminating pods before Uvicorn closes active streaming connections."]}, {"id": "KP6", "description": "Automate canary metric analysis (Argo Rollouts AnalysisRun) to trigger instant rollback on 5xx or p95 latency regression.", "required": false, "acceptable_evidence": ["Technical keywords: Argo Rollouts `AnalysisTemplate`, Prometheus query gate (`http_requests_5xx_rate`, `p95_latency`), automated abort & rollback.", "Explains querying Prometheus metrics automatically at each canary weight step (10% -> 25% -> 50% -> 100%) and aborting immediately if SLO thresholds breach."]}], "critical_failures": ["Sorts the array first in $O(N \\\\log N)$ just to run a single binary search (which is slower than a single $O(N)$ linear scan!).", "Runs Binary Search on an unsorted array without verifying that the array is sorted."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What additional checks would you perform if a model continues to underperform despite initial debugging?', '{"key_points": [{"id": "KP1", "description": "Audit Data & Label Integrity (manual inspection of top high-confidence errors, label noise/mislabeling, broken point-in-time joins, and train-validation distribution shift).", "required": true, "acceptable_evidence": ["Technical keywords: manual error inspection (top 50 highest-loss examples), label noise / Cleanlab, broken join NULL inflation, temporal/regime shift between train and val.", "Explains inspecting the 50 highest-loss validation errors by hand: often persistent underperformance is caused by noisy/corrupted ground-truth labels, silent upstream join failures filling key features with `NULL`/`0`, or a temporal regime shift between the training window and validation split."]}, {"id": "KP2", "description": "Run the Single-Batch Overfit Sanity Check and diagnose Underfitting (Bias) vs Overfitting (Variance) learning curves.", "required": true, "acceptable_evidence": ["Technical keywords: single-batch overfit test (memorizing 32-100 samples to ~0 loss), bias vs variance learning curves, gradient norm inspection, learning rate schedule.", "Explains running the canonical litmus test: training the model on a tiny slice of 32–100 examples with regularization disabled to verify it can drive training loss to near zero (if it cannot, there is still a silent bug in loss computation, label alignment, frozen layers, or learning rate)."]}, {"id": "KP3", "description": "Perform Stratified Slice & Error Cohort Analysis (`SHAP` attributions, performance across segments, cold-start vs warm cohorts).", "required": true, "acceptable_evidence": ["Technical keywords: stratified slice analysis, SHAP feature importance on failure cohorts, Simpson''s paradox, missing domain interaction features.", "Explains breaking validation metrics down by subgroup slices (e.g., new vs returning users, transaction size buckets, document formats) and computing SHAP attributions to discover which missing domain signals or feature interactions are limiting predictive power."]}, {"id": "KP4", "description": "Verify Objective-Metric Alignment, Probability Calibration, and Decision Thresholding against a simple Baseline Heuristic.", "required": true, "acceptable_evidence": ["Technical keywords: loss-to-evaluation metric mismatch (Cross-Entropy/Focal Loss vs PR-AUC/F-beta), probability calibration (Brier/reliability curve), threshold tuning, simple logistic/GBDT baseline.", "Explains checking whether the training loss aligns with the business evaluation metric (e.g., using default `0.5` threshold on a 0.5% imbalanced fraud dataset yields terrible F1/Recall even when `PR-AUC` is strong, requiring probability calibration and threshold optimization)."]}], "critical_failures": ["Continues blindly running larger hyperparameter grid searches or stacking deeper neural layers without manually inspecting the data labels and worst prediction errors.", "Tunes hyperparameters repeatedly against the final held-out test set to force the score up."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What are Python decorators, and why would you use them instead of alternative design patterns?', '{"key_points": [{"id": "KP1", "description": "Explain Python Decorators as higher-order closures (`fn = decorator(fn)`) using `*args, **kwargs` and `@functools.wraps`.", "required": true, "acceptable_evidence": ["Technical keywords: first-class functions, lexical closure, @decorator syntax, *args / **kwargs forwarding, @functools.wraps(fn), parameterized 3-level decorator factory.", "Explains that because functions are first-class objects in Python, `@my_decorator` wraps a target function in a closure to run pre/post logic while preserving the original function''s `__name__`, `__doc__`, and `__annotations__` via `@functools.wraps`."]}, {"id": "KP2", "description": "Contrast Python Decorators against Subclass Inheritance and Classical OOP Wrapper/Proxy Classes (eliminating class explosion and keeping cross-cutting concerns declarative).", "required": true, "acceptable_evidence": ["Technical keywords: cross-cutting concerns (Aspect-Oriented), avoiding subclass explosion (RetryingLoggedAuthenticatedService), DRY principle, Single Responsibility Principle.", "Explains why decorators are preferred over inheritance or Gang-of-Four Wrapper classes in Python: stacking `@require_auth`, `@retry(stop=3)`, and `@trace_span` composes independent orthogonal behaviors declaratively in 3 lines without creating a combinatorial explosion of subclasses (`AuthenticatedRetryingTracedService`) or polluting core business logic."]}, {"id": "KP3", "description": "Identify when alternative patterns (Context Managers `with` for block-scoped resources or FastAPI `Depends` / Middleware for request-scoped DI) are preferable.", "required": false, "acceptable_evidence": ["Technical keywords: Context Manager (with statement) for sub-function block scope, FastAPI Depends() for dependency injection, inspect.iscoroutinefunction for async/sync support.", "Explains that decorators apply to an entire function call, whereas `with` context managers are better when resource acquisition/release spans only a few lines inside a function."]}], "critical_failures": ["Omits `@functools.wraps(func)`, breaking FastAPI/Pydantic signature inspection, docstrings, and `pytest` introspection.", "Writes a synchronous wrapper for an `async def` coroutine function without awaiting it, returning an unawaited coroutine object instead of executing the post-hook."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What are your strengths in Python development, and how would you rate your proficiency with real-world examples?', '{"key_points": [{"id": "KP1", "description": "State a calibrated proficiency rating (e.g., 8.5–9/10 in production backend/data/AI Python) backed by concrete Python internals mastery.", "required": true, "acceptable_evidence": ["Technical keywords: calibrated self-assessment (8-9/10), CPython memory model & GIL, generators/iterators, decorators, context managers, typing.Protocol, Pydantic v2.", "Explains a confident, realistic rating (acknowledging continuous evolution in CPython internals like 3.12/3.13 free-threading/JIT) grounded in deep command of Python''s data model, typing, memory efficiency, and concurrency."]}, {"id": "KP2", "description": "Provide real-world examples across High-Concurrency Async Microservices (`FastAPI` + `asyncio`) and Distributed Data/ML Pipelines (`PySpark`, `Pandas`, `PyTorch`).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI async/SSE streaming, LangGraph/RAG orchestration, PySpark/Polars vectorization, PyTorch/scikit-learn/MLflow packaging.", "Connects Python strengths to concrete shipped systems: building non-blocking `FastAPI` + `asyncio` RAG/agent microservices streaming SSE tokens, refactoring memory-heavy Pandas/notebook code into lazy generator pipelines and vectorized PySpark/Delta transformations, and packaging MLflow models."]}, {"id": "KP3", "description": "Highlight production engineering discipline (`pytest` architecture, `mypy --strict`, `ruff`, profiling `cProfile`/`tracemalloc`, and packaging).", "required": true, "acceptable_evidence": ["Technical keywords: pytest fixtures & parametrization, mypy --strict, ruff, cProfile / tracemalloc / py-spy profiling, pyproject.toml / uv / Docker.", "Emphasizes writing maintainable, strongly-typed, tested Python packages rather than throwaway scripts."]}], "critical_failures": ["Claims ''10 out of 10, I know everything in Python'' but cannot explain the GIL, generators, `asyncio`, or `Pydantic`.", "Gives a numeric rating with zero concrete production examples."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'What challenges have you faced in code merging and version control, and how do you resolve conflicts effectively?', '{"key_points": [{"id": "KP1", "description": "Identify common real-world version control challenges: long-lived diverging feature branches, Semantic Merge Conflicts, lockfile/migration collisions, and JSON Jupyter Notebook (`ipynb`) diffs.", "required": true, "acceptable_evidence": ["Technical keywords: semantic merge conflict (clean text merge that breaks logic/signatures), lockfile conflicts (poetry.lock/uv.lock), Flyway/Alembic DB migration numbering collisions, .ipynb JSON cell conflicts.", "Explains both textual conflicts and **Semantic Conflicts** (where Branch A renames a parameter or changes a Pydantic schema and Branch B adds a new caller in a different file—Git merges cleanly without conflict markers, but runtime breaks), plus `.ipynb` base64 output bloat and DB migration version collisions."]}, {"id": "KP2", "description": "Resolve conflicts systematically using 3-Way Merge inspection (`HEAD` vs `BASE` common ancestor vs `INCOMING`), `git rebase` onto `main`, and regenerating lockfiles.", "required": true, "acceptable_evidence": ["Technical keywords: 3-way merge (diff3 conflictStyle: ours, base, theirs), git fetch + git rebase origin/main, lockfile regeneration (uv lock / poetry lock), git rerere.", "Explains enabling `merge.conflictStyle = zdiff3` to inspect the common ancestor (`BASE`) alongside `ours` and `theirs`, pairing with the other author when business logic overlaps, regenerating lockfiles (`poetry lock` / `uv lock`) rather than hand-editing lockfile hashes, and running the full `pytest` + `mypy` suite before completing the rebase/merge."]}, {"id": "KP3", "description": "Prevent conflicts proactively via Trunk-Based Development (short-lived small PRs), Feature Flags, modular file boundaries, and `nbstripout`/`Jupytext`.", "required": true, "acceptable_evidence": ["Technical keywords: Trunk-Based Development (<1-2 day branches), feature flags, nbstripout pre-commit hook, modular package boundaries.", "Explains preventing massive merge conflicts by merging small incremental PRs (<300 LOC) daily behind feature flags and stripping notebook outputs via `nbstripout`."]}], "critical_failures": ["Blindly accepts `--ours` or `--theirs` (or runs `git push --force` to `main`), silently overwriting a teammate''s production changes.", "Resolves conflict markers in a text editor and merges immediately without running unit tests and type checkers to catch semantic conflicts."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What has been your experience using tools like Cursor or similar AI-assisted coding tools, and how do you balance their use with implementing core logic yourself?', '{"key_points": [{"id": "KP1", "description": "Establish a clear Division of Labor: Engineer owns Architecture, Data/State Contracts, and Core Algorithmic/Security Invariants; AI accelerates Boilerplate, Tests, and Refactoring.", "required": true, "acceptable_evidence": ["Technical keywords: human architectural ownership, core domain invariants, AI delegation for boilerplate (DTOs, CRUD, test fixtures, migrations, regex/SQL drafts).", "Explains never outsourcing system architecture or critical domain invariants to an LLM: the engineer designs the state machine, Pydantic/database schemas, concurrency boundaries, and ML split logic first, then uses Cursor / Claude Code to fill in repetitive scaffolding, type annotations, and parameterized `pytest` suites."]}, {"id": "KP2", "description": "Constrain AI context with project rules (`.cursorrules` / `CLAUDE.md`), explicit `@file`/`@docs` grounding, and small incremental diffs.", "required": true, "acceptable_evidence": ["Technical keywords: .cursorrules / CLAUDE.md, explicit @file and @docs context pinning, atomic step-by-step diffs, avoiding unconstrained multi-file generation.", "Explains configuring repository rules (enforcing Python 3.11+, Pydantic v2, `ruff`/`mypy`, no bare `except`, async safety) and scoping AI edits to one small, verifiable function or module at a time rather than big-bang multi-file prompts."]}, {"id": "KP3", "description": "Maintain sharp first-principles coding skills and enforce strict verification gates (`pytest`, `mypy`, debugger dry-runs, and line-by-line review).", "required": true, "acceptable_evidence": ["Technical keywords: zero ''vibe-coding'' in production, line-by-line diff review, pytest + mypy --strict verification, manual implementation of hot paths.", "Explains that you must be able to write and debug every line without AI when needed—reviewing every generated diff with the same rigor as a junior engineer''s PR and writing performance-critical or security-critical algorithms directly."]}], "critical_failures": ["Describes ''vibe coding''—prompting Cursor to build entire features and committing the result without understanding how the code works under the hood.", "Cannot explain how to debug or implement core algorithms when AI tools are unavailable."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'EASY', 'SPECIFIC', 60, 'What is the Global Interpreter Lock (GIL) in Python, and how does it impact concurrency?', '{"key_points": [{"id": "KP1", "description": "Define the CPython GIL as an interpreter-level mutex that permits only one OS thread per process to execute Python bytecode at a time (protecting CPython''s non-thread-safe `ob_refcnt` reference counting).", "required": true, "acceptable_evidence": ["Technical keywords: CPython Global Interpreter Lock (GIL), mutex on Python bytecode execution, PyObject ob_refcnt reference counting, sys.getswitchinterval() (5ms).", "Explains that the GIL exists in standard CPython so every `PyObject` reference count increment/decrement (`Py_INCREF`/`Py_DECREF`) and internal C allocator state does not require fine-grained locks on every object."]}, {"id": "KP2", "description": "Contrast the GIL''s impact on CPU-Bound workloads (no multi-core speedup with `threading`) vs I/O-Bound workloads (GIL is released during network/disk syscalls).", "required": true, "acceptable_evidence": ["Technical keywords: CPU-bound thread serialization & context-switch overhead vs I/O-bound GIL release (socket read/write, disk I/O, sleep).", "Explains that for pure-Python CPU-bound loops, multiple threads cannot run in parallel across CPU cores (and may even run slower due to lock contention), whereas for I/O-bound tasks (HTTP calls, DB queries), CPython releases the GIL while waiting on OS sockets—making `threading` or `asyncio` highly effective."]}, {"id": "KP3", "description": "Explain how to achieve true multi-core CPU parallelism in Python (`multiprocessing` / `ProcessPoolExecutor`, C/Rust/CUDA extensions like `NumPy`/`PyTorch`/`Polars` that release the GIL, and PEP 703 Python 3.13+ `python3.13t`).", "required": true, "acceptable_evidence": ["Technical keywords: concurrent.futures.ProcessPoolExecutor / multiprocessing, Py_BEGIN_ALLOW_THREADS in NumPy/PyTorch/Polars/scikit-learn, PEP 703 free-threaded Python (3.13+).", "Explains bypassing the GIL via `ProcessPoolExecutor` (separate OS processes with independent GILs) or vectorized C/Rust/CUDA libraries (`NumPy`, `PyTorch`, `Polars`, `faiss`) which release the GIL (`Py_BEGIN_ALLOW_THREADS`) during heavy native compute."]}, {"id": "KP4", "description": "Use coverage-guided property-based testing (`Hypothesis`) and mutation testing to uncover edge-case input failures.", "required": false, "acceptable_evidence": ["Technical keywords: `Hypothesis` (`@given`, strategies), property-based fuzzing, boundary condition discovery.", "Explains generating randomized malformed Unicode, extreme numeric bounds, and nested JSON structures via `Hypothesis` to verify invariants automatically."]}, {"id": "KP5", "description": "Enforce deterministic CI test execution via pytest fixtures, database transaction rollbacks, and VCR/respx HTTP mocking.", "required": false, "acceptable_evidence": ["Technical keywords: `pytest` fixtures (`conftest.py`), `respx` / `pytest-recording` HTTP cassettes, isolated test DB rollback, coverage gate (`--cov-fail-under`).", "Explains mocking external LLM/network calls deterministically in unit tests while running contract tests against containerized local dependencies (`Testcontainers`)."]}], "critical_failures": ["Claims Python `threading` cannot handle concurrent network/HTTP requests because of the GIL.", "Claims the GIL makes user Python code automatically free of race conditions without `threading.Lock`."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'EASY', 'SPECIFIC', 60, 'What is your experience with Python-based AI development, including libraries and frameworks used for building production systems?', '{"key_points": [{"id": "KP1", "description": "Identify the Data Processing & Classical ML/Deep Learning stack (`PySpark`/`Delta`, `Pandas`/`Polars`, `NumPy`, `scikit-learn`, `XGBoost`/`LightGBM`, `PyTorch`, `Hugging Face transformers`/`peft`).", "required": true, "acceptable_evidence": ["Technical keywords: PySpark, Pandas/Polars, NumPy, scikit-learn, XGBoost/LightGBM, PyTorch, Hugging Face transformers, PEFT (LoRA/QLoRA), sentence-transformers.", "Explains using `PySpark` and `Pandas`/`Polars` for Medallion feature engineering, `scikit-learn` and `XGBoost`/`LightGBM` for tabular classification/ranking, and `PyTorch` + Hugging Face `transformers`/`peft`/`sentence-transformers` for embeddings, rerankers, and LoRA fine-tuning."]}, {"id": "KP2", "description": "Identify the Generative AI, RAG & Agentic Orchestration stack (`LangGraph`, `LangChain`/`LlamaIndex`, `pymilvus`/`faiss`/`pgvector`, `Pydantic`/`Instructor`).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, LangChain, LlamaIndex, pymilvus / chromadb / pgvector / faiss, rank-bm25, Pydantic v2 / Instructor, MCP SDK.", "Explains building stateful multi-agent workflows with `LangGraph`, hybrid retrieval over `Milvus`/`pgvector`/`FAISS` + `BM25`, and enforcing structured LLM outputs via `Pydantic`."]}, {"id": "KP3", "description": "Identify the Production Serving, Evaluation & MLOps stack (`FastAPI`/`Uvicorn`, `vLLM`, `MLflow`, `DVC`, `DeepEval`, `pytest`, `Prometheus`/`OpenTelemetry`).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, Uvicorn, vLLM, MLflow, DVC, DeepEval / RAGAS, pytest, OpenTelemetry / Langfuse / Prometheus.", "Explains exposing low-latency async endpoints with `FastAPI` + `Uvicorn` (and `vLLM` for LLM serving), governing artifacts with `MLflow` and `DVC`, gating CI/CD with `pytest` + `DeepEval`, and instrumenting telemetry with `Prometheus`/`OpenTelemetry`."]}], "critical_failures": ["Lists only toy notebook libraries (`matplotlib`, `seaborn`) without naming production serving (`FastAPI`), evaluation (`DeepEval`/`pytest`), or MLOps (`MLflow`/`DVC`) libraries.", "Cannot explain the distinct role of each library family in an end-to-end production pipeline."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'What steps are involved in integrating GraphQL with a React application using tools like Apollo Client and Apollo Server?', '{"key_points": [{"id": "KP1", "description": "Define the Strongly-Typed GraphQL Schema (`typeDefs`: `Query`, `Mutation`, `Subscription`, `Input` types) and Resolver functions on the Server.", "required": true, "acceptable_evidence": ["Technical keywords: GraphQL SDL (Schema Definition Language), Query, Mutation, Subscription, resolvers (parent, args, context, info), Apollo Server / Strawberry GraphQL (FastAPI).", "Explains defining the GraphQL schema contract (`typeDefs`) and implementing resolver functions that receive authenticated user/DB context (`contextValue`), using **DataLoader** batching to prevent the GraphQL $N+1$ nested resolver query problem."]}, {"id": "KP2", "description": "Configure `ApolloClient` (`HttpLink`, `AuthLink` JWT header injection, `ErrorLink`, and `InMemoryCache` with `typePolicies`) and wrap the React tree in `<ApolloProvider>`.", "required": true, "acceptable_evidence": ["Technical keywords: ApolloClient, ApolloProvider, InMemoryCache (normalized __typename:id cache), createHttpLink, setContext (Bearer JWT), onError link.", "Explains initializing `ApolloClient` with a chained link pipeline (`errorLink` $\\\\rightarrow$ `authLink` attaching Bearer JWTs $\\\\rightarrow$ `httpLink`/`GraphQLWsLink`) and `InMemoryCache` (which normalizes entities by `__typename:id` for automatic cross-component UI consistency)."]}, {"id": "KP3", "description": "Execute typed operations in React components using `useQuery`, `useLazyQuery`, `useMutation` (with optimistic updates / cache eviction), and `graphql-codegen`.", "required": true, "acceptable_evidence": ["Technical keywords: useQuery ({ data, loading, error }), useMutation, optimisticResponse, cache.modify / refetchQueries, GraphQL Code Generator (TypeScript hooks).", "Explains running `graphql-codegen` against the server schema to generate strongly-typed TypeScript hooks (`useGetCandidateQuery`), handling `loading`/`error` states declaratively, and updating `InMemoryCache` after `useMutation`."]}, {"id": "KP4", "description": "Secure production GraphQL endpoints against deeply nested query DoS (`query depth limiting`, complexity cost limits, and disabling introspection in prod).", "required": false, "acceptable_evidence": ["Technical keywords: query depth limiting (graphql-depth-limit), query complexity cost cap, persisted queries, field-level RBAC.", "Explains enforcing max query depth and complexity limits on Apollo Server so malicious cyclic queries (`user { friends { friends { ... } } }`) cannot DoS the database."]}], "critical_failures": ["Implements nested GraphQL field resolvers that fire a separate SQL query per row without `DataLoader` batching (causing severe $N+1$ database bottlenecks).", "Fetches `*` (every field on a massive GraphQL type) in every React component, defeating GraphQL''s over-fetching prevention."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'BROAD', 150, 'When do memory leaks occur in Python, and how do you identify and debug them in practice?', '{"key_points": [{"id": "KP1", "description": "Identify primary causes of Python memory leaks despite Garbage Collection (Unbounded Global Dicts/`@lru_cache(maxsize=None)`, Lingering Closures/Callbacks, and PyTorch/NumPy Tensor Graph Retention).", "required": true, "acceptable_evidence": ["Technical keywords: unbounded module-level list/dict cache, @functools.lru_cache(maxsize=None) / @cache on instance methods (holding self), unclosed file/DB connections, PyTorch autograd graph retention (missing .detach()).", "Explains that most Python ''memory leaks'' are **logical object retention** where live references prevent `ob_refcnt` from reaching zero: e.g., appending request logs/metrics to a global list, using `@lru_cache(maxsize=None)` on dynamic user inputs or instance methods (which pins `self` forever), or storing a PyTorch tensor with `requires_grad=True` without `.detach().item()`."]}, {"id": "KP2", "description": "Identify Cyclic Reference & C-Extension / Allocator fragmentation issues (`gc` generational collector, `__del__` finalizer cycles, and `pymalloc`/glibc arena retention).", "required": true, "acceptable_evidence": ["Technical keywords: reference cycles (A <-> B), gc module (Gen 0/1/2), C-extension malloc leaks, glibc MALLOC_TRIM / jemalloc arena fragmentation.", "Explains how CPython combines immediate reference counting with a cyclic generational garbage collector (`gc`), noting that C extensions failing to `Py_DECREF` or heavily fragmented `DataFrame` allocations in `glibc` can cause container RSS memory (`OOMKilled`) to climb monotonically."]}, {"id": "KP3", "description": "Diagnose and pinpoint leaking lines in practice using `tracemalloc` snapshot diffs, `objgraph`, and `memray` / `py-spy`.", "required": true, "acceptable_evidence": ["Technical keywords: tracemalloc.start(), snapshot2.compare_to(snapshot1, ''lineno''), objgraph.show_most_common_types() / show_backrefs(), Bloomberg memray, gc.get_objects().", "Explains taking two `tracemalloc.take_snapshot()` captures across 1,000 requests and calling `snap2.compare_to(snap1, ''lineno'')` to print the exact Python file and line number whose memory allocation grew monotonically, then using `objgraph.show_backrefs()` to visualize the reference chain keeping those objects alive."]}, {"id": "KP4", "description": "Remediate leaks using bounded TTL/LRU caches (`cachetools.TTLCache`), `weakref`, context managers (`with`), and worker recycling (`--max-requests`).", "required": true, "acceptable_evidence": ["Technical keywords: cachetools.TTLCache / bounded lru_cache(maxsize=1024), weakref.WeakValueDictionary, context managers, Gunicorn/Uvicorn --limit-max-requests + jitter.", "Explains fixing the root reference retention with bounded `TTLCache`s or `weakref`, and configuring Uvicorn/Gunicorn `--limit-max-requests` with jitter in Kubernetes as a defense-in-depth safeguard."]}], "critical_failures": ["Claims memory leaks are impossible in Python because Python has automatic garbage collection.", "Sprinkles `gc.collect()` after every HTTP request without fixing the unbounded dictionary/list holding live references to the objects."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Which algorithm did you use for keyword search, and why did you choose it?', '{"key_points": [{"id": "KP1", "description": "Select **Okapi BM25** (Best Matching 25) over raw TF-IDF or SQL `LIKE` as the sparse lexical retrieval algorithm.", "required": true, "acceptable_evidence": ["Technical keywords: Okapi BM25, inverted index, term frequency saturation (k1 in [1.2, 2.0]), document length normalization (b = 0.75), Inverse Document Frequency (IDF).", "Explains choosing **Okapi BM25** backed by an inverted index (in Milvus 2.4+ Sparse-BM25, OpenSearch/Elasticsearch, or `rank_bm25`) because unlike raw TF-IDF—where a word repeated 50 times scores 10x higher than 5 times linearly—BM25 applies asymptotic term-frequency saturation ($k_1$) and document-length normalization ($b$) relative to average chunk length ($\\\\text{avgdl}$)."]}, {"id": "KP2", "description": "Explain why BM25 is essential alongside Dense Vector Embeddings (exact match on SKUs, error codes, legal citations, tickers, and rare domain acronyms).", "required": true, "acceptable_evidence": ["Technical keywords: out-of-vocabulary / rare domain identifiers (error codes ERR_5042, policy IDs, part numbers, function names), zero-shot lexical precision, sub-10ms inverted index latency.", "Explains that dense bi-encoder embeddings compress text into smooth semantic vectors and frequently fail on exact alphanumeric tokens (e.g., `Policy-9941B`, `CVE-2024-3094`, function names, or medical/financial codes), where BM25''s high-IDF exact token matching achieves near-100% recall in <10ms."]}, {"id": "KP3", "description": "Explain how BM25 candidates are fused with Dense Vector search via Reciprocal Rank Fusion (`RRF`, $k=60$) and Cross-Encoder Reranking.", "required": true, "acceptable_evidence": ["Technical keywords: Hybrid Search, Reciprocal Rank Fusion (RRF: 1 / (60 + rank)), domain stopword/stemming analyzer tuning, Cross-Encoder reranking.", "Explains combining top-$K$ BM25 hits and top-$K$ dense vector hits via scale-invariant Reciprocal Rank Fusion (`RRF`) before passing the merged pool to a Cross-Encoder reranker."]}], "critical_failures": ["Uses full-table SQL `WHERE text LIKE ''%query%''` scans for keyword search in a large RAG corpus instead of an inverted index with BM25.", "Cannot explain how BM25 improves upon naive TF-IDF (term-frequency saturation $k_1$ and length normalization $b$)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you implemented the build_manifest function for a quad tree using recursion and a depth-first approach?', '{"key_points": [{"id": "KP1", "description": "Define the QuadTree node structure and spatial quadrant partitioning (NW, NE, SW, SE).", "required": true, "acceptable_evidence": ["Technical keywords: QuadTree node, bounding box (x_min, y_min, x_max, y_max), leaf node vs internal node, 4 children (NW, NE, SW, SE).", "Explains that each internal QuadTree node recursively subdivides a 2D spatial region into four equal quadrants until a leaf capacity threshold or maximum depth is reached.", "Provides a concrete node representation with `bounds`, `is_leaf`, `items/payload`, and `children = [nw, ne, sw, se]`."]}, {"id": "KP2", "description": "Implement recursive depth-first traversal (DFS) in `build_manifest` with clear base cases for leaf and empty nodes.", "required": true, "acceptable_evidence": ["Technical keywords: depth-first search (DFS), pre-order/post-order traversal, base case (`node is None` or `node.is_leaf`), quadrant path addressing.", "Explains that the base case checks if `node is None` (returning empty) or `node.is_leaf` (recording the leaf''s spatial key/quadkey, bounding box, and asset metadata into the manifest).", "Shows recursive descent iterating over `(quad_idx, child)` in `enumerate(node.children)` and passing the updated hierarchical path prefix (e.g., `''0312''`)."]}, {"id": "KP3", "description": "Aggregate child metadata or prune empty quadrants to produce a deterministic manifest structure.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic quadrant ordering, bottom-up aggregation, empty-tile pruning, manifest dictionary/list.", "Explains how visiting quadrants in a fixed canonical order (`NW -> NE -> SW -> SE`) guarantees deterministic manifest hashes and allows skipping empty subtrees.", "Demonstrates aggregating child bounding counts or checksums up to parent manifest entries."]}, {"id": "KP4", "description": "Analyze time and call-stack space complexity and guard against stack overflow on deep spatial trees.", "required": false, "acceptable_evidence": ["Technical keywords: O(N) time complexity, O(D) recursion stack space, max_depth bound, iterative explicit stack fallback.", "Explains that DFS visits every QuadTree node once in $O(N)$ time and consumes $O(D)$ stack frames where $D$ is maximum tree depth.", "Notes enforcing a maximum subdivision depth (e.g., $D \\\\le 20$) or using an explicit stack if tree depth is unbounded."]}], "critical_failures": ["Omits the recursion base case for leaf or `None` nodes, causing infinite recursion or `AttributeError`.", "Traverses quadrants in non-deterministic order or mutates a shared mutable path list across sibling recursive calls without backtracking/copying."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How do you implement logging and tracing in systems like LangFuse, and what is the role of traces in debugging distributed applications?', '{"key_points": [{"id": "KP1", "description": "Explain the hierarchical data model of LLM observability in Langfuse (`Trace` -> `Span` -> `Generation` / `Event`).", "required": true, "acceptable_evidence": ["Technical keywords: Trace, Span, Generation, parent_observation_id, session_id, user_id.", "Explains that a `Trace` represents an end-to-end user request or agent run, `Spans` track intermediate steps (query rewriting, vector search, reranking, tool calls), and `Generations` capture specific LLM calls with model parameters, prompts, completions, and token counts.", "Provides an example trace hierarchy: `Trace(chat_turn) -> Span(hybrid_retrieval) + Generation(claude_3_5_sonnet_synthesis)`."]}, {"id": "KP2", "description": "Instrument code using Langfuse decorators (`@observe()`), callback handlers, or OpenTelemetry context propagation across microservices.", "required": true, "acceptable_evidence": ["Technical keywords: @observe() decorator, CallbackHandler (LangChain/LlamaIndex), OpenTelemetry (OTel) W3C traceparent header, async background flushing.", "Explains how `@observe()` or framework callback handlers automatically capture inputs, outputs, and latencies asynchronously without blocking the request path.", "Explains propagating `trace_id` and `parent_observation_id` across distributed HTTP/gRPC or message-queue boundaries so downstream worker spans attach to the same root trace."]}, {"id": "KP3", "description": "Use distributed traces to localize root causes of latency bottlenecks, retrieval failures, and agent loops.", "required": true, "acceptable_evidence": ["Technical keywords: waterfall timeline, time-to-first-token (TTFT), retrieval vs synthesis fault isolation, tool-call retry inspection.", "Explains inspecting the trace waterfall to distinguish whether a bad response stemmed from poor query rewriting, zero/irrelevant retrieved chunks, prompt truncation, or LLM hallucination.", "Shows how span duration breakdowns pinpoint p95/p99 latency culprits (e.g., a 2.4s cross-encoder reranker stall vs a 400ms vector lookup)."]}, {"id": "KP4", "description": "Track prompt versions, token cost attribution, and attach automated or human evaluation scores (`langfuse.score`) to traces.", "required": true, "acceptable_evidence": ["Technical keywords: prompt version linking, token usage/cost tracking, langfuse.score(), golden dataset curation.", "Explains linking production traces to specific prompt versions in Langfuse Prompt Management to compare quality and cost across releases.", "Demonstrates attaching faithfulness scores or user thumbs-down feedback (`langfuse.score(trace_id, name=''faithfulness'', value=0.4)`) and exporting failing traces into evaluation datasets."]}, {"id": "KP5", "description": "Implement PII redaction and non-blocking batch ingestion before exporting telemetry.", "required": false, "acceptable_evidence": ["Technical keywords: PII masking/scrubbing before export, async queue flushing (`langfuse.flush()`), sampling rate.", "Explains scrubbing sensitive customer PII/secrets from input/output payloads before sending traces to external observability backends."]}, {"id": "KP6", "description": "Correlate frontend RUM/session IDs (`session_id`, `user_id`) with backend Langfuse traces and infrastructure metrics via OpenTelemetry baggage.", "required": false, "acceptable_evidence": ["Technical keywords: `session_id` multi-turn grouping, OpenTelemetry baggage propagation, CloudWatch/Grafana exemplars.", "Explains grouping all conversational turns under a unified Langfuse `session_id` and linking Prometheus latency histograms to specific trace IDs via exemplars."]}], "critical_failures": ["Confuses unstructured stdout text logging (`print`) with structured hierarchical distributed tracing.", "Fails to propagate trace context across service boundaries, resulting in disconnected orphan spans in distributed workflows."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you incorporate feedback loops to evaluate faithfulness, compliance, and overall model quality?', '{"key_points": [{"id": "KP1", "description": "Capture explicit and implicit user feedback signals tied directly to production trace IDs.", "required": true, "acceptable_evidence": ["Technical keywords: explicit feedback (thumbs up/down, reason codes, inline edits), implicit signals (copy/accept rate, re-querying, abandonment), trace_id correlation.", "Explains capturing structured user feedback in the UI and linking it to the exact `trace_id`, retrieved chunk IDs, prompt version, and model response.", "Provides examples such as tracking citation click-throughs and developer diff-acceptance rates in AI assistants."]}, {"id": "KP2", "description": "Evaluate faithfulness (groundedness) via NLI or claim-level LLM-as-a-Judge verification against retrieved context.", "required": true, "acceptable_evidence": ["Technical keywords: faithfulness / groundedness, claim decomposition, entailment verification (RAGAS / TruLens), unsupported claim detection.", "Explains decomposing the generated answer into atomic factual claims and verifying whether each claim is directly entailed by the retrieved source chunks.", "Computes faithfulness as the ratio of supported claims to total claims, flagging responses below threshold (e.g., `< 0.85`)."]}, {"id": "KP3", "description": "Enforce compliance via deterministic rule checks, PII/toxicity classifiers, and policy rubrics.", "required": true, "acceptable_evidence": ["Technical keywords: PII detection (Presidio), regulatory refusal policies, output guardrails, audit logging.", "Explains combining fast deterministic regex/NER checks (blocking SSNs, account numbers, prohibited financial/medical advice) with rubric-based compliance evaluators.", "Ensures non-compliant outputs are intercepted pre-delivery or escalated for compliance review."]}, {"id": "KP4", "description": "Close the loop by routing low-scoring traces to SME curation, golden evaluation sets, and retrieval/prompt iteration.", "required": true, "acceptable_evidence": ["Technical keywords: active learning triage queue, golden dataset expansion, CI/CD regression gate, DPO/few-shot refinement.", "Explains routing traces with negative user feedback or low faithfulness scores to human reviewers, promoting verified corrections into the CI/CD regression test suite or few-shot/fine-tuning datasets."]}], "critical_failures": ["Collects user feedback without linking it to the underlying retrieved context and prompt trace, making root-cause remediation impossible.", "Relies exclusively on uncalibrated LLM self-evaluation without deterministic compliance checks or human calibration."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'How have you implemented concurrency in Python (multithreading, multiprocessing, async I/O), and when do you choose each approach?', '{"key_points": [{"id": "KP1", "description": "Explain the CPython Global Interpreter Lock (GIL) and how it governs CPU-bound vs I/O-bound concurrency.", "required": true, "acceptable_evidence": ["Technical keywords: Global Interpreter Lock (GIL), bytecode execution serialization, I/O syscall GIL release, C/Rust extension GIL release.", "Explains that the CPython GIL prevents multiple OS threads from executing Python bytecode simultaneously in a single process, but is released during blocking I/O operations and in native C/C++/Rust extensions (e.g., NumPy, PyTorch, FAISS)."]}, {"id": "KP2", "description": "Use `asyncio` for high-concurrency network/I/O-bound workloads (LLM API calls, vector DB queries, webhooks).", "required": true, "acceptable_evidence": ["Technical keywords: single-threaded event loop, async/await coroutines, asyncio.gather / TaskGroup, asyncio.Semaphore, httpx/aiohttp.", "Explains that `asyncio` multiplexes thousands of concurrent network requests on a single thread using non-blocking sockets without OS thread context-switching overhead.", "Provides a concrete example using `asyncio.Semaphore(50)` with `asyncio.gather` to fan out concurrent embedding or LLM API calls safely."]}, {"id": "KP3", "description": "Use `multithreading` (`ThreadPoolExecutor`) for blocking/legacy I/O libraries or GIL-releasing native C extensions.", "required": true, "acceptable_evidence": ["Technical keywords: concurrent.futures.ThreadPoolExecutor, synchronous SDKs (boto3, requests), asyncio.to_thread / run_in_executor.", "Explains using `ThreadPoolExecutor` when integrating synchronous I/O libraries that lack native `async` support or offloading blocking calls from an `asyncio` event loop via `asyncio.to_thread()`."]}, {"id": "KP4", "description": "Use `multiprocessing` (`ProcessPoolExecutor`) for CPU-bound Python workloads (document parsing, AST chunking, regex scrubbing).", "required": true, "acceptable_evidence": ["Technical keywords: concurrent.futures.ProcessPoolExecutor, separate OS processes/memory spaces, pickle IPC serialization overhead.", "Explains spawning separate Python processes across CPU cores to bypass the GIL for heavy CPU work like PDF OCR/parsing or large text chunking.", "Notes the trade-off of higher memory footprint and IPC `pickle` serialization overhead for large payloads."]}], "critical_failures": ["Uses Python `threading` to parallelize pure-Python CPU-bound loops expecting multi-core speedup.", "Calls blocking synchronous functions (e.g., `time.sleep` or `requests.get`) directly inside an `async def` coroutine, freezing the entire event loop."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 90, 'How would you debug and handle issues when a verification email is not working or needs to be re-requested?', '{"key_points": [{"id": "KP1", "description": "Trace the end-to-end asynchronous email delivery pipeline from API trigger to SMTP/ESP webhook events.", "required": true, "acceptable_evidence": ["Technical keywords: transactional outbox / message queue (Celery/SQS), Email Service Provider (SendGrid/AWS SES), delivery webhooks (bounce, drop, spam complaint), SPF/DKIM/DMARC.", "Explains checking application logs and queue worker status first, then inspecting ESP webhook events (hard bounce, suppression list, rate limit) and DNS authentication records (`SPF`, `DKIM`, `DMARC`)."]}, {"id": "KP2", "description": "Manage verification token security: cryptographic randomness, hashed storage, TTL expiration, and previous-token invalidation on resend.", "required": true, "acceptable_evidence": ["Technical keywords: CSPRNG token (`secrets.token_urlsafe`), SHA-256 token hash in DB, TTL expiry (e.g., 15-30 min), single-use invalidation.", "Explains generating a new cryptographically secure token on re-request, storing its hash with an expiration timestamp, and immediately invalidating all previously issued unverified tokens for that user."]}, {"id": "KP3", "description": "Protect the resend endpoint with rate limiting, cooldown timers, and anti-enumeration responses.", "required": true, "acceptable_evidence": ["Technical keywords: Redis sliding-window rate limiter, cooldown backoff (e.g., 60s), account enumeration prevention, idempotency.", "Explains enforcing per-user and per-IP rate limits (e.g., max 3 resends per 15 minutes with a 60-second cooldown) and returning a uniform `200 OK` message regardless of whether the email exists or is already verified."]}], "critical_failures": ["Sends the email synchronously inside the HTTP registration transaction without timeout/queueing, or leaves old tokens valid indefinitely when a new token is requested.", "Exposes an unthrottled resend endpoint that allows attackers to spam arbitrary email addresses or enumerate registered users."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a Python program to read book records from a text file URL and compute the total number of books and total pages?', '{"key_points": [{"id": "KP1", "description": "Stream the remote file line-by-line over HTTP with timeouts and context management instead of loading the entire payload into memory.", "required": true, "acceptable_evidence": ["Technical keywords: requests.get(..., stream=True) / urllib.request.urlopen, iter_lines(decode_unicode=True), context manager (`with`), timeout.", "Explains opening a streaming HTTP connection with an explicit timeout (`timeout=10`), calling `response.raise_for_status()`, and iterating lazily over lines to maintain $O(1)$ memory usage."]}, {"id": "KP2", "description": "Parse and validate each book record defensively, handling headers, blank lines, and malformed page counts.", "required": true, "acceptable_evidence": ["Technical keywords: csv.reader / str.rsplit, schema validation, ValueError handling, malformed row logging.", "Explains stripping whitespace, skipping empty/header lines, extracting the page count field safely (e.g., via `csv` module or delimiter splitting), and validating that pages is a non-negative integer (`int(pages) >= 0`).", "Logs and skips corrupt rows without crashing the entire aggregation job."]}, {"id": "KP3", "description": "Accumulate book count and total pages in a single pass and return structured summary metrics.", "required": true, "acceptable_evidence": ["Technical keywords: single-pass accumulator (`total_books`, `total_pages`, `invalid_rows`), O(N) time complexity, O(1) auxiliary space.", "Demonstrates incrementing `total_books += 1` and `total_pages += pages` in a single streaming pass and returning a structured result or dataclass with valid and skipped counts."]}], "critical_failures": ["Calls `response.text.splitlines()` on an arbitrarily large remote file, risking OOM, or omits HTTP timeouts and status code checks.", "Crashes with an unhandled `ValueError` or `IndexError` when encountering a trailing newline, header row, or malformed record."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design and implement a playing card deck system with shuffle and draw functionalities to support a simple card game?', '{"key_points": [{"id": "KP1", "description": "Model `Suit`, `Rank`, and `Card` using `Enum` and an immutable `@dataclass(frozen=True)` value object.", "required": true, "acceptable_evidence": ["Technical keywords: Enum (Suit, Rank), @dataclass(frozen=True), value object, Cartesian product (`itertools.product`).", "Explains defining `Suit` and `Rank` enums and an immutable `Card(suit, rank)` dataclass so individual card instances cannot be mutated once dealt.", "Initializes a standard 52-card deck cleanly via `[Card(s, r) for s in Suit for r in Rank]`."]}, {"id": "KP2", "description": "Implement unbiased $O(N)$ in-place shuffling using the Fisher-Yates (Knuth) algorithm (`random.shuffle`).", "required": true, "acceptable_evidence": ["Technical keywords: Fisher-Yates shuffle, `random.shuffle` / `random.Random(seed)`, uniform permutation, O(N) time complexity.", "Explains that Fisher-Yates iterates backward from `i = n-1` down to `1`, swapping `cards[i]` with a random index `j in [0, i]`, guaranteeing all $52!$ permutations are equally likely in $O(N)$ time.", "Supports injecting a seeded `random.Random` instance for deterministic unit testing."]}, {"id": "KP3", "description": "Implement $O(1)$ `draw()` from the top of the deck with explicit empty-deck boundary handling and reset/discard management.", "required": true, "acceptable_evidence": ["Technical keywords: list.pop() O(1) amortized, EmptyDeckError / ValueError, remaining count (`__len__`), discard pile reshuffle.", "Explains popping from the end of the internal list (`self._cards.pop()`) for $O(1)$ time complexity rather than `pop(0)` ($O(N)$ shift), raising a clear exception or reshuffling the discard pile when `len(deck) == 0`."]}], "critical_failures": ["Implements naive shuffling that swaps every index with `randint(0, n-1)` ($n^n$ outcomes), producing a statistically biased shuffle.", "Fails to handle drawing from an empty deck or exposes the internal card list directly to external mutation."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'HARD', 'SPECIFIC', 120, 'How would you identify repeating patterns in a string, such as the longest prefix that is also a suffix, to optimize encoding?', '{"key_points": [{"id": "KP1", "description": "Define the Longest Proper Prefix which is also a Suffix (LPS / KMP $\\\\pi$-table) and why naive $O(N^2)$ slice comparison is suboptimal.", "required": true, "acceptable_evidence": ["Technical keywords: Longest Proper Prefix-Suffix (LPS array), KMP prefix function (pi table), proper prefix (`len < N`), O(N) vs O(N^2).", "Explains that for any position $i$, `lps[i]` stores the length of the longest proper prefix of `s[0..i]` that matches a suffix of `s[0..i]`, avoiding $O(N^2)$ substring comparisons."]}, {"id": "KP2", "description": "Construct the LPS array in $O(N)$ linear time using two pointers (`i` and `length = lps[i-1]`).", "required": true, "acceptable_evidence": ["Technical keywords: two-pointer state transition, fallback transition `length = lps[length - 1]`, amortized O(N) time, O(N) space.", "Explains advancing `i` from `1` to `n-1`: when `s[i] == s[length]`, increment `length` and set `lps[i] = length`; on mismatch, fall back via `length = lps[length - 1]` without ever decrementing `i`.", "Proves amortized $O(N)$ time complexity because `length` increases at most $N$ times and cannot decrease more times than it increased."]}, {"id": "KP3", "description": "Derive the minimal repeating unit (fundamental period) and apply it to string compression/encoding.", "required": true, "acceptable_evidence": ["Technical keywords: string period `p = n - lps[n - 1]`, divisibility check `n % p == 0`, repeating substring compression.", "Explains that `lps[n - 1]` gives the longest proper prefix matching a suffix of the full string, and if `lps[n - 1] > 0` and `n % (n - lps[n - 1]) == 0`, the string is purely periodic with repeating unit `s[:n - lps[n - 1]]` repeated `n // p` times.", "Provides a concrete example: for `''ababab''` ($n=6$), `lps[-1] = 4`, period $p = 6 - 4 = 2$ (`''ab''`), encoding as `3 * ''ab''`."]}], "critical_failures": ["Includes the full string itself as a ''proper'' prefix (`len == N`), which trivially matches every string.", "Uses $O(N^2)$ brute-force prefix/suffix slicing (`s[:k] == s[-k:]` for all $k$) when each slice comparison takes $O(k)$ time."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize the duplicate detection algorithm to avoid sorting, and what trade-offs would this introduce?', '{"key_points": [{"id": "KP1", "description": "Replace $O(N \\\\log N)$ comparison sorting with a single-pass $O(N)$ Hash Set lookup.", "required": true, "acceptable_evidence": ["Technical keywords: hash set (`set`), O(1) average lookup/insert, O(N) time complexity, early exit on first duplicate.", "Explains iterating through the collection and checking `if item in seen: return True; seen.add(item)`, reducing time complexity from $O(N \\\\log N)$ (sorting) to $O(N)$ average time and preserving original input order."]}, {"id": "KP2", "description": "Analyze the core trade-offs: $O(N)$ auxiliary memory overhead, hashability constraints, and worst-case hash collisions.", "required": true, "acceptable_evidence": ["Technical keywords: O(N) space vs O(1) in-place sort, hashable requirement (`__hash__` and `__eq__`), CPU cache locality, hash collision worst-case O(N^2).", "Explains that a hash set requires $O(N)$ extra RAM to store distinct keys and hash table buckets (whereas in-place sorting uses $O(1)$–$O(\\\\log N)$ space), requires elements to be immutable/hashable, and has poorer CPU cache locality than contiguous array sorting."]}, {"id": "KP3", "description": "Handle massive datasets that exceed RAM using Bloom filters or hash-partitioned external buckets.", "required": false, "acceptable_evidence": ["Technical keywords: Bloom filter (probabilistic bit array, false positive rate, zero false negatives), hash partitioning to disk shards.", "Explains using a Bloom filter to screen out unique items in fixed memory (verifying only positives against disk/DB) or partitioning records by `hash(x) % K` into disk buckets so each bucket fits in memory."]}], "critical_failures": ["Claims hash set deduplication uses $O(1)$ space or fails to recognize the $O(N)$ memory trade-off compared to in-place sorting.", "Uses `if item in seen_list:` on a Python `list` instead of a `set`, degrading time complexity to $O(N^2)$."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What is your perspective on using no-code or low-code AI tools, and what are their trade-offs?', '{"key_points": [{"id": "KP1", "description": "Identify high-value use cases for low-code/no-code AI tools (rapid prototyping, domain-expert validation, internal workflow automation).", "required": true, "acceptable_evidence": ["Technical keywords: rapid POC validation, visual workflow builders (Flowise, Dify, Langflow, n8n), SME prompt iteration, time-to-market.", "Explains that low-code tools accelerate initial discovery, allowing product managers and domain SMEs to test prompt flows, RAG connectors, and basic automations in hours rather than weeks."]}, {"id": "KP2", "description": "Analyze production engineering limitations: version control, automated testing, custom orchestration, and observability.", "required": true, "acceptable_evidence": ["Technical keywords: Git diffability / CI-CD regression gates, custom hybrid retrieval / stateful graph control (LangGraph), latency overhead, vendor lock-in.", "Explains that visual JSON/GUI workflows are difficult to review in Git PRs, unit-test deterministically, or optimize for fine-grained concurrency, streaming, custom RBAC metadata filtering, and tail-latency SLAs."]}, {"id": "KP3", "description": "Articulate a pragmatic hybrid adoption strategy: prototype in low-code, graduate validated high-scale systems to code-first architectures.", "required": true, "acceptable_evidence": ["Technical keywords: prototype-to-production graduation pattern, enterprise governance/security compliance, TCO at scale.", "Proposes using low-code platforms to validate business ROI and gather initial evaluation datasets, then migrating core customer-facing or regulated workflows to code-first frameworks (FastAPI, LangGraph, Pydantic) with full CI/CD and telemetry."]}], "critical_failures": ["Takes an absolutist stance (either dismissing rapid prototyping tools entirely or claiming no-code tools can replace all custom engineering for complex, regulated, high-scale systems without trade-offs)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'And the embedding are you doing through the database or you doing externally the embedding?', '{"key_points": [{"id": "KP1", "description": "Contrast external embedding generation in the ingestion/query microservice against database-integrated embedding extensions.", "required": true, "acceptable_evidence": ["Technical keywords: external embedding service (SentenceTransformers / Bedrock / OpenAI SDK), in-database auto-embedding (Chroma embedding_function, Weaviate vectorizer, pgai), decoupling.", "Clearly distinguishes computing vector representations in an external Python/GPU inference layer (passing float32 arrays to the DB) from delegating text-to-vector conversion to the database engine."]}, {"id": "KP2", "description": "Justify external embedding generation for production scale: GPU batching, independent scaling, caching, and database portability.", "required": true, "acceptable_evidence": ["Technical keywords: GPU dynamic batching, Redis query embedding cache, zero vendor lock-in, DB CPU/connection pool protection.", "Explains that externalizing embeddings allows batching thousands of chunks on GPU workers, caching frequent query vectors in Redis before hitting the DB, switching vector stores (e.g., Chroma to Milvus/PGVector) without re-architecting, and keeping DB nodes focused on ANN index I/O."]}, {"id": "KP3", "description": "Enforce strict model and normalization consistency (`model_id`, `L2` norm) across external ingestion and query paths.", "required": true, "acceptable_evidence": ["Technical keywords: shared embedding client library, embedding_model_version metadata, L2 normalization parity.", "Explains that when embeddings are generated externally, both the offline indexing pipeline and online query service must share the exact same model checkpoint, tokenizer, prefix formatting, and normalization logic."]}], "critical_failures": ["Performs synchronous external HTTP embedding calls inside a relational database trigger holding row/table locks.", "Uses different embedding models or normalization settings between external ingestion and query time."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'Are there any scripted prompts that go to each agent in your system, along with all of this RAG and chunking strategies?', '{"key_points": [{"id": "KP1", "description": "Design modular, role-specific system prompts for each specialized agent (Supervisor, Retriever/Researcher, SQL/Tool Agent, Validator/Critic).", "required": true, "acceptable_evidence": ["Technical keywords: role persona & scope boundaries, tool usage rules, negative constraints, versioned prompt templates.", "Explains that each agent receives a distinct, version-controlled system prompt defining its specific responsibility, allowed tools, escalation conditions, and strict anti-hallucination boundaries."]}, {"id": "KP2", "description": "Format and inject retrieved RAG chunks with source metadata delimiters into the agent''s dynamic context block.", "required": true, "acceptable_evidence": ["Technical keywords: XML/Markdown context delimiters (`<context doc_id=''...'' version=''...''>`), citation anchoring, instruction-data separation.", "Explains how chunked and reranked documents are injected into a structured prompt template with explicit `doc_id`, `section`, and `effective_date` attributes so the synthesis agent can cite sources and resist prompt injection."]}, {"id": "KP3", "description": "Coordinate inter-agent state passing using typed schemas (Pydantic/JSON) rather than raw unstructured chat history.", "required": true, "acceptable_evidence": ["Technical keywords: typed agent state (`TypedDict` / `Pydantic`), structured output contracts, context window pruning.", "Explains constraining each agent''s prompt to output structured JSON (e.g., rewritten queries, extracted claims, validation verdicts) so downstream agents receive clean, predictable inputs."]}, {"id": "KP4", "description": "Align chunking granularity (parent-child / semantic chunks) with the specific agent''s task requirements.", "required": false, "acceptable_evidence": ["Technical keywords: task-specific retrieval profile, fine-grained chunks for fact lookup vs parent chunks for synthesis.", "Explains configuring retrieval parameters per agent (e.g., high-precision top-3 chunks for a fact-verifier agent vs broader parent-document context for a summarization agent)."]}], "critical_failures": ["Uses a single monolithic, generic prompt across all agents or concatenates raw retrieved text into the prompt without source attribution or structural delimiters."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you describe how you would integrate FAISS with a managed vector database like Pinecone in a production system?', '{"key_points": [{"id": "KP1", "description": "Compare the architectural roles of FAISS (in-process C++ ANN library) and Pinecone (fully managed distributed vector database).", "required": true, "acceptable_evidence": ["Technical keywords: FAISS (in-memory library, sub-millisecond local search, no built-in CRUD/persistence), Pinecone (managed cloud persistence, metadata filtering, namespaces, horizontal scaling).", "Explains that FAISS provides ultra-fast local vector math and clustering in RAM/GPU without network hops, whereas Pinecone provides durable storage, live CRUD upserts, RBAC metadata filtering, and multi-tenant namespaces."]}, {"id": "KP2", "description": "Design a tiered L1/L2 retrieval or local pre-filtering pattern combining FAISS and Pinecone.", "required": true, "acceptable_evidence": ["Technical keywords: L1 hot-tier FAISS cache (semantic cache / FAQ index), L2 authoritative Pinecone corpus, session-scoped ephemeral FAISS index.", "Explains two production integration patterns: (1) using an in-memory FAISS index as a sub-millisecond L1 semantic cache or hot-document index in front of Pinecone (L2), or (2) using FAISS in memory for ephemeral user-uploaded session files while querying Pinecone for the enterprise knowledge base."]}, {"id": "KP3", "description": "Use FAISS offline for high-speed batch deduplication, k-means clustering, or quantization before upserting to Pinecone.", "required": true, "acceptable_evidence": ["Technical keywords: GPU-accelerated near-duplicate vector pruning (cosine > 0.98), k-means centroid computation, batch upsert.", "Explains running FAISS on ingestion workers to deduplicate millions of chunk vectors locally at high speed before paying network and storage costs to upsert into Pinecone."]}, {"id": "KP4", "description": "Maintain embedding space parity and cache invalidation between FAISS and Pinecone.", "required": false, "acceptable_evidence": ["Technical keywords: distance metric parity (Inner Product + L2 norm = Cosine), TTL/CDC invalidation, score calibration.", "Explains ensuring both indices use identical embedding models, vector dimensions, and distance metrics (`IndexFlatIP` with L2-normalized vectors matching Pinecone cosine similarity) and invalidating local FAISS entries on document updates."]}], "critical_failures": ["Treats FAISS as a drop-in distributed database with built-in multi-node persistence, metadata filtering, and transactional CRUD.", "Mixes incompatible distance metrics (e.g., unnormalized L2 in FAISS vs Cosine in Pinecone) when merging scores across tiers."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you describe the architecture and use case of your RAG-based application, including how you used LangChain and structured the overall workflow?', '{"key_points": [{"id": "KP1", "description": "Define the business use case and decouple the offline ingestion pipeline from the online low-latency query pipeline.", "required": true, "acceptable_evidence": ["Technical keywords: enterprise knowledge/domain assistant, offline asynchronous ingestion pipeline, online synchronous/streaming query pipeline.", "Explains the target problem (grounding answers in dynamic enterprise documents with verifiable citations) and separates document parsing/indexing from real-time user query serving."]}, {"id": "KP2", "description": "Detail the offline ingestion workflow: document loaders, structure-aware chunking, metadata enrichment, and vector indexing.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain DocumentLoaders, RecursiveCharacterTextSplitter / MarkdownHeaderTextSplitter, metadata tagging (`doc_id`, `acl_role`, `version`), batch embedding upsert.", "Walks through extracting clean text, splitting with overlap to preserve context, attaching filterable metadata, and indexing vectors + BM25 lexical tokens."]}, {"id": "KP3", "description": "Structure the online query orchestration using LangChain Expression Language (LCEL) or LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: LCEL (`RunnableParallel`, `RunnablePassthrough`, pipe `|` operator), history-aware query rewriting, EnsembleRetriever (BM25 + dense), Cross-Encoder reranking.", "Explains orchestrating conversational query contextualization, hybrid retrieval with metadata filters, cross-encoder reranking (`ContextualCompressionRetriever`), and grounded prompt synthesis."]}, {"id": "KP4", "description": "Implement streaming delivery (`astream`), structured citation outputs, and fallback/observability guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: async streaming (`astream` / `astream_events`), Pydantic structured output with citations, abstention on low relevance, LangSmith/Langfuse tracing.", "Explains streaming tokens via FastAPI SSE while enforcing citation grounding and logging full trace telemetry."]}], "critical_failures": ["Describes a toy single-script prototype (`RetrievalQA.from_chain_type`) with no metadata filtering, no reranking, no conversation history handling, and synchronous blocking ingestion."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you describe your current work at Wells Fargo, including the system architecture and key components of the RAG-based AI assistant you built?', '{"key_points": [{"id": "KP1", "description": "Frame the enterprise financial use case and strict regulatory requirements (data residency, zero external data leakage, auditability).", "required": true, "acceptable_evidence": ["Technical keywords: internal banking policy/operations assistant, VPC-isolated LLM endpoints, zero model training on customer data, immutable audit trail.", "Explains assisting banking/wealth operations or engineering teams across complex regulatory policies, compliance manuals, and internal procedures within a strictly isolated cloud VPC."]}, {"id": "KP2", "description": "Describe the secure ingestion pipeline with version lifecycle management and Role-Based Access Control (RBAC) metadata tagging.", "required": true, "acceptable_evidence": ["Technical keywords: PII scrubbing (Presidio), hierarchical section chunking, effective_date / is_latest versioning, ACL entitlement tags.", "Explains parsing regulatory PDFs/tables, tagging every chunk with document version, effective date, and AD/IAM security groups so superseded policies are never served as current."]}, {"id": "KP3", "description": "Detail the hybrid retrieval and reranking architecture optimized for exact financial terminology and semantic intent.", "required": true, "acceptable_evidence": ["Technical keywords: pre-search RBAC metadata filtering, hybrid search (BM25 for policy codes/acronyms + dense embeddings), Reciprocal Rank Fusion (RRF), Cross-Encoder reranker.", "Explains enforcing user ACL filters pre-retrieval, combining sparse keyword matching (for exact form numbers/regulatory clauses) with dense embeddings, and reranking top candidates."]}, {"id": "KP4", "description": "Enforce strict citation grounding, deterministic abstention guardrails, and compliance observability.", "required": true, "acceptable_evidence": ["Technical keywords: mandatory inline citations, confidence threshold abstention, faithfulness evaluation, Prometheus/Grafana/Langfuse audit logging.", "Explains requiring every claim to cite an exact policy section, abstaining when retrieval confidence is below threshold, and logging every query, retrieved chunk ID, and response for regulatory audits."]}], "critical_failures": ["Proposes sending unredacted banking customer data to public consumer LLM APIs or omits pre-retrieval RBAC permission filtering and policy version control."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you describe your experience building end-to-end RAG pipelines using frameworks like LangChain, LlamaIndex, and vector databases such as ChromaDB and PGVector?', '{"key_points": [{"id": "KP1", "description": "Contrast when to use LlamaIndex vs LangChain/LangGraph in an end-to-end RAG architecture.", "required": true, "acceptable_evidence": ["Technical keywords: LlamaIndex (hierarchical node parsers, AutoMergingRetriever, SubQuestionQueryEngine), LangChain/LangGraph (LCEL chains, multi-step tool/agent state orchestration).", "Explains leveraging LlamaIndex for complex document ingestion, hierarchical parent-child node indexing, and structured data connectors, while using LangChain/LangGraph for multi-step workflow orchestration, tool calling, and conversational state machines."]}, {"id": "KP2", "description": "Contrast ChromaDB vs PostgreSQL with `pgvector` for storage, transactional consistency, and operational overhead.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB (lightweight embedded/client-server HNSW prototyping), PGVector (ACID transactions, SQL JOINs with relational tables, HNSW/IVFFlat indexes, enterprise backups).", "Explains using ChromaDB for rapid local development and standalone microservice collections, and choosing `pgvector` in production when vector embeddings must join transactionally with relational user/permission tables under a unified PostgreSQL backup and HA setup."]}, {"id": "KP3", "description": "Configure vector indexing parameters (`HNSW` `m`, `ef_construction`, `ef_search`) and hybrid search (`tsvector` + dense).", "required": true, "acceptable_evidence": ["Technical keywords: HNSW index (`vector_cosine_ops`, `m`, `ef_construction`), PostgreSQL full-text search (`tsvector`/`GIN`) + RRF fusion, metadata indexing (`B-tree`/`GIN`).", "Demonstrates tuning HNSW parameters and combining PostgreSQL native full-text search (`ts_rank_cd`) with `pgvector` cosine distance (`<=>`) via Reciprocal Rank Fusion."]}, {"id": "KP4", "description": "Manage incremental ingestion via content hashes and evaluate pipeline quality with automated RAG metrics.", "required": false, "acceptable_evidence": ["Technical keywords: SHA-256 content hash upsert/deduplication, RAGAS evaluation (Context Recall, Faithfulness).", "Explains tracking document hashes for idempotent incremental updates and gating changes on retrieval/faithfulness metrics."]}], "critical_failures": ["Runs sequential exact scans on large `pgvector` tables without creating an `HNSW` or `IVFFlat` index or matching the query operator (`<=>`) to the index operator class (`vector_cosine_ops`)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'Can you describe your experience with multi-agent architectures and how they extend or enhance RAG-based systems?', '{"key_points": [{"id": "KP1", "description": "Identify the limitations of static single-pass (''naive'') RAG on complex, multi-hop, or heterogeneous queries.", "required": true, "acceptable_evidence": ["Technical keywords: single-shot retrieval bottleneck, multi-hop reasoning failure, heterogeneous data sources (SQL + Vector + APIs), zero self-correction.", "Explains that linear `Retrieve -> Generate` pipelines fail when a query requires decomposing sub-questions, combining live SQL database metrics with unstructured policy PDFs, or recovering from an initial empty/irrelevant retrieval."]}, {"id": "KP2", "description": "Explain how multi-agent topologies (Supervisor/Router, Researcher, SQL/API Specialist, Critic/Verifier) enhance retrieval and synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: query decomposition & routing, parallel sub-agent execution, Corrective RAG (CRAG), Self-RAG reflection loop.", "Walks through how a Supervisor decomposes a complex prompt, dispatches parallel retrieval/tool tasks to specialized agents (e.g., Vector RAG Agent + Text-to-SQL Agent), and uses a Critic Agent to grade relevance and rewrite queries if context is insufficient."]}, {"id": "KP3", "description": "Manage shared state, deterministic cycle limits, and context isolation using graph orchestration (e.g., LangGraph).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph `StateGraph`, typed shared state (`TypedDict`), `Send` API for map-reduce fan-out, `max_iterations` recursion guard.", "Explains passing compact structured artifacts between agents rather than dumping noisy intermediate tool traces into every agent''s context window, while enforcing hard iteration caps (e.g., `max_retries=2`)."]}, {"id": "KP4", "description": "Address the latency and token cost trade-offs of multi-agent RAG via tiered routing.", "required": true, "acceptable_evidence": ["Technical keywords: complexity router (fast-path single RAG vs multi-agent path), small-model routing/grading, latency budget.", "Explains routing simple factual queries directly to a fast single-pass RAG pipeline (~1.5s) and reserving multi-agent loops for complex analytical queries."]}], "critical_failures": ["Routes every trivial FAQ lookup through a 5-agent conversational loop, exploding latency and token costs without a fast-path router or loop termination bound."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'Can you explain BM25?', '{"key_points": [{"id": "KP1", "description": "Define Okapi BM25 as a bag-of-words probabilistic lexical ranking algorithm that improves upon classic TF-IDF.", "required": true, "acceptable_evidence": ["Technical keywords: Okapi BM25 (Best Matching 25), sparse lexical retrieval, inverted index, TF-IDF improvement.", "Explains that BM25 scores documents based on exact query term overlap weighted by term rarity and normalized document length."]}, {"id": "KP2", "description": "Explain the three mathematical components of BM25: Inverse Document Frequency ($IDF$), Term Frequency saturation ($k_1$), and Document Length Normalization ($b$).", "required": true, "acceptable_evidence": ["Technical keywords: IDF (rarity weighting), TF saturation parameter `k1` (typically 1.2–2.0), length normalization parameter `b` (typically 0.75), average document length (`avgdl`).", "Explains how $k_1$ creates diminishing returns for repeated term occurrences (unlike unbounded linear TF in TF-IDF) and how $b \\\\in [0, 1]$ penalizes long documents relative to $|D| / \\\\text{avgdl}$."]}, {"id": "KP3", "description": "Explain why BM25 is paired with dense embeddings in hybrid RAG retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: exact match strength (SKUs, error codes, acronyms, proper nouns), zero semantic synonym awareness, hybrid search with RRF.", "Explains that BM25 excels at exact identifiers where dense embeddings blur meaning, while dense embeddings capture synonyms and conceptual similarity where BM25 fails."]}], "critical_failures": ["Claims BM25 uses neural vector embeddings or captures semantic synonyms without shared lexical tokens.", "Cannot distinguish BM25 from basic TF-IDF (omitting term frequency saturation $k_1$ and document length normalization $b$)."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'Can you explain Precision@K and its importance in retrieval systems?', '{"key_points": [{"id": "KP1", "description": "Define `Precision@K` mathematically and compute it with a concrete numerical example.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K = (Relevant documents in top K) / K, cutoff rank K.", "States the formula $\\\\text{Precision@}K = \\\\frac{|\\\\text{Relevant} \\\\cap \\\\text{Top-}K|}{K}$ and gives an example (e.g., if $K=5$ retrieved chunks contain 3 relevant chunks, $\\\\text{Precision@}5 = 3/5 = 0.60$)."]}, {"id": "KP2", "description": "Explain why `Precision@K` is critical in RAG pipelines (signal-to-noise ratio, token costs, and ''Lost in the Middle'' mitigation).", "required": true, "acceptable_evidence": ["Technical keywords: context window signal-to-noise ratio, distractor chunk hallucination, Lost in the Middle phenomenon, LLM prompt token cost.", "Explains that low `Precision@K` injects irrelevant distractor chunks into the LLM prompt, increasing latency/cost and degrading synthesis accuracy."]}, {"id": "KP3", "description": "Identify the limitations of `Precision@K` (order-insensitivity and total-relevant ceiling) and pair it with `Recall@K`, `MRR`, or `NDCG@K`.", "required": true, "acceptable_evidence": ["Technical keywords: rank-order insensitivity, Recall@K, Mean Reciprocal Rank (MRR), NDCG@K.", "Explains that `Precision@K` does not care whether the relevant chunk is at rank 1 or rank $K$, and is capped at $1/K$ when only 1 relevant document exists in the corpus, requiring complementary metrics like `Recall@K` and `NDCG@K`."]}], "critical_failures": ["Confuses `Precision@K` with `Recall@K` (dividing by total relevant documents in the corpus instead of $K$).", "Claims `Precision@K` is sensitive to the exact ranking position of relevant items within the top $K$."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'Can you explain the Phase 2 multi-agent architecture you are building and how it differs from the Phase 1 RAG system?', '{"key_points": [{"id": "KP1", "description": "Contrast the control flow: Phase 1 static DAG (`Rewrite -> Retrieve -> Rerank -> Generate`) vs Phase 2 stateful cyclic graph (`Plan -> Route -> Act -> Verify -> Reflect`).", "required": true, "acceptable_evidence": ["Technical keywords: linear DAG vs cyclic state graph (LangGraph), autonomous planning/decomposition, iterative reflection loop.", "Explains that Phase 1 executed a fixed single-pass retrieval over unstructured docs, whereas Phase 2 uses a stateful graph that dynamically decomposes complex goals, invokes multiple tools/agents, and self-corrects."]}, {"id": "KP2", "description": "Detail the specialized agent roles and expansion beyond vector stores to live transactional tools (SQL, REST APIs, calculators).", "required": true, "acceptable_evidence": ["Technical keywords: Supervisor/Router Agent, RAG Research Agent, SQL/API Tool Agent, Compliance/Critic Agent, multi-source synthesis.", "Explains how Phase 2 combines unstructured policy retrieval (Phase 1 capability) with live structured database queries, external API lookups, and deterministic validation steps."]}, {"id": "KP3", "description": "Compare state management, memory persistence, and human-in-the-loop (HITL) checkpoints.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph checkpointers (Postgres/Redis), thread-level state persistence, interrupt_before HITL approval gates.", "Explains that Phase 2 persists granular intermediate execution state across steps, enabling pause/resume for human approval before executing state-mutating actions."]}, {"id": "KP4", "description": "Compare evaluation and reliability guardrails between Phase 1 (chunk recall/faithfulness) and Phase 2 (trajectory evaluation, tool accuracy, loop budgets).", "required": true, "acceptable_evidence": ["Technical keywords: trajectory/step evaluation, tool-selection accuracy, max_iterations circuit breaker, hybrid latency routing.", "Explains adding agent trajectory evaluation, step-count budgets, and a complexity router that keeps simple queries on the fast Phase 1 path."]}], "critical_failures": ["Describes Phase 2 as merely adding a larger LLM or more documents without explaining agent specialization, tool use, state checkpoints, or iterative verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you explain the architecture of the RAG system you worked on, including the ingestion and query pipelines?', '{"key_points": [{"id": "KP1", "description": "Detail the asynchronous offline/event-driven ingestion pipeline (extraction, cleaning, chunking, metadata tagging, and dual indexing).", "required": true, "acceptable_evidence": ["Technical keywords: event-driven ingestion (S3/webhook -> queue), layout-aware PDF/HTML parsing, structure-aware chunking with overlap, SHA-256 idempotency, dense + sparse indexing.", "Walks through extracting text and tables, splitting into semantically coherent chunks (e.g., 512 tokens with 10-15% overlap), attaching metadata (`doc_id`, `acl`, `timestamp`), generating batch embeddings, and upserting into vector and BM25 indexes."]}, {"id": "KP2", "description": "Detail the online query transformation and pre-filtered hybrid retrieval stage.", "required": true, "acceptable_evidence": ["Technical keywords: conversational query contextualization, RBAC metadata pre-filtering, parallel dense ANN + sparse BM25 retrieval, Reciprocal Rank Fusion (RRF).", "Explains rewriting follow-up queries into standalone search queries, applying mandatory user permission filters, retrieving top-$N$ candidates (e.g., $N=50$) from both dense and sparse indexes, and fusing via RRF."]}, {"id": "KP3", "description": "Explain cross-encoder reranking and context window assembly.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranker (BGE-Reranker / Cohere Rerank), top-K cutoff (e.g., K=5–8), parent-chunk expansion, token budget packing.", "Explains scoring query-chunk pairs jointly with a cross-encoder to select the top $K$ highest-precision chunks and ordering them with clear XML/Markdown source headers."]}, {"id": "KP4", "description": "Describe grounded generation, streaming response delivery, and observability/caching layers.", "required": true, "acceptable_evidence": ["Technical keywords: citation-enforced prompt, SSE token streaming, Redis embedding/semantic cache, Langfuse/RAGAS telemetry.", "Explains streaming grounded answers with inline `[doc_id]` citations and abstaining when maximum reranker relevance falls below a calibrated threshold."]}], "critical_failures": ["Couples heavy document ingestion synchronously to the user query thread or omits metadata filtering and reranking."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 210, 'Can you explain the architecture of the RAG-based system you built for code review, including ingestion, chunking, embedding, and retrieval?', '{"key_points": [{"id": "KP1", "description": "Design Git webhook/CI-triggered incremental ingestion and diff parsing for pull requests and repository state.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub/GitLab webhook, unified git diff parser (hunks, added/modified lines), incremental commit-tree indexing (`git diff --name-only`), coding standards corpus.", "Explains indexing both the target repository codebase (incrementally updated on merge via commit SHA diffs) and engineering architecture/security style guides."]}, {"id": "KP2", "description": "Implement syntax-aware AST chunking (`tree-sitter`) rather than naive character/token splitting.", "required": true, "acceptable_evidence": ["Technical keywords: Abstract Syntax Tree (AST), tree-sitter, class/function/method boundary preservation, file imports & docstring header injection.", "Explains parsing source files with `tree-sitter` so functions, methods, and classes remain intact syntactic units, prepending the file path, module imports, and enclosing class signature to every code chunk."]}, {"id": "KP3", "description": "Use code-specialized embeddings paired with lexical symbol/identifier indexing and static call-graph metadata.", "required": true, "acceptable_evidence": ["Technical keywords: code embedding models (voyage-code-2 / CodeBERT / StarEncoder), symbol metadata (`function_name`, `called_symbols`, `imported_modules`, `language`), BM25 camelCase/snake_case tokenizer.", "Explains generating dense embeddings with a code-trained model while indexing exact symbol names, type definitions, and caller/callee relationships for lexical and graph lookup."]}, {"id": "KP4", "description": "Execute multi-signal retrieval per PR diff hunk: changed symbol definitions, caller/callee impact, similar historical bugs, and team style rules.", "required": true, "acceptable_evidence": ["Technical keywords: symbol definition lookup (LSP/ctags/AST), hybrid BM25 + vector retrieval, cross-encoder reranking, multi-file dependency resolution.", "Explains that reviewing a diff hunk requires retrieving (1) definitions of functions/types modified or called in the diff, (2) callers impacted by signature changes, and (3) relevant security/architecture standards."]}, {"id": "KP5", "description": "Synthesize structured inline PR review comments with linter/SAST verification to suppress false positives.", "required": false, "acceptable_evidence": ["Technical keywords: structured JSON review (`file_path`, `line_number`, `severity`, `suggested_patch`), SAST/linter pre-check (Ruff, Semgrep), confidence filtering.", "Explains combining deterministic static analysis output with LLM semantic review and posting only high-confidence, actionable inline PR comments."]}, {"id": "KP6", "description": "Enforce security & secret-scanning guardrails before sending proprietary repository diffs to the LLM.", "required": true, "acceptable_evidence": ["Technical keywords: pre-flight secret scanning (Gitleaks / TruffleHog), `.aiignore` sensitive file exclusion, VPC-hosted LLM endpoint.", "Explains scanning diffs for hardcoded keys/credentials and excluding restricted paths before constructing the code-review prompt."]}, {"id": "KP7", "description": "Capture developer feedback on inline PR comments (resolved, thumbs-up/down, dismissed) to tune rule precision.", "required": false, "acceptable_evidence": ["Technical keywords: PR comment resolution tracking, false-positive suppression, golden code-review benchmark.", "Explains tracking which AI review comments lead to actual code commits in follow-up pushes vs which get dismissed as noise, pruning low-value prompt rules."]}], "critical_failures": ["Splits source code with fixed character/word counts that slice functions mid-expression and strip enclosing class/import context.", "Feeds only the isolated git diff lines to the LLM without retrieving referenced symbol definitions or cross-file callers."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'BROAD', 150, 'Can you explain your experience deploying machine learning or RAG systems to production using Docker, Kubernetes (EKS), and AWS?', '{"key_points": [{"id": "KP1", "description": "Build optimized, secure multi-stage Docker images for ML/RAG services and push to Amazon ECR.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage Dockerfile, slim/distroless base image, non-root user, layer caching for Python wheels/model weights, Amazon ECR image scanning.", "Explains separating build dependencies (`gcc`, build wheels) from the runtime image, pinning dependencies, baking or pre-warming tokenizer/reranker weights to avoid cold-start downloads, and running as a non-root UID."]}, {"id": "KP2", "description": "Configure Kubernetes workloads on AWS EKS with separate CPU and GPU node groups, resource limits, and health probes.", "required": true, "acceptable_evidence": ["Technical keywords: EKS Managed Node Groups / Karpenter, CPU vs GPU nodes (`nvidia.com/gpu`, taints & tolerations), requests/limits, startupProbe / readinessProbe / livenessProbe.", "Explains running I/O-bound RAG orchestration pods on cost-effective CPU nodes while scheduling local embedding/reranker inference pods onto GPU nodes using node selectors/tolerations and `startupProbe` to accommodate model loading time."]}, {"id": "KP3", "description": "Implement autoscaling (HPA/KEDA), AWS IAM Roles for Service Accounts (IRSA), and VPC-private networking.", "required": true, "acceptable_evidence": ["Technical keywords: Horizontal Pod Autoscaler (HPA) / KEDA (queue depth or concurrent requests), IRSA (OIDC least-privilege access to Bedrock/S3/Secrets Manager), AWS Load Balancer Controller (ALB), VPC Endpoints (PrivateLink).", "Explains using IRSA instead of static AWS keys so pods securely access S3, Bedrock, and Secrets Manager over private VPC endpoints, and scaling pods via HPA/KEDA."]}, {"id": "KP4", "description": "Automate zero-downtime deployments (rolling/canary) with CI/CD gates and Prometheus/CloudWatch observability.", "required": false, "acceptable_evidence": ["Technical keywords: RollingUpdate / Argo Rollouts canary, PodDisruptionBudget (PDB), Prometheus/Grafana/CloudWatch metrics, automatic rollback.", "Explains gating deployments on automated RAG evaluation and container vulnerability checks, then executing progressive rollouts with automatic rollback on error-rate or p95 latency spikes."]}], "critical_failures": ["Hardcodes static AWS IAM credentials inside Docker images or Kubernetes ConfigMaps instead of using IRSA and Secrets Manager.", "Omits `startupProbe`/`readinessProbe` on ML pods, causing Kubernetes to send live traffic before model weights finish loading into memory."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you explain your experience working with vector databases such as ChromaDB and Milvus, including how you managed metadata and retrieval efficiency?', '{"key_points": [{"id": "KP1", "description": "Contrast ChromaDB (embedded/single-node simplicity) with Milvus (cloud-native distributed storage/compute separation for billion-scale vectors).", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB (rapid prototyping, small-to-medium collections), Milvus (distributed QueryNode/DataNode/IndexNode architecture, S3/MinIO object storage, high QPS).", "Explains using ChromaDB for local dev and smaller workloads, and migrating to Milvus when requiring distributed horizontal scaling, multi-replica query nodes, and hybrid dense + sparse vector support at scale."]}, {"id": "KP2", "description": "Design explicit metadata schemas, scalar indexes (`INVERTED` / bitmap), and partition keys for fast pre-filtering.", "required": true, "acceptable_evidence": ["Technical keywords: scalar field indexing (`INVERTED`, `BITMAP`), partition_key (`tenant_id` or `department`), bitset pre-filtering (`doc_id`, `acl_group`, `effective_date`, `is_latest`).", "Explains indexing high-selectivity scalar metadata fields and enabling `partition_key` in Milvus so queries prune entire physical segments before evaluating vector distances."]}, {"id": "KP3", "description": "Tune ANN index types and quantization (`HNSW`, `IVF_FLAT`, `IVF_SQ8`/`PQ`) to balance recall, latency, and RAM footprint.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW (`M`, `efConstruction`, `ef`), IVF (`nlist`, `nprobe`), scalar/product quantization (`SQ8`, `PQ`), segment compaction.", "Explains tuning `HNSW` parameters (`M=16–32`, `ef=64–128`) for low-latency high-recall search, applying `SQ8` quantization to cut memory usage by ~70% with minimal recall loss, and compacting growing segments into sealed indexed segments."]}, {"id": "KP4", "description": "Optimize runtime I/O by excluding bulky raw text or unused fields during initial scoring or using MMap.", "required": false, "acceptable_evidence": ["Technical keywords: `output_fields` projection, memory-mapped (MMap) storage, consistency level (`Bounded` vs `Strong`).", "Explains projecting only necessary `output_fields` and tuning Milvus consistency levels (`Bounded` for high-throughput reads vs `Strong` for immediate read-after-write tests)."]}], "critical_failures": ["Performs post-filtering after retrieving top-$K$ vectors globally (resulting in empty results when the filter is selective) instead of indexed pre-filtering.", "Leaves growing segments uncompacted or unindexed in Milvus, degrading queries to brute-force scans."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you explain your retrieval pipeline, including embedding generation, hybrid search, re-ranking, and prompt construction?', '{"key_points": [{"id": "KP1", "description": "Stage 1 — Query preprocessing and consistent embedding generation (with query-instruction prefixes and L2 normalization).", "required": true, "acceptable_evidence": ["Technical keywords: conversational query rewriting, asymmetric query prefix (e.g., BGE/E5 instruction prefix), L2 vector normalization, embedding cache.", "Explains rewriting ambiguous follow-up queries into standalone search strings, applying any model-specific query prefix, generating an L2-normalized vector, and checking a Redis cache for repeated queries."]}, {"id": "KP2", "description": "Stage 2 — Pre-filtered hybrid search combining dense vector ANN and sparse BM25 via Reciprocal Rank Fusion (RRF).", "required": true, "acceptable_evidence": ["Technical keywords: metadata/RBAC pre-filter, dense ANN (top-50) + sparse BM25/SPLADE (top-50), Reciprocal Rank Fusion (`1 / (k + rank)` with `k=60`).", "Explains executing dense and lexical searches in parallel within the user''s authorized metadata scope and fusing the candidate lists using rank-based RRF (`k=60`) to avoid raw score calibration skew."]}, {"id": "KP3", "description": "Stage 3 — Cross-encoder reranking and relevance threshold gating.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder joint self-attention (query + chunk), top-N to top-K compression (e.g., 50 -> 5), minimum relevance cutoff.", "Explains passing the top 30–50 fused candidates through a Cross-Encoder reranker (`bge-reranker-large` or Cohere Rerank) to compute fine-grained token-level interaction scores, keeping the top 5–8 chunks above a relevance floor."]}, {"id": "KP4", "description": "Stage 4 — Context deduplication, parent-window expansion, and structured prompt construction with citation rules.", "required": true, "acceptable_evidence": ["Technical keywords: overlapping chunk deduplication/merging, XML/Markdown context blocks (`<source id=''...''>`), Lost-in-the-Middle ordering, abstention instruction.", "Explains merging adjacent/overlapping chunks, formatting each chunk with explicit metadata headers, placing the highest-ranked evidence at the boundaries of the context block, and instructing the LLM to cite `[source_id]` or abstain if unsupported."]}], "critical_failures": ["Averages raw uncalibrated BM25 scores (unbounded `[0, inf)`) directly with cosine similarity scores (`[-1, 1]`) without rank fusion or normalization.", "Stuffs all 50 retrieved chunks directly into the LLM prompt without reranking or deduplication."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you explain your understanding of Primer''s platform and how it leverages RAG-based applications for NLP tasks across structured and unstructured data?', '{"key_points": [{"id": "KP1", "description": "Explain the core mission of decision-intelligence RAG platforms like Primer: near-real-time situational awareness with zero-hallucination provenance.", "required": true, "acceptable_evidence": ["Technical keywords: multi-source intelligence synthesis, mission-critical provenance/verifiability, temporal event tracking, briefing generation.", "Explains ingesting high-velocity streams of unstructured reports, news, filings, and structured telemetry to produce verifiable analytical briefings where every statement traces back to source evidence."]}, {"id": "KP2", "description": "Combine classical NLP pipelines (NER, entity linking, relation/event extraction, temporal tagging) with vector indexing during ingestion.", "required": true, "acceptable_evidence": ["Technical keywords: Named Entity Recognition (NER), canonical entity resolution/linking, event & timestamp extraction, metadata-enriched chunks.", "Explains running fast encoder/NLP models during ingestion to extract people, organizations, locations, geopolitics/financial events, and timestamps, storing them as structured metadata and knowledge-graph edges alongside dense/sparse vectors."]}, {"id": "KP3", "description": "Orchestrate hybrid retrieval across both structured stores (SQL, time-series, entity graphs) and unstructured document indexes.", "required": true, "acceptable_evidence": ["Technical keywords: query router/decomposer, structured query generation (SQL/Cypher/API) + unstructured hybrid RAG, temporal recency weighting.", "Explains decomposing complex analytical queries so structured quantitative facts/timelines are fetched from relational/graph databases while qualitative context is retrieved via entity- and time-filtered hybrid vector search."]}, {"id": "KP4", "description": "Enforce sentence-level citation grounding, cross-source contradiction surfacing, and claim verification.", "required": true, "acceptable_evidence": ["Technical keywords: sentence-level inline citations, conflicting-source detection, NLI entailment verification.", "Explains instructing the synthesis layer to surface discrepancies when multiple sources report conflicting facts rather than silently picking one, and verifying claim entailment before delivery."]}], "critical_failures": ["Treats structured tabular/entity databases as plain text blobs to be chunked naively instead of combining structured queries/NER metadata with unstructured RAG."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Can you walk us through your background and experience building end-to-end AI systems using RAG and agentic architectures?', '{"key_points": [{"id": "KP1", "description": "Present a structured progression of hands-on experience from classical ML/NLP to production RAG and multi-agent architectures.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end system ownership, domain context (financial/enterprise/code/healthcare), architectural progression (RAG -> Agentic workflows).", "Articulates a coherent engineering narrative covering problem definition, architecture design, implementation, and production operations."]}, {"id": "KP2", "description": "Highlight concrete technical depth in the RAG stack (structure-aware chunking, hybrid BM25+vector search, cross-encoder reranking, RBAC metadata).", "required": true, "acceptable_evidence": ["Technical keywords: LangChain/LlamaIndex, Milvus/PGVector/ChromaDB, hybrid RRF retrieval, Cross-Encoder reranking, citation grounding.", "Details specific engineering decisions made in data ingestion, retrieval optimization, and hallucination mitigation."]}, {"id": "KP3", "description": "Highlight experience designing stateful multi-agent workflows (LangGraph, tool calling, SQL/API validation, reflection loops).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph stateful orchestration, Supervisor/Specialist/Critic agents, schema-validated tool calling, human-in-the-loop checkpoints.", "Explains extending static retrieval with multi-agent reasoning, deterministic tool validation, and bounded retry loops."]}, {"id": "KP4", "description": "Demonstrate production discipline: evaluation rigor (RAGAS/LLM-as-a-Judge), observability (Langfuse/Prometheus), cloud deployment (AWS EKS), and measurable business impact.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset CI gates (Recall@K, Faithfulness), p95 latency/cost optimization, Docker/EKS deployment, quantifiable KPI improvement.", "Connects technical implementation to measurable outcomes (e.g., improved recall/faithfulness, reduced call handling or PR review turnaround time, SLA adherence)."]}], "critical_failures": ["Recites buzzwords without explaining specific architectural choices, failure modes encountered in production, or measurable quality/business metrics."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Describe your monitoring and observability strategy for the production RAG system, including the tools used for traceability (Prometheus, Grafana, CloudWatch).', '{"key_points": [{"id": "KP1", "description": "Instrument stage-by-stage latency, throughput, and error metrics using Prometheus histograms/counters and visualize on Grafana dashboards.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus `Histogram` / `Counter`, stage latency breakdown (embedding, vector ANN, reranker, LLM TTFT, total E2E), p50/p95/p99, Grafana Golden Signals dashboard.", "Explains tracking p50/p95/p99 latencies separately for each pipeline stage alongside request rate, HTTP/API 4xx/5xx error rates, token consumption rate, and Redis cache hit ratio."]}, {"id": "KP2", "description": "Centralize structured JSON logs and infrastructure/container telemetry in AWS CloudWatch (EKS Container Insights, ALB, Bedrock/RDS metrics).", "required": true, "acceptable_evidence": ["Technical keywords: structured JSON logging (`trace_id`, `user_id`, `doc_ids`, `latency_ms`), CloudWatch Logs Insights, EKS Container Insights (CPU/GPU/RAM), Bedrock InvocationThrottles.", "Explains emitting structured JSON logs with a correlated `trace_id` to CloudWatch Logs and monitoring EKS pod memory/GPU utilization, vector DB disk/IOPS, and AWS Bedrock throttling alarms."]}, {"id": "KP3", "description": "Monitor RAG-specific retrieval and semantic quality signals to detect silent degradation.", "required": true, "acceptable_evidence": ["Technical keywords: reranker top-1 score distribution drift, zero-hit / abstention rate spike, asynchronous RAGAS/LLM-judge sampling (Faithfulness, Answer Relevance).", "Explains that infrastructure `200 OK` status does not guarantee answer quality; monitors rolling distributions of retrieval similarity scores, fallback/abstention rates, and async faithfulness scores."]}, {"id": "KP4", "description": "Configure actionable alerting thresholds and runbook-linked incident notifications (Alertmanager / CloudWatch Alarms -> PagerDuty/Slack).", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus Alertmanager / CloudWatch Alarms, SLA breach triggers (e.g., p95 > 4s, 5xx > 1%, abstention spike), trace drill-down.", "Explains wiring automated alerts for latency SLA breaches, vector DB connection exhaustion, or sudden drops in retrieval confidence."]}], "critical_failures": ["Monitors only container CPU/memory and HTTP 200 status codes while remaining completely blind to retrieval score degradation, hallucination spikes, or LLM token cost runaway."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 210, 'Did you explore knowledge graph-based RAG approaches, and what were your findings or challenges with them?', '{"key_points": [{"id": "KP1", "description": "Explain the core value proposition of Knowledge Graph RAG (GraphRAG): multi-hop relational reasoning and global corpus synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: entity-relationship triples `(Subject, Predicate, Object)`, multi-hop graph traversal, hierarchical community summaries (Leiden clustering), Neo4j / Amazon Neptune.", "Explains that standard vector RAG struggles when answers require traversing relationships across disparate documents (e.g., ''Which suppliers of Component X are owned by parent companies subject to Regulation Y?'') or summarizing global themes across an entire corpus."]}, {"id": "KP2", "description": "Analyze the ingestion and graph construction bottleneck: LLM extraction cost, ontology drift, and entity resolution.", "required": true, "acceptable_evidence": ["Technical keywords: LLM triple extraction token cost (10x–20x higher than embedding), entity disambiguation/canonicalization (`Wells Fargo & Co.` vs `WFC`), schema/ontology enforcement.", "Explains that extracting nodes and edges via LLMs is slow and expensive at ingestion time, and without strict canonical entity resolution, duplicate/synonymous nodes fragment the graph topology."]}, {"id": "KP3", "description": "Analyze query-time challenges: Text-to-Cypher brittleness, supernode subgraph explosion, and incremental update complexity.", "required": true, "acceptable_evidence": ["Technical keywords: Text-to-Cypher syntax/schema errors, high-degree ''supernode'' neighborhood explosion, document deletion/edge pruning lifecycle.", "Explains that 2- or 3-hop traversals through high-degree hub nodes can pull thousands of irrelevant edges into the prompt, and deleting or updating a source document requires reference-counting every extracted node and edge."]}, {"id": "KP4", "description": "Describe the pragmatic production architecture: hybrid vector-first retrieval augmented by deterministic metadata/entity graph expansion.", "required": true, "acceptable_evidence": ["Technical keywords: vector entry-point + bounded 1-hop graph expansion, parameterized Cypher templates, NER/AST deterministic graph extraction.", "Explains using vector/BM25 search to anchor onto initial entities/chunks and then executing bounded, parameterized graph lookups (rather than unconstrained LLM-generated Cypher) only for queries requiring relational traversal."]}, {"id": "KP5", "description": "Implement community-detection hierarchical summaries (e.g., Leiden algorithm) for global sensemaking queries.", "required": false, "acceptable_evidence": ["Technical keywords: Leiden hierarchical community clustering, pre-computed community summaries, map-reduce global query answering.", "Explains pre-computing summaries of densely connected entity communities to answer corpus-wide thematic questions that have no single matching text chunk."]}, {"id": "KP6", "description": "Enforce node/edge ACL security filtering during graph traversal to prevent cross-tenant relationship leakage.", "required": false, "acceptable_evidence": ["Technical keywords: edge-level ACL attributes, filtered Cypher path traversal (`ALL(r IN relationships(p) WHERE ...)`), tenant subgraph isolation.", "Explains verifying user permissions on every traversed edge so multi-hop paths cannot bridge across confidential documents."]}], "critical_failures": ["Claims GraphRAG is a cheap, universally superior drop-in replacement for vector search without acknowledging ingestion cost, entity resolution, or graph maintenance challenges."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'Did you incorporate human-in-the-loop evaluation, and how did your approach differ between RAG and multi-agent systems?', '{"key_points": [{"id": "KP1", "description": "Describe HITL evaluation for RAG systems: SME grading of retrieval relevance, citation faithfulness, and completeness on stratified trace samples.", "required": true, "acceptable_evidence": ["Technical keywords: offline SME annotation queue, relevance/faithfulness/completeness rubrics, inter-annotator agreement (Cohen''s Kappa), LLM-as-a-Judge calibration.", "Explains sampling production RAG traces (prioritizing low reranker scores, abstentions, and user thumbs-down) for domain SMEs to verify whether the right policy chunks were retrieved and accurately cited, using those labels to calibrate automated LLM judges."]}, {"id": "KP2", "description": "Contrast HITL for multi-agent systems: evaluating full execution trajectories (planning, routing, tool selection, argument construction, recovery).", "required": true, "acceptable_evidence": ["Technical keywords: trajectory-level evaluation, step efficiency, tool selection & parameter accuracy, error recovery grading, state handoff inspection.", "Explains that evaluating only the final text output of a multi-agent system is insufficient; reviewers inspect the intermediate state graph trace to verify whether the Supervisor chose the optimal path, passed valid tool arguments, and avoided redundant loops."]}, {"id": "KP3", "description": "Implement runtime synchronous HITL approval gates (`interrupt_before`) for high-risk or state-mutating agent actions.", "required": true, "acceptable_evidence": ["Technical keywords: synchronous runtime HITL vs asynchronous post-hoc evaluation, LangGraph `interrupt_before` checkpointing, human approve/edit/reject resume.", "Explains that while RAG is read-only (allowing asynchronous post-hoc HITL sampling), multi-agent systems that execute write actions (DB updates, external emails, financial transactions) require synchronous runtime checkpoints where execution pauses for human approval or parameter editing before committing."]}, {"id": "KP4", "description": "Feed human annotations back into golden regression suites, router/prompt updates, and few-shot tool examples.", "required": false, "acceptable_evidence": ["Technical keywords: continuous evaluation flywheel, golden trajectory dataset, CI/CD regression gate.", "Explains converting human-corrected RAG answers and agent trajectories into automated CI test cases."]}, {"id": "KP5", "description": "Design ergonomic reviewer tooling showing side-by-side source evidence, agent state diffs, and one-click rubric grading.", "required": false, "acceptable_evidence": ["Technical keywords: annotation UI (Argilla / Langfuse / Label Studio), highlighted source spans, trajectory step timeline, rubric keyboard shortcuts.", "Explains reducing SME review time by rendering highlighted chunk citations alongside the generated claim or agent tool payload."]}, {"id": "KP6", "description": "Measure inter-annotator agreement (`Cohen''s Kappa` / `Krippendorff''s Alpha`) and resolve rubric ambiguity before training automated judges.", "required": false, "acceptable_evidence": ["Technical keywords: Cohen''s Kappa (`> 0.75`), calibration adjudication sessions, rubric disambiguation.", "Explains having multiple SMEs grade an overlapping subset of traces to ensure the human evaluation rubric itself is unambiguous and consistent."]}], "critical_failures": ["Treats multi-agent evaluation identically to single-turn text grading without inspecting intermediate tool calls, state transitions, or runtime action approval gates."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Do you have any experience working directly with RAG or broadly in the wealth management industry?', '{"key_points": [{"id": "KP1", "description": "Explain wealth management RAG use cases (advisor copilot, CIO market research synthesis, client portfolio policy lookup, regulatory compliance).", "required": true, "acceptable_evidence": ["Technical keywords: financial advisor copilot, SEC/FINRA regulatory compliance, investment research synthesis, trust/estate policy retrieval.", "Describes grounding advisor workflows in approved house research, product prospectuses, fee schedules, and regulatory compliance guidelines."]}, {"id": "KP2", "description": "Address financial document ingestion challenges: complex tables, fee schedules, footnotes, and strict temporal/version validity.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware table extraction (Markdown/HTML table preservation), effective_date / temporal filtering, fund ticker & CUSIP metadata.", "Explains preserving financial tables and fee tiers intact during chunking (never splitting row headers from values) and filtering out expired market commentary or superseded compliance circulars."]}, {"id": "KP3", "description": "Enforce strict client data isolation (Chinese walls / household entitlements) and hybrid retrieval across exact identifiers and concepts.", "required": true, "acceptable_evidence": ["Technical keywords: pre-retrieval entitlement filtering (`advisor_id`, `household_id`, `jurisdiction`), hybrid search (BM25 for tickers/CUSIPs/tax forms + dense embeddings).", "Explains enforcing advisor/client ACLs at the database query layer and combining exact lexical match for tickers/CUSIPs/IRS codes with semantic vector search."]}, {"id": "KP4", "description": "Implement fiduciary guardrails: no unapproved personalized investment advice, deterministic calculations via tools, and full SEC/FINRA audit logging.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic calculator/SQL tools (no LLM mental math), mandatory source citations, compliance refusal guardrails, WORM audit trail.", "Explains offloading portfolio math to deterministic Python/SQL tools, requiring verbatim citations to approved disclosures, and logging every interaction for regulatory examination."]}], "critical_failures": ["Allows the LLM to perform portfolio return/tax arithmetic via token prediction or retrieve cross-client records without entitlement pre-filtering."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Do you know that you could take the same Medallion Architecture and apply it to vector stores?', '{"key_points": [{"id": "KP1", "description": "Define the **Bronze Layer**: immutable raw document landing zone with provenance and content hashing.", "required": true, "acceptable_evidence": ["Technical keywords: Bronze layer (raw immutable landing zone), S3/ADLS/Delta Lake, source provenance (`source_uri`, `ingested_at`, `sha256_hash`).", "Explains storing raw PDFs, HTML, DOCX, and API payloads unaltered in the Bronze tier so downstream parsing or chunking changes can always be replayed from source without re-scraping."]}, {"id": "KP2", "description": "Define the **Silver Layer**: parsed, cleaned, PII-redacted, deduplicated, and canonicalized structured blocks/chunks.", "required": true, "acceptable_evidence": ["Technical keywords: Silver layer (cleaned & normalized text/tables), OCR/layout parsing, PII scrubbing, near-duplicate removal, enriched metadata (`acl_roles`, `effective_date`).", "Explains storing clean, model-agnostic Markdown/JSON document segments and validated metadata in Silver tables (Parquet/Delta), decoupled from any specific embedding model."]}, {"id": "KP3", "description": "Define the **Gold Layer**: consumption-ready vector indexes, BM25 indexes, and task-specific embeddings with zero-downtime re-indexing.", "required": true, "acceptable_evidence": ["Technical keywords: Gold layer (production vector store / Milvus / PGVector), model-versioned embedding collections, blue-green index re-embedding from Silver.", "Explains generating embeddings from Silver into Gold vector collections; when upgrading embedding models (e.g., MiniLM to BGE-Large) or tuning chunk sizes, you simply re-compute Gold from Silver without repeating expensive Bronze OCR/PII pipelines."]}], "critical_failures": ["Streams raw uncleaned documents directly into the vector database without persisting intermediate Bronze/Silver layers, forcing full re-scraping and re-OCR whenever the embedding model changes."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'EASY', 'SPECIFIC', 60, 'Does the embedding model need to be the same model as the inference model? Can you use an embedding model to infer?', '{"key_points": [{"id": "KP1", "description": "State clearly that the embedding model and generative inference LLM do NOT need to be the same model or from the same vendor.", "required": true, "acceptable_evidence": ["Technical keywords: decoupled retrieval and generation, cross-vendor compatibility (e.g., BGE/OpenAI embeddings + Anthropic Claude/Llama-3 generation).", "Explains that the embedding model only maps queries and chunks into a shared vector space to retrieve plain-text passages; those raw text passages are then passed into the generative LLM''s prompt, so the two models never share hidden states or tokenizers."]}, {"id": "KP2", "description": "Explain why an embedding model cannot perform autoregressive text generation, while enfatizing that indexing and query embeddings MUST use the exact same embedding model.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder encoder-only architecture, mean/CLS pooling to fixed-dimension vector (`R^d`), no causal language modeling (LM) decoding head, index-query embedding space parity.", "Explains that embedding models (e.g., BERT/RoBERTa/E5/BGE bi-encoders) compress an input sequence into a single fixed-size vector ($\\\\mathbb{R}^d$) for similarity search/classification and lack a causal decoder head to generate token sequences autoregressively.", "Clarifies the critical invariant: while the generator LLM is independent, the **document indexing embedding model** and **query embedding model** must be identical."]}, {"id": "KP3", "description": "Clarify what inference tasks an embedding model CAN perform (similarity scoring, clustering, zero-shot classification, k-NN anomaly detection).", "required": false, "acceptable_evidence": ["Technical keywords: cosine similarity inference, k-NN classification, semantic clustering, feature extraction for downstream classifiers.", "Notes that while an embedding model cannot generate conversational answers, its forward pass (''embedding inference'') can directly power semantic routing, classification, and clustering."]}], "critical_failures": ["Claims the embedding model and generative LLM must come from the same model family/vendor, or confuses index-vs-query embedding parity with embedding-vs-generator parity.", "Claims a pooled bi-encoder embedding model can directly generate conversational text responses."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Explain the hybrid retrieval approach used in your RAG system, detailing how semantic and keyword search are combined to fetch relevant context from the Milvus vector database.', '{"key_points": [{"id": "KP1", "description": "Define the Milvus collection schema storing both a dense vector field (`FLOAT_VECTOR`) and a sparse lexical field (`SPARSE_FLOAT_VECTOR`) alongside scalar metadata.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus 2.4+ multi-vector schema, `FLOAT_VECTOR` (HNSW/IVF), `SPARSE_FLOAT_VECTOR` (`SPARSE_INVERTED_INDEX`, BM25/SPLADE/BGE-M3), scalar metadata fields.", "Explains configuring a unified Milvus collection where each chunk entity holds a dense semantic vector, a sparse lexical vector (BM25 or SPLADE weights), and indexed scalar metadata."]}, {"id": "KP2", "description": "Execute parallel sub-queries using multiple `AnnSearchRequest` objects inside `client.hybrid_search()` with shared metadata pre-filtering.", "required": true, "acceptable_evidence": ["Technical keywords: `AnnSearchRequest`, `hybrid_search()`, shared `expr` metadata pre-filter (`IP` / `COSINE`), candidate `limit`.", "Demonstrates constructing two `AnnSearchRequest` instances (one targeting `dense_vector` with `HNSW`, one targeting `sparse_vector` with `SPARSE_INVERTED_INDEX`), both applying the user''s RBAC/metadata filter `expr` before scoring."]}, {"id": "KP3", "description": "Fuse dense and sparse rankings using `RRFRanker` (Reciprocal Rank Fusion) or `WeightedRanker`.", "required": true, "acceptable_evidence": ["Technical keywords: `RRFRanker(k=60)`, `WeightedRanker(w_dense, w_sparse)`, rank normalization vs score normalization.", "Explains why `RRFRanker(k=60)` ($\\\\sum \\\\frac{1}{k + \\\\text{rank}_i}$) is preferred by default to combine unbounded sparse BM25/SPLADE inner-product scores with bounded dense cosine scores without manual calibration."]}, {"id": "KP4", "description": "Apply a second-stage Cross-Encoder reranker on the top fused Milvus candidates before prompt assembly.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval (Milvus top-40 -> Cross-Encoder top-5), `bge-reranker-large`, precision@K boost.", "Explains retrieving the top 30–50 fused candidates from Milvus and passing them through a cross-encoder reranker to select the final top 5–8 chunks for the LLM."]}], "critical_failures": ["Combines raw unnormalized BM25 scores and dense cosine scores via simple addition without rank fusion or min-max/z-score normalization.", "Applies metadata filters only to one branch of the hybrid search, leaking unauthorized chunks through the other branch."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How can AI help reduce operational costs, improve efficiency, and increase accuracy in insurance or brokerage workflows?', '{"key_points": [{"id": "KP1", "description": "Automate unstructured document intake and extraction (ACORD forms, loss runs, policy schedules, claims FNOL).", "required": true, "acceptable_evidence": ["Technical keywords: Intelligent Document Processing (IDP), ACORD forms / loss runs / policy declarations, schema-validated structured extraction, manual data-entry reduction.", "Explains replacing manual re-keying of multi-page PDF submissions, endorsements, and medical/claim attachments with layout-aware extraction + schema-validated LLM parsing."]}, {"id": "KP2", "description": "Accelerate underwriting and brokerage workflows with RAG-powered policy coverage comparison and clause gap detection.", "required": true, "acceptable_evidence": ["Technical keywords: policy wording comparison (exclusions, sub-limits, deductibles, endorsements), E&O (Errors & Omissions) risk reduction, citation-backed underwriting copilot.", "Explains using hybrid RAG to compare expiring policies against renewal quotes or carrier binders side-by-side, automatically flagging hidden coverage exclusions or sub-limit changes with exact page citations."]}, {"id": "KP3", "description": "Route workflows via confidence-based Human-in-the-Loop (HITL) triage and deterministic rule engines.", "required": true, "acceptable_evidence": ["Technical keywords: straight-through processing (STP) for high-confidence routine tasks, HITL exception queue for complex/ambiguous claims, deterministic rating/actuarial tools.", "Explains keeping premium calculations and binding rules in deterministic engines while using confidence thresholds to auto-process clean routine submissions and route edge cases to senior underwriters."]}, {"id": "KP4", "description": "Quantify operational KPIs (quote turnaround time, claims handling time, E&O error rate, cost per transaction) under regulatory auditability.", "required": true, "acceptable_evidence": ["Technical keywords: quote-to-bind cycle time, Average Handle Time (AHT), loss-ratio / leakage accuracy, immutable audit logs.", "Links technical deployment to concrete brokerage/insurance metrics while maintaining full regulatory audit trails."]}], "critical_failures": ["Proposes fully autonomous, unverified LLM binding or claims denial without deterministic actuarial rules, citation provenance, or human-in-the-loop compliance review."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did overlapping embeddings impact your system, and what strategies did you use to mitigate this issue?', '{"key_points": [{"id": "KP1", "description": "Identify the two causes and negative impacts of overlapping embeddings: sliding-window chunk redundancy and vector space crowding of boilerplate templates.", "required": true, "acceptable_evidence": ["Technical keywords: sliding-window overlap redundancy, boilerplate semantic crowding/hubness, top-K slot exhaustion, Recall@K diversity drop.", "Explains that (1) high chunk overlap causes near-identical adjacent chunks from the same paragraph to consume multiple top-$K$ slots, and (2) standardized templates/headers across documents cluster tightly in embedding space, drowning out subtle distinguishing details."]}, {"id": "KP2", "description": "Mitigate during ingestion: structure-aware chunking, boilerplate stripping, contextual header injection, and parent-child indexing.", "required": true, "acceptable_evidence": ["Technical keywords: boilerplate removal, contextual chunk headers (`Document Title > Section`), ParentDocumentRetriever / AutoMergingRetriever, domain fine-tuned embeddings.", "Explains stripping repetitive legal/template footers before embedding, prepending distinctive document/section metadata to disambiguate similar clauses, and indexing small child chunks that resolve to deduplicated parent windows."]}, {"id": "KP3", "description": "Mitigate at query time: Maximal Marginal Relevance (MMR), hybrid BM25 lexical disambiguation, and post-retrieval span merging.", "required": true, "acceptable_evidence": ["Technical keywords: Maximal Marginal Relevance (MMR, `lambda_mult`), hybrid BM25 + dense RRF, post-retrieval contiguous chunk merging (`doc_id` + adjacent `chunk_index`), Cross-Encoder reranking.", "Explains using MMR to penalize candidate chunks that are overly similar to already-selected chunks, combining BM25 to differentiate exact version/clause numbers, and merging overlapping contiguous chunks from the same `doc_id` before prompt construction."]}], "critical_failures": ["Sets chunk overlap to 50%+ without post-retrieval span merging or MMR, filling the entire top-$K$ context window with duplicate slices of the same paragraph."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did the RAG-based code review system improve developer productivity and reduce pull request turnaround time?', '{"key_points": [{"id": "KP1", "description": "Eliminate the initial review wait-time bottleneck by delivering context-aware feedback within minutes of PR creation inside CI/CD.", "required": true, "acceptable_evidence": ["Technical keywords: Time-to-First-Review (TTFR), asynchronous CI webhook trigger, pre-human review pass, reduced context-switching.", "Explains that developers receive actionable feedback on architectural violations, edge cases, and security patterns within 1–2 minutes of opening a PR rather than waiting hours or days for a senior reviewer."]}, {"id": "KP2", "description": "Ground reviews in repository-specific AST call graphs, internal SDK conventions, and historical post-mortems to keep signal-to-noise high.", "required": true, "acceptable_evidence": ["Technical keywords: repo-specific RAG grounding (internal libraries, ADR docs, call-graph impact), actionable inline diff suggestions, low false-positive rate.", "Explains that unlike generic LLM code review (which hallucinates nonexistent helper methods), RAG grounding cites exact internal patterns and catches cross-file breaking changes before human review begins."]}, {"id": "KP3", "description": "Track concrete engineering productivity and quality metrics (PR cycle time, review rounds, suggestion acceptance rate).", "required": true, "acceptable_evidence": ["Technical keywords: PR merge turnaround time (cycle time), review ping-pong iterations, comment acceptance/resolution rate, escaped defect rate.", "Quantifies impact via reduced back-and-forth review cycles, faster time-to-merge, and freed senior engineer bandwidth to focus on high-level system design."]}], "critical_failures": ["Floods every PR with noisy style nitpicks already handled by linters (`Ruff`/`ESLint`), causing alert fatigue and slowing developers down."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did the SQL validation agent ensure correctness in terms of syntax, schema, and data retrieval?', '{"key_points": [{"id": "KP1", "description": "Layer 1 — Deterministic SQL syntax and security policy enforcement via AST parsing (`sqlglot`) before touching the database.", "required": true, "acceptable_evidence": ["Technical keywords: `sqlglot` AST parsing, dialect validation, read-only `SELECT` enforcement (blocking `DROP`, `DELETE`, `UPDATE`, `GRANT`), stacked-query prevention.", "Explains parsing the generated query into an AST using `sqlglot` to verify dialect syntax, reject any DDL/DML mutation statements, and enforce row limits (`LIMIT`)."]}, {"id": "KP2", "description": "Layer 2 — Schema and execution-plan validation against live database catalog metadata and `EXPLAIN` dry runs.", "required": true, "acceptable_evidence": ["Technical keywords: catalog metadata verification (tables, columns, foreign keys, data types), `EXPLAIN` query plan check, error-guided self-correction loop.", "Explains verifying that every referenced table, column, and join key exists in the authorized schema catalog, running `EXPLAIN` in a read-only transaction with a statement timeout, and feeding exact database error messages back to the generator for bounded retry (max 2–3 attempts)."]}, {"id": "KP3", "description": "Layer 3 — Semantic data retrieval sanity checking (empty result debugging, NULL/fan-out traps, and unit alignment with user intent).", "required": true, "acceptable_evidence": ["Technical keywords: zero-row / NULL result diagnosis, cartesian join fan-out check, value/enum probing, semantic question-to-SQL alignment.", "Explains that a syntactically valid query can still return wrong data (e.g., filtering `WHERE status = ''Active''` when the DB stores `''ACTIVE''`, or duplicating sums across a 1-to-many join); the validation agent inspects result statistics and probes distinct column values when 0 rows return."]}], "critical_failures": ["Executes raw LLM-generated SQL directly against a read-write production database user without AST validation, read-only permissions, or statement timeouts.", "Assumes a query is semantically correct simply because it executed without throwing a SQL syntax error."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you associate embeddings with user permissions and enforce role-based retrieval?', '{"key_points": [{"id": "KP1", "description": "Attach ACL/permission metadata (`allowed_roles`, `tenant_id`, `department`, `classification`) to every chunk at ingestion time.", "required": true, "acceptable_evidence": ["Technical keywords: source ACL inheritance (SharePoint/Confluence/IAM), scalar array metadata (`allowed_groups`, `tenant_id`), indexed scalar bitsets.", "Explains extracting document access control lists from the source system during ingestion and storing them as indexed scalar metadata fields alongside every chunk vector (plus physical namespace/partition isolation per tenant)."]}, {"id": "KP2", "description": "Enforce server-side **pre-filtering** during ANN/hybrid search using claims extracted from the authenticated user''s JWT/IAM session.", "required": true, "acceptable_evidence": ["Technical keywords: JWT/OAuth2 server-side claim extraction, pre-filtering (`ARRAY_CONTAINS_ANY(allowed_roles, user_roles)`), zero prompt-based security.", "Explains resolving the caller''s verified identity and group memberships in the backend API from their auth token and injecting a mandatory pre-filter expression into both vector and BM25 search requests so unauthorized chunks are never scored or returned."]}, {"id": "KP3", "description": "Synchronize permission changes without re-embedding and scope semantic caches by permission signature.", "required": true, "acceptable_evidence": ["Technical keywords: metadata-only partial update / relational ACL join (`pgvector`), permission-scoped cache key (`hash(query + sorted(user_roles))`), prompt-injection immunity.", "Explains updating ACL metadata fields via event hooks (or joining against a live relational ACL table) without recomputing embeddings, and hashing the user''s role set into any semantic/response cache key to prevent cross-role cache poisoning."]}], "critical_failures": ["Retrieves top-$K$ chunks globally and relies on the LLM system prompt (''Do not reveal confidential info'') to enforce access control.", "Performs naive post-filtering after fetching top-5 global results, or shares an un-scoped semantic response cache across users with different permission levels."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How did you balance maintaining the original RAG system while introducing agentic AI for new use cases?', '{"key_points": [{"id": "KP1", "description": "Encapsulate the battle-tested Phase 1 RAG pipeline as a reusable, versioned tool/service invoked by both direct queries and Phase 2 agents.", "required": true, "acceptable_evidence": ["Technical keywords: shared retrieval core (single ingestion, vector store, reranker), RAG-as-a-Tool abstraction, zero duplicate indexing pipelines.", "Explains wrapping the existing hybrid retrieval + reranking pipeline as a clean internal service/tool so improvements to chunking, embeddings, or RBAC automatically benefit both the original RAG assistant and the new multi-agent workflows."]}, {"id": "KP2", "description": "Introduce an intelligent intent/complexity router at the API gateway to protect SLAs and token budgets.", "required": true, "acceptable_evidence": ["Technical keywords: complexity/intent router, fast-path Phase 1 RAG (low latency, single-hop lookup) vs slow-path Agentic workflow (multi-hop, SQL/API tools).", "Explains routing single-domain informational lookups to the fast deterministic RAG pipeline while directing complex multi-step analytical or transactional tasks to the LangGraph agent orchestrator."]}, {"id": "KP3", "description": "Use feature flags, shadow mode, and canary traffic splitting to validate agentic workflows safely alongside production RAG.", "required": true, "acceptable_evidence": ["Technical keywords: feature flags (LaunchDarkly / config-driven), shadow/dark launches, canary rollout, graceful fallback to Phase 1 RAG.", "Explains running new agentic flows in shadow mode or behind role-based feature flags, and configuring automatic circuit-breaker fallback to standard RAG if an agent exceeds its latency budget or tool retry limit."]}, {"id": "KP4", "description": "Maintain unified CI/CD regression suites and shared observability dashboards across both architectures.", "required": false, "acceptable_evidence": ["Technical keywords: unified golden evaluation suite, cost/latency per route tracking in Langfuse/Grafana.", "Ensures new agentic changes never regress baseline RAG accuracy or p95 latency."]}], "critical_failures": ["Forks the codebase into two separate ingestion/vector-store stacks that drift out of sync, or performs a ''big-bang'' replacement of a stable production RAG system without fallback or routing."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you balance retrieval parameters such as top-k selection, re-ranking, and dynamic retrieval strategies?', '{"key_points": [{"id": "KP1", "description": "Tune two-stage retrieval parameters: wide initial recall (`top_N = 30–50`) followed by tight cross-encoder precision (`top_K = 5–8`).", "required": true, "acceptable_evidence": ["Technical keywords: recall-precision funnel, initial candidate pool `top_N` (30–50), reranked context `top_K` (5–8), Pareto trade-off (Recall@N vs Precision@K vs latency).", "Explains casting a wide initial net (`top_N=50`) via fast hybrid search to maximize `Recall@N`, then using a Cross-Encoder reranker to filter down to `top_K=5` high-precision chunks so the LLM context stays focused."]}, {"id": "KP2", "description": "Apply dynamic score-threshold cutoffs and score-dropoff (''elbow'') filtering rather than rigid fixed `K`.", "required": true, "acceptable_evidence": ["Technical keywords: dynamic similarity threshold, reranker logit/probability floor (e.g., `score >= 0.35`), relative score dropoff, zero-chunk abstention.", "Explains truncating the `top_K` list early when reranker relevance drops below a calibrated threshold (avoiding padding the prompt with irrelevant tail chunks when only 2 chunks are actually relevant)."]}, {"id": "KP3", "description": "Adapt retrieval strategy and `K` dynamically based on query complexity (factoid lookup vs comparative vs multi-hop summary).", "required": true, "acceptable_evidence": ["Technical keywords: adaptive query routing, factoid (`K=3`, strict threshold) vs comparative/multi-hop (`K=8–12`, sub-query decomposition, MMR diversity).", "Explains classifying incoming queries so narrow single-fact queries fetch a small high-precision window (`K=3`) while broad comparative queries expand `K`, enable Maximal Marginal Relevance (MMR), or decompose into sub-queries."]}, {"id": "KP4", "description": "Calibrate parameters empirically using a golden evaluation dataset (grid search over `Recall@K`, `NDCG@K`, `Faithfulness`, and `p95` latency).", "required": true, "acceptable_evidence": ["Technical keywords: offline grid/Bayesian hyperparameter sweep, RAGAS evaluation curves, token cost & p95 latency SLA constraint.", "Demonstrates plotting `Recall@K` and `Faithfulness` against `p95` latency on a golden dataset to pick the knee of the curve."]}], "critical_failures": ["Passes a fixed large `top_K` (e.g., 30 un-reranked chunks) into every prompt regardless of relevance scores or query type."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'How did you build and expose your RAG system for consumption, and what technologies did you use for serving and API development?', '{"key_points": [{"id": "KP1", "description": "Build the API service layer using async `FastAPI`, `Uvicorn`/`Gunicorn` ASGI workers, and strict `Pydantic` v2 request/response schemas.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, ASGI (`uvicorn.workers.UvicornWorker`), Pydantic v2 validation (`QueryRequest`, `Citation`, `RAGResponse`), OpenAPI/Swagger spec.", "Explains exposing typed REST endpoints (`/v1/chat/stream`, `/v1/ingest`, `/healthz`) with strict Pydantic validation for query length, conversation ID, metadata filters, and structured source citations."]}, {"id": "KP2", "description": "Implement real-time token and citation streaming using Server-Sent Events (SSE / `StreamingResponse`) or WebSockets.", "required": true, "acceptable_evidence": ["Technical keywords: Server-Sent Events (`text/event-stream`), `StreamingResponse`, async generator (`yield f''data: {json.dumps(event)}\\\\n\\\\n''`), TTFT optimization.", "Explains streaming structured SSE events (`status`, `token`, `citations`, `done`, `error`) so the UI renders tokens within ~400ms Time-to-First-Token instead of blocking 5–10 seconds for full completion."]}, {"id": "KP3", "description": "Decouple heavy document ingestion from online query serving via asynchronous task queues (`Celery` / `SQS` / `Kafka`).", "required": true, "acceptable_evidence": ["Technical keywords: async job queue (Celery + Redis / AWS SQS), `202 Accepted` + `job_id` polling/webhook, worker isolation.", "Explains returning `202 Accepted` immediately on document upload and processing PDF parsing, chunking, and embedding on separate background worker pools so query API latency is never impacted."]}, {"id": "KP4", "description": "Enforce API Gateway security: OAuth2/JWT authentication, per-tenant token-bucket rate limiting, and circuit breakers.", "required": true, "acceptable_evidence": ["Technical keywords: JWT Bearer authentication, Redis rate limiting (requests/min and tokens/min), connection pooling, timeout/retry middleware.", "Explains validating JWTs via FastAPI dependency injection (`Depends(get_current_user)`), enforcing Redis rate limits, and sharing persistent connection pools to the vector DB and LLM gateway."]}], "critical_failures": ["Serves LLM responses over synchronous blocking WSGI (`Flask` dev server) without streaming or async I/O, exhausting worker threads under concurrent load."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you create and use ground truth datasets for evaluating retrieval and generation quality?', '{"key_points": [{"id": "KP1", "description": "Structure each ground-truth record with both retrieval targets (`expected_chunk_ids`) and generation targets (`reference_answer`, `required_facts`).", "required": true, "acceptable_evidence": ["Technical keywords: schema `(query, user_role, expected_doc_ids, expected_chunk_ids, reference_answer, query_type)`, component-level decoupling.", "Explains storing both ground-truth chunk IDs and reference answers so retrieval quality (`Recall@K`, `MRR`, `NDCG@K`) and generation quality (`Faithfulness`, `Answer Correctness`) can be evaluated independently."]}, {"id": "KP2", "description": "Combine three data sources: SME-curated questions, LLM-synthesized evolutionary queries (RAGAS/Evol-Instruct), and anonymized production failure traces.", "required": true, "acceptable_evidence": ["Technical keywords: synthetic question generation from chunks, multi-hop/adversarial/unanswerable query synthesis, SME verification, production trace mining.", "Explains bootstrapping coverage by prompting a strong LLM to generate single-hop, multi-hop, tabular, and unanswerable (''abstention'') test cases from corpus chunks, filtering them with domain SMEs, and continuously adding real production edge cases."]}, {"id": "KP3", "description": "Automate offline and CI/CD regression gates across retrieval and generation metrics before deploying changes.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD evaluation gate, Recall@K / MRR / NDCG@K, RAGAS Faithfulness & Context Precision, prompt/chunker/embedding A/B comparison.", "Explains running the golden dataset automatically in CI whenever chunking strategies, embedding models, rerankers, or system prompts change, blocking merges if `Recall@5` or `Faithfulness` regresses."]}, {"id": "KP4", "description": "Version the golden dataset alongside corpus snapshots to prevent stale ground-truth drift.", "required": false, "acceptable_evidence": ["Technical keywords: dataset versioning (DVC / Langfuse Datasets), corpus snapshot pinning, stale chunk_id remapping.", "Explains pinning evaluation runs to a versioned document corpus snapshot so document updates don''t silently invalidate ground-truth `chunk_ids`."]}], "critical_failures": ["Evaluates RAG solely by eyeball-testing 5–10 ad-hoc prompts or omits `expected_chunk_ids`, making it impossible to separate retrieval failures from LLM generation failures."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'SPECIFIC', 120, 'How did you decide between different embedding models like MiniLM, or maybe Ada? What was your trade-off analysis?', '{"key_points": [{"id": "KP1", "description": "Compare model specifications: vector dimensionality (`384` vs `1536`), max token sequence length (`256/512` vs `8191`), and MTEB/domain retrieval accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: `all-MiniLM-L6-v2` (384-dim, 256–512 max tokens, 22M params), `text-embedding-ada-002` / `text-embedding-3-small` (1536-dim, 8191 tokens, Matryoshka truncation), `BGE-large` / `E5-large` (1024-dim).", "Contrasts `MiniLM`''s compact 384-d vectors (4x smaller HNSW RAM footprint, but silent truncation beyond 256/512 tokens) against `Ada-002`/`text-embedding-3` (1536-d, 8191-token context window, stronger zero-shot cross-domain recall, 4x higher vector DB memory unless Matryoshka-truncated)."]}, {"id": "KP2", "description": "Analyze infrastructure, latency, cost, and data privacy/VPC residency trade-offs (self-hosted GPU/ONNX vs external SaaS API).", "required": true, "acceptable_evidence": ["Technical keywords: self-hosted ONNX/TensorRT inference (<5–10ms local latency, zero per-token API cost, strict VPC data residency, fine-tunable) vs Managed API (network RTT + rate limits, per-token billing, external data transit).", "Explains that self-hosting open-weight models (`MiniLM`, `BGE`, `E5`) in EKS keeps sensitive enterprise data inside the VPC with predictable fixed GPU cost and sub-10ms latency, whereas external API embeddings incur network latency, rate limits, and third-party data governance hurdles."]}, {"id": "KP3", "description": "Describe the empirical benchmark methodology used to make the final selection on domain data.", "required": true, "acceptable_evidence": ["Technical keywords: domain golden dataset benchmark, `Recall@5`, `MRR@10`, `NDCG@10`, HNSW index memory calculation (`N_vectors * dim * 4 bytes * 1.5`).", "Explains benchmarking candidate models on a domain-specific query-chunk test set (measuring `Recall@5`, `NDCG@10`, p95 query latency, and HNSW memory cost) rather than relying purely on generic public MTEB leaderboard rankings."]}], "critical_failures": ["Selects `all-MiniLM-L6-v2` for 1,500-token chunks without realizing it silently truncates everything past 256/512 tokens.", "Picks an embedding model based solely on public MTEB scores without testing domain recall, vector DB memory cost, or VPC privacy constraints."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'BROAD', 210, 'How did you deploy your RAG system in production, and what role did AWS services like EKS and Bedrock play?', '{"key_points": [{"id": "KP1", "description": "Architect the compute and orchestration layer on Amazon EKS across private subnets with ALB/NLB ingress and HPA/Karpenter autoscaling.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, private subnets across multiple AZs, AWS Load Balancer Controller (ALB/WAF), Karpenter / HPA autoscaling, separate API and ingestion worker deployments.", "Explains running stateless FastAPI RAG query pods and asynchronous ingestion worker pods in private EKS subnets across multiple Availability Zones behind an AWS WAF-protected Application Load Balancer."]}, {"id": "KP2", "description": "Integrate Amazon Bedrock for managed foundation models and embeddings over AWS PrivateLink VPC Endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon Bedrock (`InvokeModelWithResponseStream`, Claude 3.5 Sonnet, Titan/Cohere Embeddings, Bedrock Guardrails), VPC Interface Endpoint (AWS PrivateLink), Provisioned Throughput / cross-region inference profiles.", "Explains invoking Bedrock models via `InvokeModelWithResponseStream` over an AWS PrivateLink VPC Endpoint so prompts and retrieved context never traverse the public internet, using cross-region inference profiles or Provisioned Throughput to prevent `ThrottlingException`."]}, {"id": "KP3", "description": "Design the event-driven storage and vector database tier on AWS (S3 -> EventBridge/SQS -> EKS Workers -> Aurora pgvector / OpenSearch / Milvus).", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3 (KMS-encrypted document store), EventBridge/SQS + DLQ, Aurora PostgreSQL `pgvector` / Milvus on EKS / OpenSearch, ElastiCache for Redis.", "Walks through S3 upload events triggering SQS messages consumed by EKS ingestion pods, which parse, chunk, call Bedrock embeddings, and upsert into the vector store while ElastiCache (Redis) handles session state and semantic caching."]}, {"id": "KP4", "description": "Enforce defense-in-depth security: IAM Roles for Service Accounts (IRSA), KMS encryption, Secrets Manager, and CloudWatch/X-Ray telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: IAM Roles for Service Accounts (IRSA / OIDC), AWS KMS encryption at rest, AWS Secrets Manager, CloudWatch Container Insights.", "Explains binding fine-grained IAM policies to Kubernetes service accounts via IRSA (`bedrock:InvokeModel`, `s3:GetObject`) with zero long-lived access keys."]}, {"id": "KP5", "description": "Implement multi-region / cross-region Bedrock failover and semantic caching in Amazon ElastiCache (Redis) for resilience and cost control.", "required": true, "acceptable_evidence": ["Technical keywords: Bedrock Cross-Region Inference (`us.anthropic.claude-3-5-sonnet...`), exponential backoff with jitter, ElastiCache Redis semantic/embedding cache.", "Explains routing across primary and secondary AWS regions (`us-east-1` / `us-west-2`) to absorb regional capacity spikes while serving repeated queries from ElastiCache Redis."]}, {"id": "KP6", "description": "Provision the entire AWS stack reproducibly using Terraform/CDK with GitOps (ArgoCD) and automated CI/CD evaluation gates.", "required": false, "acceptable_evidence": ["Technical keywords: Terraform / AWS CDK state management, Helm / ArgoCD GitOps sync, pre-deployment RAGAS regression gate.", "Explains managing EKS node groups, IAM roles, VPC endpoints, and S3 buckets declaratively via Terraform and gating rollouts on automated RAG quality checks."]}, {"id": "KP7", "description": "Configure FinOps token cost attribution and AWS Budgets/CloudWatch anomaly detection per tenant and use case.", "required": false, "acceptable_evidence": ["Technical keywords: Bedrock invocation token tagging, per-tenant cost allocation, CloudWatch token-spend anomaly alarms.", "Explains tracking prompt and completion token costs per tenant/department and alerting on abnormal spend spikes."]}], "critical_failures": ["Routes sensitive enterprise prompts to Amazon Bedrock over the public internet via NAT Gateways instead of AWS PrivateLink VPC Endpoints, or uses static IAM user keys inside pods."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How did you generate embeddings using sentence transformers, and how did you ensure consistency between indexing and query embedding?', '{"key_points": [{"id": "KP1", "description": "Generate embeddings efficiently using `SentenceTransformer.encode()` with GPU batching, FP16/BF16 precision, and L2 normalization (`normalize_embeddings=True`).", "required": true, "acceptable_evidence": ["Technical keywords: `SentenceTransformer(model_name_or_path)`, `model.encode(texts, batch_size=64, normalize_embeddings=True)`, FP16 (`torch.float16`), mean pooling.", "Explains encoding texts into unit-length vectors (`normalize_embeddings=True`) so dot product (inner product) equals cosine similarity, using GPU batching (`batch_size=32–128`) during ingestion and single/micro-batch inference at query time."]}, {"id": "KP2", "description": "Enforce strict model, tokenizer, preprocessing, and asymmetric prefix parity between indexing and query pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: shared `EmbeddingService` wrapper, pinned HuggingFace commit hash/digest, `max_seq_length` parity, asymmetric prefixes (`query: ` vs `passage: ` for E5/BGE).", "Explains wrapping `SentenceTransformer` in a single shared Python package or internal microservice used by both ingestion and query services, pinning the exact model revision hash, `max_seq_length`, normalization flag, and model-required instruction prefixes."]}, {"id": "KP3", "description": "Tag every vector record with `embedding_model_id` and validate compatibility at runtime before querying.", "required": true, "acceptable_evidence": ["Technical keywords: collection/index metadata (`embedding_model_id`, `vector_dim`), startup compatibility assertion, blue-green index alias swap on model upgrade.", "Explains storing the exact `embedding_model_id` in collection metadata and asserting at API startup that the query encoder matches the indexed collection''s model version."]}], "critical_failures": ["Normalizes vectors at indexing time (`normalize_embeddings=True`) but forgets to normalize at query time (or vice versa), or swaps the embedding model checkpoint without re-indexing the corpus."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you identify issues with recall in your retrieval system, and what steps did you take to improve it?', '{"key_points": [{"id": "KP1", "description": "Diagnose recall bottlenecks quantitatively using `Recall@K` and `MRR@K` on a golden dataset and by slicing production failure modes.", "required": true, "acceptable_evidence": ["Technical keywords: `Recall@K` (`|Relevant ∩ Top-K| / |Relevant|`), retrieval-vs-generation error attribution, failure taxonomy (lexical miss, vocabulary mismatch, chunk truncation, over-restrictive metadata filter).", "Explains isolating cases where the LLM failed or abstained because the ground-truth chunk was absent from the retrieved `top_N` pool (`Recall@N == 0`), and categorizing the root causes."]}, {"id": "KP2", "description": "Improve ingestion & indexing: structure-aware/hierarchical chunking, contextual headers, and hybrid dense + BM25 search.", "required": true, "acceptable_evidence": ["Technical keywords: Parent-Child / hierarchical chunking, contextual header prepending (`Doc Title > Section`), Hybrid Search (BM25 + Dense Vector + RRF).", "Explains adding BM25 lexical search via RRF to rescue exact acronym/ID/code misses, prepending document/section headers to every chunk before embedding so orphan paragraphs retain context, and preserving intact tables."]}, {"id": "KP3", "description": "Improve query-side recall: conversational query rewriting, Multi-Query expansion, or HyDE (Hypothetical Document Embeddings).", "required": true, "acceptable_evidence": ["Technical keywords: standalone query rewriting, Multi-Query expansion (3–4 query variations + RRF union), HyDE, acronym expansion.", "Explains bridging the vocabulary gap between short user questions and formal enterprise prose by expanding queries or generating a hypothetical answer passage for embedding lookup."]}, {"id": "KP4", "description": "Tune ANN index search parameters (`ef_search` / `nprobe`), widen initial `top_N` before reranking, and upgrade/fine-tune the embedding model.", "required": false, "acceptable_evidence": ["Technical keywords: HNSW `ef_search` increase, widening candidate pool `top_N` (e.g., 10 -> 50) + Cross-Encoder reranker, stronger domain embedding model.", "Explains increasing `top_N` from 5 to 50 (paired with a cross-encoder reranker to keep `top_K=5` clean) and increasing HNSW `ef_search` to eliminate approximate graph search misses."]}], "critical_failures": ["Attempts to fix low retrieval recall solely by tweaking the final generator LLM''s system prompt or temperature when the relevant chunk was never retrieved in the first place."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you identify that your retrieval system was underperforming, and what evaluation signals or testing methods led to that conclusion?', '{"key_points": [{"id": "KP1", "description": "Isolate retrieval from generation using an offline 2x2 diagnostic matrix (Oracle Context vs Retrieved Context).", "required": true, "acceptable_evidence": ["Technical keywords: component isolation test, Oracle/Gold Context accuracy vs Retrieved Context accuracy, `Recall@K` / `MRR@K` / `Context Recall` (RAGAS).", "Explains proving retrieval is the bottleneck by showing that the LLM answers 95%+ of golden questions accurately when fed the ground-truth (''oracle'') chunk directly, but drops to e.g. 62% when fed the retriever''s output because `Recall@5` is low."]}, {"id": "KP2", "description": "Monitor online production signals: reranker score distribution drift, high abstention/fallback rates, and user reformulation loops.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder max-score distribution shift, abstention (''I don''t have enough information'') rate spike, rapid query reformulation rate, thumbs-down trace clustering.", "Explains tracking real-time telemetry where a drop in top-1 reranker confidence logits or a spike in user query re-wording within 30 seconds signals that the retriever is missing relevant documents."]}, {"id": "KP3", "description": "Conduct stratified error slicing by query category (acronyms/IDs, tabular data, multi-hop, recency-sensitive queries).", "required": true, "acceptable_evidence": ["Technical keywords: stratified failure analysis, lexical-heavy vs semantic queries, table/PDF parsing defects, stale document retrieval.", "Explains bucketing failed traces in Langfuse to pinpoint specific blind spots (e.g., dense-only search failing on exact error codes/part numbers, or broken PDF table chunking)."]}], "critical_failures": ["Measures only end-to-end answer similarity without separately scoring retrieval recall, making it impossible to know whether the retriever or the LLM generator is at fault."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'How did you integrate the backend RAG pipeline with the frontend application?', '{"key_points": [{"id": "KP1", "description": "Implement a structured Server-Sent Events (SSE) or WebSocket streaming protocol (`fetch` + `ReadableStream`) for incremental token and stage updates.", "required": true, "acceptable_evidence": ["Technical keywords: SSE (`text/event-stream`), `fetch` + `ReadableStream` + `TextDecoder`, typed event envelopes (`stage`, `delta`, `citations`, `done`, `error`), `AbortController`.", "Explains streaming multiplexed JSON events from FastAPI so the React frontend can display intermediate progress indicators (''Searching policies...'', ''Reranking 5 sources...''), render tokens incrementally, and allow the user to cancel in-flight generation via `AbortController`."]}, {"id": "KP2", "description": "Bind inline citation markers (`[1]`, `[2]`) to structured source metadata payloads for interactive document preview and deep-linking.", "required": true, "acceptable_evidence": ["Technical keywords: structured citation payload (`source_id`, `doc_title`, `page_number`, `bounding_box`/`snippet`, `presigned_url`), interactive citation drawer/popover.", "Explains sending the verified retrieved source metadata array alongside the response so clicking `[1]` in the React UI opens a side-panel highlighting the exact source passage and page number."]}, {"id": "KP3", "description": "Manage multi-turn conversation state (`session_id` / `thread_id`) and authentication headers (`Authorization: Bearer <JWT>`) on the server.", "required": true, "acceptable_evidence": ["Technical keywords: server-side conversation history (Redis/Postgres keyed by `session_id`), JWT auth header, optimistic UI updates.", "Explains passing only the new `user_message` and `session_id` from the frontend (rather than trusting client-side history arrays), while the backend loads session history from Redis and enforces user RBAC claims from the JWT."]}, {"id": "KP4", "description": "Wire trace-linked user feedback endpoints (`POST /v1/feedback` with `trace_id`) and graceful error/abstention UI states.", "required": true, "acceptable_evidence": ["Technical keywords: `trace_id` propagation to frontend, thumbs-up/down + comment webhook to Langfuse, graceful partial-failure / abstention UI.", "Explains returning the backend `trace_id` in the stream completion event so frontend feedback buttons attach ratings directly to the exact observability trace."]}], "critical_failures": ["Blocks the UI with a synchronous 15-second REST call waiting for the entire LLM response before rendering anything, or trusts client-passed role permissions in the request body."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you justify and drive adoption of a specific technology choice, such as a vector database, across teams?', '{"key_points": [{"id": "KP1", "description": "Define concrete evaluation criteria aligned with engineering, security, and business constraints before benchmarking.", "required": true, "acceptable_evidence": ["Technical keywords: evaluation matrix (scale/vector count, p95 latency at target QPS, hybrid dense+sparse support, RBAC pre-filtering, HA/DR ops, VPC compliance, TCO).", "Explains gathering requirements across application, platform/SRE, and security teams to establish objective decision criteria rather than chasing hype."]}, {"id": "KP2", "description": "Run a reproducible Proof-of-Concept (POC) benchmark across finalist candidates (e.g., `pgvector` vs `Milvus` vs `OpenSearch`/`Pinecone`) and document an Architecture Decision Record (ADR).", "required": true, "acceptable_evidence": ["Technical keywords: Architecture Decision Record (ADR), load-test benchmark (`Recall@10`, `p95/p99` latency under concurrent load, indexing throughput, memory/monthly cost).", "Explains publishing a transparent ADR comparing quantitative POC results and operational trade-offs (e.g., why `pgvector` wins for `<5M` vectors with strict relational ACL joins, or why `Milvus` wins for `50M+` multi-vector hybrid scale)."]}, {"id": "KP3", "description": "Address stakeholder concerns (SRE operational burden, InfoSec compliance, FinOps cost ceiling).", "required": true, "acceptable_evidence": ["Technical keywords: Terraform/Helm IaC modules, backup/restore runbooks, VPC isolation & encryption at rest, FinOps capacity sizing.", "Explains winning buy-in from DevOps/SRE and Security by providing automated Terraform modules, Prometheus dashboards, backup/failover runbooks, and security architecture sign-offs."]}, {"id": "KP4", "description": "Accelerate cross-team adoption with a shared internal Python SDK/template, reference architecture, and migration workshops.", "required": true, "acceptable_evidence": ["Technical keywords: paved-road internal SDK (`VectorStoreClient`), cookiecutter service template, onboarding documentation & brown-bag sessions.", "Explains lowering the adoption friction for partner teams by shipping a standardized internal client library with built-in telemetry, retries, and RBAC filtering."]}], "critical_failures": ["Mandates a technology top-down without benchmarking alternatives, calculating Total Cost of Ownership (TCO), or providing operational runbooks/SDKs for adopting teams."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you leverage LLM-as-a-judge for evaluating RAG outputs, and what criteria did you use?', '{"key_points": [{"id": "KP1", "description": "Evaluate the core RAG Triad criteria: **Context Precision/Relevance**, **Faithfulness (Groundedness)**, and **Answer Relevance/Correctness**.", "required": true, "acceptable_evidence": ["Technical keywords: RAG Triad (RAGAS / TruLens / DeepEval), Context Relevance/Precision, Faithfulness (claim-to-context entailment), Answer Relevance, Answer Correctness (vs ground truth).", "Explains evaluating each leg of the RAG pipeline separately so the judge distinguishes retrieval noise (low Context Precision) from hallucination (low Faithfulness) and off-topic answers (low Answer Relevance)."]}, {"id": "KP2", "description": "Design structured, deterministic judge prompts using atomic claim decomposition, Chain-of-Thought reasoning BEFORE scoring, and discrete integer/boolean scales.", "required": true, "acceptable_evidence": ["Technical keywords: claim extraction + per-claim verification, rationale-before-score (Pydantic JSON `reasoning` -> `verdict`), discrete 0/1 or 1–5 rubric, `temperature=0`.", "Explains instructing the judge LLM at `temperature=0` to first extract atomic claims from the answer, verify each claim against the retrieved context with step-by-step reasoning, and output a structured Pydantic JSON verdict rather than an arbitrary 0–100 float."]}, {"id": "KP3", "description": "Mitigate known LLM-judge biases (self-preference bias, verbosity bias, position bias) and calibrate against human SME labels.", "required": true, "acceptable_evidence": ["Technical keywords: cross-family judge model (e.g., GPT-4o judging Claude or vice versa), position swapping in pairwise evals, human alignment correlation (Cohen''s Kappa / Spearman rho).", "Explains using a different/stronger model family as the judge to avoid self-enhancement bias, randomizing candidate order in pairwise comparisons, and validating judge agreement (`Kappa > 0.80`) against a human-annotated calibration set."]}, {"id": "KP4", "description": "Run LLM-as-a-Judge both synchronously in CI/CD regression suites and asynchronously on sampled production traces.", "required": false, "acceptable_evidence": ["Technical keywords: offline CI/CD PR gate, asynchronous production trace sampling (e.g., 5–10% + 100% of low-confidence/negative-feedback traces), Langfuse score ingestion.", "Explains running full judge evaluations on golden datasets in CI and asynchronously scoring sampled production traces without adding latency to the user''s synchronous response."]}], "critical_failures": ["Asks the exact same model at `temperature=0.7` ''Rate your own answer from 1 to 10'' with no rubric, no retrieved-context comparison, and no human calibration."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you load, clean, chunk, embed, and store documents in the vector database?', '{"key_points": [{"id": "KP1", "description": "Stage 1 & 2 — Load and clean heterogeneous documents using layout-aware parsers while preserving tables and stripping noise/PII.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing (PyMuPDF / Unstructured / Docling / Textract), table-to-Markdown conversion, Unicode normalization (`NFKC`), boilerplate/header/footer removal, PII redaction.", "Explains extracting structured sections and converting tables into clean Markdown/HTML, normalizing whitespace/encoding, stripping repetitive page numbers/watermarks, and redacting sensitive PII."]}, {"id": "KP2", "description": "Stage 3 — Chunk documents along structural boundaries (`MarkdownHeaderTextSplitter` + `RecursiveCharacterTextSplitter`) with overlap and metadata injection.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchical/structural splitting, token-aware sizing (e.g., 400–600 tokens with 10–15% overlap), contextual breadcrumb header injection, intact table preservation.", "Explains splitting first by document headings/sections and then recursively by paragraph/sentence boundaries using the embedding model''s tokenizer, prepending the document title and section path to each chunk."]}, {"id": "KP3", "description": "Stage 4 — Compute dense and sparse embeddings in GPU-accelerated batches with content-hash deduplication.", "required": true, "acceptable_evidence": ["Technical keywords: SHA-256 chunk content hash (`doc_id + chunk_hash`), skip unchanged chunks, GPU batch encoding (`normalize_embeddings=True`), sparse BM25/SPLADE vectors.", "Explains computing a deterministic hash per chunk so unchanged chunks skip re-embedding on incremental updates, and batch-encoding new/modified chunks with L2 normalization."]}, {"id": "KP4", "description": "Stage 5 — Upsert vectors and indexed scalar metadata atomically into the vector database and prune deleted chunks.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic primary key (`{doc_id}_{chunk_idx}`), batch upsert, scalar metadata (`doc_id`, `version`, `acl_roles`, `effective_date`), stale chunk cleanup.", "Explains performing batched idempotent upserts into Milvus/PGVector/Chroma with full filterable metadata and deleting orphan chunks from older document versions."]}], "critical_failures": ["Uses `insert` with random UUIDs on every re-ingestion run without deleting or upserting over previous versions, polluting the vector DB with duplicate and stale chunks."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How did you manage conversation history, reranking, and query optimization in your deployed assistant?', '{"key_points": [{"id": "KP1", "description": "Manage multi-turn conversation history in Redis/Postgres using a hybrid sliding window (`last K turns`) plus rolling summary to bound token growth.", "required": true, "acceptable_evidence": ["Technical keywords: Redis session store (`session_id`, TTL), hybrid memory (verbatim last 4–6 turns + compressed summary of older turns), token budget enforcement.", "Explains storing raw turn history server-side in Redis and keeping the last $K$ turns verbatim for immediate coreference while asynchronously summarizing older turns so long conversations never overflow the context window."]}, {"id": "KP2", "description": "Optimize conversational queries via coreference resolution, standalone query rewriting, and multi-query decomposition before retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: history-aware query contextualization (pronoun/coreference resolution), sub-query decomposition, metadata filter extraction.", "Explains transforming ambiguous follow-ups (e.g., ''What is the penalty for violating it?'') using conversation history into a self-contained search query (''What is the penalty for violating the Section 404 wire transfer threshold policy?'') before hitting the vector/BM25 index."]}, {"id": "KP3", "description": "Rerank retrieved candidates against the rewritten standalone query using a Cross-Encoder and deduplicate across turns.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranking (`bge-reranker-large` / Cohere Rerank), top-N to top-K compression, ephemeral vs persistent context separation.", "Explains scoring candidate chunks against the resolved standalone query, keeping only the top $K$ chunks for the current turn (rather than permanently accumulating all retrieved chunks from every prior turn in the prompt history)."]}], "critical_failures": ["Embeds raw follow-up queries like ''How about for contractors?'' directly without resolving coreferences from conversation history.", "Appends all full retrieved document chunks from every previous turn permanently into the chat history, rapidly exhausting the context window."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you manage metadata and indexing strategies in your vector database to improve retrieval quality?', '{"key_points": [{"id": "KP1", "description": "Design a curated metadata taxonomy covering access control, temporal validity, structural hierarchy, and domain facets.", "required": true, "acceptable_evidence": ["Technical keywords: `tenant_id`, `allowed_roles`, `doc_type`, `department`, `effective_date` (int64 epoch), `is_latest` (bool), `section_path`, `parent_chunk_id`.", "Explains storing strongly typed scalar fields rather than unindexed free-form JSON strings so queries can deterministically filter by security scope, active version (`is_latest == True`), and date ranges."]}, {"id": "KP2", "description": "Configure physical partitioning (`partition_key` / namespaces) and scalar indexes (`INVERTED`, `BITMAP`, `B-Tree`/`GIN`) for fast pre-filtering.", "required": true, "acceptable_evidence": ["Technical keywords: physical partitioning by `tenant_id` or `domain`, scalar indexes (`BITMAP` for low-cardinality booleans/enums, `INVERTED`/`B-Tree` for IDs/timestamps), bitset pre-filtering.", "Explains combining physical partition pruning with scalar indexes so the vector engine constructs a valid candidate bitset in milliseconds before traversing the ANN graph."]}, {"id": "KP3", "description": "Select and tune the vector and lexical index structures (`HNSW` parameters `M`, `efConstruction`, `ef_search` + inverted BM25/GIN index).", "required": true, "acceptable_evidence": ["Technical keywords: HNSW (`M=16–32`, `efConstruction=200`, `ef_search=64–128`), filtered HNSW graph traversal, sparse inverted index.", "Explains tuning HNSW graph connectivity (`M`) so pre-filtered searches maintain high recall without disconnecting the proximity graph when selective metadata filters are applied."]}, {"id": "KP4", "description": "Combine deterministic metadata pre-filtering with LLM-assisted self-query filter extraction for explicit user constraints.", "required": false, "acceptable_evidence": ["Technical keywords: mandatory server-side RBAC filter + extracted domain filter (e.g., `year >= 2025 AND doc_type == ''SOP''`), fallback relaxation.", "Explains enforcing non-negotiable security filters in backend code while extracting optional user-specified filters (like year or product line) from the query."]}], "critical_failures": ["Stores dates as unparseable strings (`''Jan 5th, 25''`) instead of numeric timestamps/ISO dates, or omits scalar indexes on filtered fields causing full collection scans."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'BROAD', 210, 'How did you modularize and orchestrate components in your RAG or agent-based systems to ensure flexibility and scalability?', '{"key_points": [{"id": "KP1", "description": "Decouple core capabilities behind clean interfaces (`Protocol` / `ABC`) and Pydantic data contracts (Ports & Adapters pattern).", "required": true, "acceptable_evidence": ["Technical keywords: Python `Protocol` / `ABC` interfaces (`BaseEmbedder`, `BaseRetriever`, `BaseReranker`, `BaseLLM`, `BaseTool`), dependency injection, Pydantic state contracts.", "Explains defining strict input/output Pydantic schemas for each stage so swapping ChromaDB for Milvus, or OpenAI for Bedrock Claude, requires only a configuration change and adapter swap without touching orchestration logic."]}, {"id": "KP2", "description": "Orchestrate workflows declaratively as composable DAGs or stateful graphs (`LangGraph` `StateGraph` / `LCEL`).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph `StateGraph`, pure functional nodes (`state -> partial_state_update`), conditional routing edges, subgraphs, persistent checkpointers.", "Explains modeling each agent or RAG step as an isolated, unit-testable node operating on a typed `State` object, wired together via declarative edges and conditional routers."]}, {"id": "KP3", "description": "Execute independent sub-tasks concurrently (`asyncio.gather` / `RunnableParallel` / LangGraph `Send` API).", "required": true, "acceptable_evidence": ["Technical keywords: parallel fan-out/fan-in (`asyncio.gather`, `Send`), concurrent dense + sparse retrieval, parallel multi-agent sub-queries.", "Explains running independent operations (e.g., dense search + BM25 search + user profile lookup, or multi-agent sub-questions) concurrently to minimize end-to-end wall-clock latency."]}, {"id": "KP4", "description": "Separate deployment tiers by compute profile so I/O-bound orchestration, CPU-heavy parsing, and GPU-bound inference scale independently.", "required": true, "acceptable_evidence": ["Technical keywords: workload decomposition, stateless API/orchestrator pods (CPU), async ingestion worker pool (CPU/memory), dedicated embedding/reranker inference service (GPU).", "Explains scaling lightweight FastAPI/LangGraph orchestrator pods on CPU nodes via request concurrency while scaling GPU embedding/reranking services and queue-driven ingestion workers independently."]}, {"id": "KP5", "description": "Externalize prompts, model routing rules, and retrieval hyperparameters into versioned configuration.", "required": false, "acceptable_evidence": ["Technical keywords: externalized YAML/JSON config, Langfuse Prompt Registry, feature flags.", "Allows tuning top-K thresholds, temperatures, and prompt templates without redeploying container images."]}, {"id": "KP6", "description": "Enforce idempotency keys, circuit breakers, and dead-letter queues (DLQs) across asynchronous component boundaries.", "required": false, "acceptable_evidence": ["Technical keywords: idempotency key (`request_id` / `doc_hash`), tenacity retry with circuit breaker, SQS/Kafka Dead-Letter Queue (DLQ).", "Explains ensuring that retried agent tool calls or document ingestion jobs are idempotent and poison messages route cleanly to a DLQ."]}], "critical_failures": ["Writes a monolithic, tightly coupled script where document parsing, hardcoded vendor SDK calls, prompt strings, and HTTP serving live in a single class."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you perform chunking on large unstructured documents, and what strategies did you use to determine chunk size, overlap, and handling of different document types?', '{"key_points": [{"id": "KP1", "description": "Route documents to format-specific structural splitters (PDFs/manuals, tables, source code, Markdown/HTML, transcripts).", "required": true, "acceptable_evidence": ["Technical keywords: format-aware chunking router, layout/header splitting for PDFs/Docs, intact table blocks + summary embeddings, AST (`tree-sitter`) for code, speaker-turn windows for transcripts.", "Explains tailoring the splitter to the document modality: splitting policies/manuals by section headers, keeping tables intact as Markdown/HTML blocks (never slicing rows mid-table), and splitting code by AST function/class nodes."]}, {"id": "KP2", "description": "Explain the trade-off of `chunk_size` (e.g., 300–600 tokens) bounded by the embedding model''s `max_seq_length` and topic coherence.", "required": true, "acceptable_evidence": ["Technical keywords: tokenizer-based length measurement (`tiktoken` / `AutoTokenizer`), small chunks (high embedding specificity, missing context) vs large chunks (semantic dilution, context bloat), Parent-Child decoupling.", "Explains measuring chunk size in tokens (not characters), respecting the embedding model''s sequence limit, and using Parent-Child indexing (256-token child chunks for precise vector matching linked to 1024-token parent sections for LLM synthesis)."]}, {"id": "KP3", "description": "Calibrate `chunk_overlap` (10%–15%, e.g., 50–80 tokens) along sentence boundaries to prevent boundary context severance without causing duplicate crowding.", "required": true, "acceptable_evidence": ["Technical keywords: 10–15% sliding-window overlap, recursive separator hierarchy (`\\\\n\\\\n`, `\\\\n`, `. `, ` `), post-retrieval contiguous chunk merging.", "Explains why 10–15% overlap preserves cross-sentence continuity across split points while avoiding the index bloat and top-$K$ redundancy caused by excessive (>30%) overlap."]}, {"id": "KP4", "description": "Prepend hierarchical document/section breadcrumb headers to every chunk and validate parameters on a golden retrieval benchmark.", "required": true, "acceptable_evidence": ["Technical keywords: contextual header injection (`[Doc: X | Section: Y]`), empirical grid sweep (`Recall@5`, `NDCG@10`, `Faithfulness`).", "Explains injecting document title and section hierarchy into every chunk''s text before embedding and selecting final chunk size/overlap via offline retrieval evaluation."]}], "critical_failures": ["Applies a single blind fixed-character splitter (`text[i:i+1000]`) across PDFs, tables, and source code, slicing words, table rows, and functions in half."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you perform data chunking, and what strategies did you use to preserve semantic context?', '{"key_points": [{"id": "KP1", "description": "Preserve structural and sentence integrity using recursive/semantic boundary splitting (`\\\\n\\\\n` -> `\\\\n` -> sentence) and 10–15% overlap.", "required": true, "acceptable_evidence": ["Technical keywords: `RecursiveCharacterTextSplitter` / `SemanticChunker` (sentence embedding cosine dropoff), sentence boundary preservation, sliding-window overlap.", "Explains splitting at natural paragraph, heading, or semantic shift boundaries so coreferent sentences stay together."]}, {"id": "KP2", "description": "Prepend contextual document/section headers (or Anthropic-style Contextual Retrieval summaries) to every chunk before embedding.", "required": true, "acceptable_evidence": ["Technical keywords: contextual header prepending (`Document Title > H1 > H2`), Contextual Retrieval (situating summary prefix), pronoun/entity disambiguation.", "Explains solving the ''orphan pronoun/clause'' problem (e.g., a chunk stating ''The fee increases to 3% after 90 days'' without naming the product) by prepending the document title, product name, and section breadcrumb directly into the embedded text."]}, {"id": "KP3", "description": "Use Parent-Child (Small-to-Big) or Sentence-Window expansion so retrieval matches fine-grained vectors while generation receives full surrounding context.", "required": true, "acceptable_evidence": ["Technical keywords: `ParentDocumentRetriever` / `SentenceWindowNodeParser`, child-vector search -> parent-context synthesis, contiguous neighbor merging.", "Explains indexing small, focused child chunks for high-precision vector similarity while retrieving the parent section or $\\\\pm 2$ surrounding paragraphs for the LLM prompt."]}], "critical_failures": ["Embeds isolated middle paragraphs stripped of their document title and section header, making them unretrievable when the user''s query mentions the document or entity name."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you structure and store embeddings in your vector database, and how were they queried during runtime?', '{"key_points": [{"id": "KP1", "description": "Define the vector database record schema: deterministic primary key, dense vector (`float32`/`float16`), sparse vector, chunk text/parent pointer, and typed scalar metadata.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic ID (`{doc_id}_{chunk_idx}`), `dense_vector` (L2-normalized), `sparse_vector`, payload (`text`, `parent_id`, `doc_id`, `acl_roles`, `effective_date`, `embedding_model_id`).", "Explains structuring each record with an idempotent primary key, normalized vector(s), and strongly typed scalar metadata fields."]}, {"id": "KP2", "description": "Configure storage partitioning (`tenant_id` / namespace), ANN index (`HNSW` with Inner Product/Cosine), and scalar metadata indexes.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW index (`M`, `efConstruction`), Inner Product (`IP`) on unit vectors, scalar bitset indexes (`BITMAP`/`INVERTED`), tenant partitioning.", "Explains building an HNSW index with Inner Product (fastest metric on L2-normalized vectors) alongside scalar indexes on filterable attributes."]}, {"id": "KP3", "description": "Execute runtime queries: encode query vector, apply mandatory RBAC/metadata pre-filter, run hybrid ANN+BM25 search (`ef_search`), project required `output_fields`, and rerank.", "required": true, "acceptable_evidence": ["Technical keywords: query embedding + L2 norm, pre-filter `expr`, `ef_search` tuning, `output_fields` projection, RRF + Cross-Encoder reranking.", "Walks through the runtime path: encoding the query with the identical model, applying server-side ACL pre-filters, retrieving top-$N$ candidates via hybrid search, and reranking down to top-$K$."]}], "critical_failures": ["Stores vectors without metadata or parent document references, or mismatches the runtime distance metric (`L2` vs `IP`/`Cosine`) against how the index was constructed."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How did you structure the workflow for your agents, including retrieval, reasoning, validation, and response generation?', '{"key_points": [{"id": "KP1", "description": "Stage 1 (Reasoning & Planning) — Analyze intent, decompose complex queries into sub-tasks, and route to appropriate tools/retrievers.", "required": true, "acceptable_evidence": ["Technical keywords: Planner/Router node, query decomposition, tool/source selection (Vector RAG vs Text-to-SQL vs REST API), typed `AgentState`.", "Explains starting the `StateGraph` with a planning/routing step that resolves conversation history, breaks multi-part questions into sub-queries, and selects the required retrieval or analytical tools."]}, {"id": "KP2", "description": "Stage 2 (Retrieval & Tool Execution) — Execute parallel hybrid retrieval and schema-validated tool calls.", "required": true, "acceptable_evidence": ["Technical keywords: parallel sub-query execution, hybrid vector+BM25 retrieval + reranking, Pydantic-validated tool execution, sandboxing & timeouts.", "Explains fetching context from vector stores and structured databases/APIs concurrently with strict schema validation and RBAC filters."]}, {"id": "KP3", "description": "Stage 3 (Validation & Self-Correction Loop) — Grade retrieved context relevance and verify SQL/tool outputs before synthesis (Bounded Corrective RAG).", "required": true, "acceptable_evidence": ["Technical keywords: Document Grader / Critic node, query rewrite retry loop, `retry_count < max_retries` (e.g., max 2), SQL/output verification.", "Explains evaluating whether retrieved evidence actually answers every sub-question; if relevance is low and `retry_count < 2`, the graph loops back to rewrite/broaden the query rather than hallucinating."]}, {"id": "KP4", "description": "Stage 4 (Grounded Response Generation & Post-Check) — Synthesize citation-backed answers and verify faithfulness/compliance.", "required": true, "acceptable_evidence": ["Technical keywords: citation-anchored synthesis, faithfulness/hallucination self-check, graceful abstention on exhausted retries.", "Explains generating the final response strictly from validated evidence with inline citations, or returning a transparent partial/abstention response if evidence remains missing after bounded retries."]}], "critical_failures": ["Creates an unbounded validation loop without a `max_retries` counter, risking infinite agent loops and runaway token costs when information does not exist in the corpus."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 210, 'How did you use LangChain for orchestration, and what were the roles of the query understanding, retrieval, and synthesis chains?', '{"key_points": [{"id": "KP1", "description": "Compose the pipeline using LangChain Expression Language (LCEL: `RunnableSequence`, `RunnableParallel`, `RunnableLambda`, `.with_fallbacks()`) for async streaming and observability.", "required": true, "acceptable_evidence": ["Technical keywords: LCEL pipe syntax (`|`), `RunnableParallel`, `RunnablePassthrough.assign()`, `.with_retry()`, `.with_fallbacks()`, native `astream_events`.", "Explains why declarative LCEL runnables are used instead of legacy `Chain` subclasses: automatic async batching, token-by-token streaming, parallel branch execution, declarative fallbacks, and seamless LangSmith/Langfuse trace spans."]}, {"id": "KP2", "description": "Detail the **Query Understanding Chain**: coreference resolution, intent classification, sub-query expansion, and structured metadata filter extraction.", "required": true, "acceptable_evidence": ["Technical keywords: `.with_structured_output(QueryPlan)`, standalone query rewriting, multi-query generation, self-query metadata filter extraction.", "Explains using a fast LLM call with `.with_structured_output()` to rewrite conversational follow-ups into standalone search queries, classify intent, and extract explicit metadata filters (e.g., `doc_type`, `date_range`)."]}, {"id": "KP3", "description": "Detail the **Retrieval & Compression Chain**: parallel hybrid search (`EnsembleRetriever`), RBAC pre-filtering, Cross-Encoder reranking (`ContextualCompressionRetriever`), and parent-chunk resolution.", "required": true, "acceptable_evidence": ["Technical keywords: `EnsembleRetriever` (BM25 + Vector RRF), `ContextualCompressionRetriever` + `CrossEncoderReranker`, chunk deduplication & XML formatting.", "Explains executing dense and sparse retrievers in parallel via `RunnableParallel`/`EnsembleRetriever`, compressing the top-50 candidates to top-5 with a cross-encoder reranker, and formatting chunks with XML source tags."]}, {"id": "KP4", "description": "Detail the **Synthesis Chain**: prompt assembly, token budget enforcement, citation-grounded generation, and fallback/abstention handling.", "required": true, "acceptable_evidence": ["Technical keywords: `ChatPromptTemplate`, citation-enforced system prompt, model fallback (`.with_fallbacks([backup_llm])`), structured/streaming output.", "Explains combining the formatted context, conversation history, and user query into `ChatPromptTemplate`, streaming the grounded answer with inline `[source_id]` citations, and configuring `.with_fallbacks()` for secondary LLM provider failover."]}, {"id": "KP5", "description": "Add a post-synthesis Verification / Guardrail Runnable to validate citation accuracy and schema compliance before completing the stream.", "required": false, "acceptable_evidence": ["Technical keywords: post-generation guardrail runnable, citation existence check, fallback abstention trigger.", "Explains verifying that every cited `[doc_id]` in the generated output actually exists in the retrieved context set."]}, {"id": "KP6", "description": "Instrument LCEL chains with custom callbacks/tags (`RunnableConfig`) for granular per-chain latency and token attribution.", "required": false, "acceptable_evidence": ["Technical keywords: `RunnableConfig(callbacks=[...], tags=[...], metadata={...})`, per-chain token/latency breakdown.", "Explains passing trace metadata and tags through `RunnableConfig` to monitor Query Understanding, Retrieval, and Synthesis chain latencies independently."]}], "critical_failures": ["Passively pipes raw user chat messages straight into a single vector store lookup without a query understanding chain or reranking compression stage."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you use metadata (such as document version, type, or category) to improve retrieval accuracy?', '{"key_points": [{"id": "KP1", "description": "Eliminate stale/deprecated hallucinations using version and temporal metadata (`is_latest == True`, `effective_date <= now < expiry_date`).", "required": true, "acceptable_evidence": ["Technical keywords: `is_latest` boolean flag, `doc_version`, `effective_date` / `superseded_by`, temporal pre-filtering.", "Explains that updated policies (e.g., 2024 vs 2026 remote work policy) have nearly identical semantic embeddings; filtering `is_latest == True` by default ensures superseded documents never pollute the top-$K$ results unless the user explicitly asks for historical versions."]}, {"id": "KP2", "description": "Prune the search space using `document_type` and `category`/`department` pre-filters (via intent routing or self-query extraction).", "required": true, "acceptable_evidence": ["Technical keywords: `doc_type` (`SOP`, `API_Spec`, `Runbook`, `Contract`), `category`/`department` scoping, search space reduction, precision@K boost.", "Explains narrowing candidate evaluation to matching categories (e.g., restricting an engineering outage query to `doc_type IN [''Runbook'', ''Postmortem'']`), preventing false-positive matches from marketing or HR documents."]}, {"id": "KP3", "description": "Inject metadata headers into both the embedded chunk text and the LLM prompt context block for disambiguation and recency-aware synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: metadata-prefixed embeddings (`[Category: HR | Version: v3.2 | Date: 2026-01]`), metadata-aware reranking/recency decay, LLM source header visibility.", "Explains prepending key metadata to the chunk text prior to embedding AND exposing `version`/`effective_date` in the prompt''s `<source>` tags so the LLM can explicitly cite document versions and resolve temporal precedence."]}], "critical_failures": ["Stores multiple versions of the same document in the vector index without an `is_latest` or `effective_date` filter, causing the LLM to blend contradictory rules from old and new versions."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'BROAD', 210, 'How did you use models like BERT and Anthropic Claude within your pipeline for embeddings and text generation?', '{"key_points": [{"id": "KP1", "description": "Contrast the architectural strengths of BERT-family bidirectional encoders ($O(1)$ pooled representation / fast classification) vs Anthropic Claude causal decoders (long-context reasoning & synthesis).", "required": true, "acceptable_evidence": ["Technical keywords: bidirectional self-attention encoder (BERT/RoBERTa/DeBERTa/BGE) vs causal autoregressive decoder (Claude 3.5 Sonnet / Haiku), task-to-architecture alignment.", "Explains that encoder models attend bidirectionally across all tokens simultaneously to produce dense representations and classification logits in a single 5–20ms forward pass, whereas causal LLMs like Claude generate tokens sequentially with strong multi-step reasoning and 200K-token context capacity."]}, {"id": "KP2", "description": "Use BERT-based Bi-Encoders (`SentenceTransformers` / `BGE` / `MiniLM`) for dense vector embeddings and BERT Cross-Encoders for second-stage reranking.", "required": true, "acceptable_evidence": ["Technical keywords: Siamese Bi-Encoder (contrastive InfoNCE loss, independent chunk/query encoding), Cross-Encoder reranker (`[CLS] query [SEP] chunk [SEP]` full cross-attention).", "Explains using a fine-tuned BERT Bi-Encoder to index millions of chunks into the vector store for sub-20ms ANN search, and a BERT Cross-Encoder to jointly score the top-50 candidate `(query, chunk)` pairs down to top-5."]}, {"id": "KP3", "description": "Use lightweight BERT/DeBERTa classifiers as fast pre/post-generation guardrails (intent routing, PII/NER detection, prompt-injection screening, NLI faithfulness).", "required": true, "acceptable_evidence": ["Technical keywords: token classification (NER/Presidio PII redaction), sequence classification (intent router, prompt injection detector), DeBERTa NLI entailment scorer.", "Explains offloading high-frequency classification and PII scrubbing to <15ms BERT models so expensive LLM calls are protected and filtered at minimal cost."]}, {"id": "KP4", "description": "Use Anthropic Claude (Sonnet for complex synthesis/tool-use, Haiku for fast query rewriting) with XML-structured prompts and prompt caching.", "required": true, "acceptable_evidence": ["Technical keywords: Claude 3.5 Sonnet vs Haiku model tiering, XML tags (`<documents>`, `<instructions>`, `<quotes>`), Anthropic Prompt Caching (`cache_control`), structured tool use.", "Explains structuring retrieved passages in XML `<document>` tags (which Claude is specifically trained to respect), instructing Claude to extract verbatim `<quotes>` before synthesizing the answer, and routing simpler query-rewriting steps to Claude Haiku."]}, {"id": "KP5", "description": "Optimize inference latency and throughput using ONNX Runtime / TensorRT quantization (`INT8`/`FP16`) for BERT and prompt caching for Claude.", "required": false, "acceptable_evidence": ["Technical keywords: ONNX Runtime / TensorRT `FP16`/`INT8` dynamic quantization, dynamic batching (Triton Inference Server), Claude prompt caching.", "Explains quantizing BERT embedding/reranker models to `FP16`/`INT8` on ONNX Runtime for 3x–4x speedup and caching long static system instructions in Claude."]}, {"id": "KP6", "description": "Fine-tune BERT Bi-Encoder/Cross-Encoder weights on domain hard negatives (MultipleNegativesRankingLoss) while keeping Claude zero/few-shot.", "required": false, "acceptable_evidence": ["Technical keywords: `MultipleNegativesRankingLoss` (InfoNCE), hard-negative mining from BM25, domain vocabulary adaptation.", "Explains why adapting the small BERT retriever/reranker on domain hard negatives yields massive RAG accuracy gains without the cost or catastrophic forgetting of fine-tuning the frontier generator LLM."]}], "critical_failures": ["Uses raw un-finetuned `bert-base-uncased` `[CLS]` vectors for semantic search (which produces poor anisotropic similarity compared to Siamese Sentence-BERT/BGE bi-encoders), or uses a heavy generative LLM for every millisecond-level PII/routing check."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did your RAG project evolve from POC to production, and what improvements were made in each phase?', '{"key_points": [{"id": "KP1", "description": "Phase 1 (POC Baseline) — Rapid validation with fixed-size chunking, single dense vector search, and basic prompt stuffing, plus identifying initial failure modes.", "required": true, "acceptable_evidence": ["Technical keywords: Naive RAG baseline, fixed-size character splitting, dense-only ANN, failure discovery (missed exact keywords, broken tables, stale docs, high latency).", "Explains building a minimal viable pipeline on a small static document set to prove business value, then building a golden evaluation dataset to quantify why naive RAG failed on complex queries."]}, {"id": "KP2", "description": "Phase 2 (Retrieval & Context Engineering) — Upgrade to layout-aware/parent-child chunking, hybrid BM25 + dense RRF search, Cross-Encoder reranking, and query rewriting.", "required": true, "acceptable_evidence": ["Technical keywords: layout/table-aware parsing, contextual header injection, Hybrid Search (BM25 + Dense + RRF), Cross-Encoder reranker, conversational query rewriting.", "Details the concrete retrieval engineering upgrades that boosted `Recall@5` and `Faithfulness` on the golden benchmark."]}, {"id": "KP3", "description": "Phase 3 (Security, Scale & Reliability) — Event-driven incremental ingestion, RBAC pre-filtering, version lifecycle (`is_latest`), SSE streaming, and semantic caching.", "required": true, "acceptable_evidence": ["Technical keywords: async SQS/Celery ingestion with SHA-256 deduplication, JWT RBAC metadata pre-filtering, SSE streaming, Redis embedding/semantic cache, LLM fallback routing.", "Explains hardening the system for concurrent enterprise users: enforcing document permissions, automating incremental index updates, and cutting p95 latency and token cost."]}, {"id": "KP4", "description": "Phase 4 (LLMOps & Continuous Governance) — CI/CD evaluation gates (RAGAS), distributed tracing (Langfuse/Prometheus), guardrails, and user feedback flywheels.", "required": true, "acceptable_evidence": ["Technical keywords: automated CI/CD regression gate, Langfuse/Prometheus/Grafana observability, PII/injection guardrails, human-in-the-loop feedback curation.", "Explains operationalizing continuous monitoring, automated regression blocking in CI, and feeding production thumbs-down traces back into the golden test suite."]}], "critical_failures": ["Treats moving from POC to production as simply putting a Docker container around a naive notebook without addressing incremental ingestion, RBAC security, hybrid retrieval/reranking, evaluation gates, or observability."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did your RAG-based system reduce call handling time, and what components were involved in achieving this improvement?', '{"key_points": [{"id": "KP1", "description": "Target the two primary drivers of Average Handle Time (AHT): live in-call knowledge lookup latency (hold time) and post-call After-Call Work (ACW) wrap-up notes.", "required": true, "acceptable_evidence": ["Technical keywords: Average Handle Time (AHT = Talk/Hold Time + After-Call Work ACW), First Contact Resolution (FCR), manual knowledge-base search elimination.", "Explains that contact center reps previously placed callers on hold for 2–4 minutes searching fragmented PDFs/portals and spent another 2–3 minutes typing disposition notes after hang-up."]}, {"id": "KP2", "description": "Architect the low-latency in-call RAG copilot: CRM context injection, semantic/embedding caching, hybrid search + reranking, and sub-second SSE streaming.", "required": true, "acceptable_evidence": ["Technical keywords: real-time transcript/query trigger, CRM metadata pre-filtering (customer tier, state, plan ID), Redis semantic cache, Hybrid Search + Cross-Encoder, SSE bulleted answer cards.", "Explains pre-filtering the knowledge base automatically using the caller''s active CRM profile (state/product plan) and streaming concise, step-by-step resolution bullets with clickable policy citations in `<1.5s` TTFT."]}, {"id": "KP3", "description": "Automate After-Call Work (ACW) via structured call summarization, disposition code classification, and one-click CRM write-back.", "required": true, "acceptable_evidence": ["Technical keywords: structured JSON call summary (`issue`, `resolution_steps`, `policy_cited`, `follow_up_action`, `disposition_code`), rep one-click review/approve.", "Explains generating a schema-validated call summary and disposition tag at call completion so the rep reviews and saves in 15 seconds instead of typing from scratch."]}, {"id": "KP4", "description": "Quantify operational and quality guardrails (AHT reduction %, FCR lift, compliance script adherence, zero hallucinated policy promises).", "required": false, "acceptable_evidence": ["Technical keywords: AHT reduction (e.g., 25–40%), FCR improvement, new-hire ramp time reduction, citation verification.", "Connects the architecture to measurable call-center KPIs while ensuring the copilot never fabricates refund/coverage rules."]}], "critical_failures": ["Returns 800-word wall-of-text essays after a 12-second delay during a live phone call, which is unusable for an agent speaking to a customer in real time."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did your system integrate with internal data sources such as PDFs and provider data for retrieval tasks?', '{"key_points": [{"id": "KP1", "description": "Ingest unstructured PDFs (benefit manuals, clinical/coverage policies, contracts) via event-driven layout-aware parsing and hierarchical chunking.", "required": true, "acceptable_evidence": ["Technical keywords: S3/SharePoint connectors, layout-aware PDF/OCR extraction (Document AI / Textract / Docling), intact benefit/fee table preservation, metadata tagging (`plan_id`, `effective_date`).", "Explains extracting multi-column PDF text and complex coverage tables without losing row/column headers, chunking by policy section, and indexing into the vector + BM25 store."]}, {"id": "KP2", "description": "Integrate structured provider data (NPI, specialty, network status, location, live availability) via SQL/REST API tools or CDC-synced search indexes.", "required": true, "acceptable_evidence": ["Technical keywords: structured provider directory (SQL/PostgreSQL, FHIR/REST APIs, OpenSearch), exact key lookups (NPI, taxonomy code, ZIP/geo-distance, `in_network` boolean), CDC sync.", "Explains that rapidly changing, high-cardinality structured records (millions of provider rows, live network status, geo-coordinates) should be queried via parameterized SQL/API tools or structured search filters rather than dumped as naive unstructured text chunks."]}, {"id": "KP3", "description": "Orchestrate hybrid query routing that joins structured provider lookups with unstructured PDF policy rules.", "required": true, "acceptable_evidence": ["Technical keywords: intent router / query decomposer, parallel tool + RAG execution, cross-source entity linking (`provider_network_tier` + `plan_coverage_pdf`).", "Walks through answering compound queries (e.g., ''Is Dr. Smith in-network for Plan Gold and does an MRI require prior authorization?'') by querying the structured provider API/DB for Dr. Smith''s network status while retrieving Plan Gold''s prior-auth PDF section via RAG."]}, {"id": "KP4", "description": "Enforce HIPAA/PII security, data freshness SLAs, and source-attributed citations across both data planes.", "required": true, "acceptable_evidence": ["Technical keywords: PHI/PII encryption & redaction, CDC/webhook freshness, dual provenance (DB record timestamp + PDF page citation).", "Ensures every synthesized answer cites both the live provider directory record and the exact policy PDF page."]}], "critical_failures": ["Converts a 5-million-row relational provider database into static text chunks in a vector store, leading to stale network statuses, broken geo-radius filtering, and poor exact-ID recall."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'How did your team structure responsibilities across MLOps, ML, RAG, and agent development tasks?', '{"key_points": [{"id": "KP1", "description": "Define clear ownership across four core functional pillars: (1) Data & RAG Ingestion/Retrieval, (2) Agent & Orchestration Engineering, (3) ML/Model Optimization & Evaluation, and (4) MLOps & Cloud Platform.", "required": true, "acceptable_evidence": ["Technical keywords: Data/RAG pillar (parsers, chunking, vector DBs, hybrid search), Agent/App pillar (LangGraph orchestration, tool APIs, SSE serving), ML pillar (embedding/reranker fine-tuning, LLM-as-a-judge), MLOps pillar (EKS, CI/CD, Langfuse/Prometheus, security).", "Articulates how responsibilities are specialized without creating rigid silos."]}, {"id": "KP2", "description": "Establish clean technical contracts and interface boundaries (Pydantic schemas, OpenAPI specs, shared evaluation datasets) between sub-teams.", "required": true, "acceptable_evidence": ["Technical keywords: contract-first interfaces (`RetrieverProtocol`, `ToolSchema`, `EvaluationDataset`), golden benchmark handoffs, versioned prompt/model registries.", "Explains how the RAG team exposes a versioned retrieval interface consumed by Agent engineers, while MLOps provides self-service deployment pipelines and automated CI evaluation runners."]}, {"id": "KP3", "description": "Drive shared quality rituals: joint trace-review triage, unified golden dataset curation with SMEs, and shared production SLAs.", "required": true, "acceptable_evidence": ["Technical keywords: weekly failure-trace review, shared KPIs (`Recall@K`, `Faithfulness`, `p95 latency`, `cost/query`), cross-functional on-call rotation.", "Explains preventing finger-pointing between retrieval, prompt/agent, and infra engineers by reviewing Langfuse failure traces together and gating all PRs on a unified evaluation suite."]}], "critical_failures": ["Describes a siloed ''throw-it-over-the-wall'' workflow where data scientists build notebooks with no production contracts, evaluation suites, or shared observability with platform/application engineers."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How do agents perform reasoning, planning, and tool calling, and what advantages do they provide over retrieval-only systems?', '{"key_points": [{"id": "KP1", "description": "Explain how agents perform **Planning** and **Reasoning** (task decomposition, ReAct `Thought -> Action -> Observation` loops, Plan-and-Execute, reflection).", "required": true, "acceptable_evidence": ["Technical keywords: ReAct loop, Plan-and-Execute / task decomposition DAG, dynamic state evaluation, self-reflection / error recovery.", "Explains how an agent breaks a complex goal into ordered or parallel sub-goals, reasons over intermediate observations, and dynamically adjusts its plan when a step returns incomplete data or an error."]}, {"id": "KP2", "description": "Explain the mechanics of **Tool Calling**: JSON Schema / Pydantic tool definitions, LLM structured argument emission, deterministic runtime execution, and observation feedback.", "required": true, "acceptable_evidence": ["Technical keywords: JSON Schema / Pydantic tool binding (`bind_tools`), `tool_calls` payload (`name`, `arguments`, `tool_call_id`), deterministic host execution, `ToolMessage` observation.", "Clarifies that the LLM does not execute code directly; it emits a structured `tool_call` JSON object matching a registered schema, the application runtime validates and executes the function (SQL, REST API, calculator, vector search), and feeds the result back as a `ToolMessage`."]}, {"id": "KP3", "description": "Contrast key advantages over static retrieval-only RAG: multi-hop iterative retrieval, deterministic computation, live transactional API access, and controlled side effects.", "required": true, "acceptable_evidence": ["Technical keywords: iterative query refinement (Corrective RAG), live transactional state (SQL/CRM APIs), exact math/code execution, workflow actions (creating tickets/PRs).", "Explains that retrieval-only RAG is limited to a single read pass over static indexed text, whereas agents can iteratively reformulate searches, combine unstructured docs with live SQL/APIs, perform exact math, and execute approved actions."]}, {"id": "KP4", "description": "Note the engineering trade-offs and guardrails required for agents (higher latency/cost, `max_iterations` caps, RBAC tool permissions, HITL approval).", "required": true, "acceptable_evidence": ["Technical keywords: multi-turn latency & token multiplication, `max_iterations` circuit breaker, least-privilege tool scoping, human-in-the-loop (HITL) approval gates.", "Balances the advantages by noting that agents require strict iteration bounds, deterministic schema validation, and HITL gates for state-mutating tools."]}], "critical_failures": ["Believes the LLM itself executes external API or database calls inside its neural weights rather than emitting structured tool-call parameters executed by the host runtime."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How do chunking, embedding strategies, and context window limitations impact retrieval quality in a RAG pipeline?', '{"key_points": [{"id": "KP1", "description": "Analyze how **chunking strategy** governs the trade-off between embedding specificity and context completeness.", "required": true, "acceptable_evidence": ["Technical keywords: micro-chunks (missing surrounding context/antecedents) vs macro-chunks (multi-topic vector dilution/averaging), boundary severance, Parent-Child resolution.", "Explains that overly small chunks lose entity/conditional context needed for accurate generation, while overly large chunks average multiple topics into a single noisy embedding vector that fails to match specific queries."]}, {"id": "KP2", "description": "Analyze how **embedding strategies** (sequence length cap, domain alignment, dense vs hybrid sparse+dense) bound maximum achievable recall.", "required": true, "acceptable_evidence": ["Technical keywords: `max_seq_length` silent truncation, out-of-domain vocabulary gap (acronyms, codes, jargon), dense + sparse BM25 hybrid retrieval, contextual header prefixes.", "Explains that if chunk tokens exceed the embedding model''s `max_seq_length`, tail content is silently dropped from the vector, and pure dense embeddings miss exact domain identifiers unless paired with BM25/SPLADE and contextual headers."]}, {"id": "KP3", "description": "Analyze **context window limitations**: ''Lost in the Middle'' attention degradation, distractor-induced hallucinations, and TTFT/cost scaling.", "required": true, "acceptable_evidence": ["Technical keywords: nominal vs effective context window, U-shaped attention curve (''Lost in the Middle''), distractor noise ratio, quadratic/linear prefill latency & token cost.", "Explains that even with 128K–200K context windows, stuffing 50 un-reranked chunks degrades reasoning accuracy on middle passages, introduces conflicting distractors, and inflates Time-to-First-Token (TTFT) and API cost."]}, {"id": "KP4", "description": "Synthesize how the three stages must be co-designed (token-aligned child chunks -> hybrid retrieval -> Cross-Encoder reranking -> boundary-ordered parent context).", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end co-design, child-chunk indexing (`<= max_seq_length`) + parent-chunk expansion, Cross-Encoder compression to top 5–8, edge-weighted prompt ordering.", "Demonstrates aligning chunk token counts to the embedder, retrieving broadly via hybrid search, reranking tightly to top-$K$ to protect the LLM''s effective context window, and placing top-ranked evidence at the start/end of the context block."]}], "critical_failures": ["Claims that modern 128K/200K LLM context windows make chunking quality and reranking obsolete, ignoring ''Lost in the Middle'' accuracy degradation, distractor hallucinations, and latency/cost."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'How do embeddings enable semantic search, and why are they more effective than traditional keyword-based approaches?', '{"key_points": [{"id": "KP1", "description": "Explain how embedding models map text into a continuous high-dimensional vector space ($\\\\mathbb{R}^d$) where geometric proximity reflects semantic meaning.", "required": true, "acceptable_evidence": ["Technical keywords: dense vector representation (`R^d`, e.g., 384–1536 dimensions), contrastive training (bi-encoder), cosine similarity / inner product / L2 distance, ANN search (HNSW).", "Explains that neural embedding models trained via contrastive learning project sentences/passages with similar meaning close together in vector space so relevance can be computed via cosine similarity ($\\\\frac{A \\\\cdot B}{\\\\|A\\\\| \\\\|B\\\\|}$)."]}, {"id": "KP2", "description": "Explain why semantic embeddings outperform keyword search (BM25/TF-IDF) on synonyms, paraphrases, polysemy, and cross-lingual queries.", "required": true, "acceptable_evidence": ["Technical keywords: vocabulary mismatch problem, synonym & paraphrase matching, contextual polysemy disambiguation (''apple fruit'' vs ''Apple stock'').", "Provides a concrete example showing that a query for `''how to terminate my subscription''` retrieves a document titled `''Account cancellation policy''` via vector similarity even with zero overlapping keywords."]}, {"id": "KP3", "description": "Note the complementary limitation of pure embeddings on exact identifiers (part numbers, error codes, rare proper nouns) and why production systems use Hybrid Search.", "required": false, "acceptable_evidence": ["Technical keywords: exact lexical match weakness (SKUs, error codes, UUIDs), Hybrid Search (Dense Embeddings + Sparse BM25).", "Demonstrates production maturity by noting that while embeddings dominate conceptual search, combining them with BM25 handles exact alphanumeric codes."]}], "critical_failures": ["Cannot explain how similarity is measured in vector space (cosine similarity / dot product / Euclidean distance) or claims embeddings rely on exact word-stem matching."]}', 1);
